**Description:**

This Terraform configuration sets up a Route 53 query logging configuration that sends DNS query logs to a CloudWatch Logs group. It creates a CloudWatch Logs group, a CloudWatch Logs resource policy to allow Route 53 to write logs, and configures a Route 53 hosted zone with query logging enabled. The hosted zone is named "primary", the CloudWatch Logs group is named "aws_route53_example_com", and the resource policy is named "route53-query-logging-policy".

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "zone_name" {
  description = "The name of the Route 53 hosted zone."
  default     = "primary"
}

variable "log_group_name" {
  description = "The name of the CloudWatch Logs group."
  default     = "aws_route53_example_com"
}

variable "policy_name" {
  description = "The name of the CloudWatch Logs resource policy."
  default     = "route53-query-logging-policy"
}

resource "aws_cloudwatch_log_group" "route53_log_group" {
  name = var.log_group_name
  retention_in_days = 30
}

resource "aws_cloudwatch_log_resource_policy" "route53_log_policy" {
  name   = var.policy_name
  policy = jsonencode({
    "version" = "2012-10-17"
    "statement" = [{
      "effect"     = "Allow"
      "principal"  = "*"
      "action"     = ["logs:PutLogEvents", "logs:DescribeLogStreams"]
      "resource"   = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${var.log_group_name}:*"
    }]
  })
}

resource "aws_route53_zone" "primary_zone" {
  name = var.zone_name
}

resource "aws_route53_query_logging_config" "query_logging" {
  zone_id = aws_route53_zone.primary_zone.id
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.route53_log_group.arn
}
```

