**Description:**  
This Terraform configuration creates a Route 53 hosted zone and associates it with a VPC. It includes a valid AWS provider configuration, defines a hosted zone, and sets up a VPC with a private subnet to demonstrate the association. The configuration uses default values for variables where necessary and ensures all resources are declared and properly referenced.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.1.0/24"
}

resource "aws_vpc" "example_vpc" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "example_subnet" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = "us-east-1a"
  tags = {
    Name = "example-subnet"
  }
}

resource "aws_route53_zone" "example_zone" {
  name = "example.com"
}

resource "aws_route53_zone_association" "example_association" {
  zone_id      = aws_route53_zone.example_zone.id
  vpc_id       = aws_vpc.example_vpc.id
  vpc_region   = "us-east-1"
  private      = true
  subnet_ids   = [aws_subnet.example_subnet.id]
}
