**Description:**

This Terraform configuration sets up an AWS Elastic Load Balancer (ELB) and a Route 53 record that points to the ELB. The Route 53 hosted zone is named "primary", and the ELB is named "main". The configuration includes:

- A VPC with a default CIDR block.
- A security group allowing HTTP traffic.
- A launch configuration for a simple EC2 instance.
- A load balancer (Classic ELB) with a listener on port 80.
- A Route 53 hosted zone named "primary".
- A Route 53 record that points to the ELB's DNS name.

All resources are created in the `us-east-1` region. Default values are provided for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "elb_name" {
  default = "main"
}

variable "zone_name" {
  default = "primary"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "main" {
  name        = "elb-security-group"
  description = "Allow HTTP traffic to ELB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_configuration" "main" {
  name          = "elb-launch-config"
  image_id      = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
  instance_type = "t2.micro"
  security_groups = [aws_security_group.main.id]
}

resource "aws_elb" "main" {
  name = var.elb_name
  subnets = [aws_subnet.main.id]
  security_groups = [aws_security_group.main.id]

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    port     = 80
    protocol = "HTTP"
    timeout  = 3
    interval = 30
    healthy_threshold = 2
    unhealthy_threshold = 5
  }
}

resource "aws_route53_zone" "primary" {
  name = var.zone_name
}

resource "aws_route53_record" "elb" {
  zone_id = aws_route53_zone.primary.id
  name    = var.elb_name
  type    = "A"
  ttl     = 300
  records = [aws_elb.main.dns_name]
}
```

