**Description of the Terraform Program:**

This Terraform configuration sets up two AWS Route 53 private and public hosted zones, each associated with a separate RDS database instance. The private zone routes internal users to an internal RDS instance, while the public zone routes external users to a publicly accessible RDS instance. A subnet group named "main" is created to organize the subnets for the RDS instances. The configuration includes:

- Two Route 53 hosted zones: `private` and `public`.
- Two RDS instances: one internal (private subnet) and one public (public subnet).
- A subnet group named `main` that includes both subnets.
- IAM roles and policies to allow RDS to be accessed by the instances.
- Default values for variables to ensure the configuration is deployable without additional input.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the subnets."
  default     = "vpc-12345678"
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "public_subnet_ids" {
  description = "List of public subnet IDs."
  default     = ["subnet-23456789", "subnet-98765432"]
}

variable "rds_instance_class" {
  description = "The class of the RDS instance."
  default     = "db.t3.micro"
}

variable "rds_engine" {
  description = "The engine for the RDS instance."
  default     = "mysql"
}

variable "rds_engine_version" {
  description = "The engine version for the RDS instance."
  default     = "8.0"
}

variable "rds_db_name" {
  description = "The name of the database."
  default     = "mydb"
}

variable "rds_username" {
  description = "The username for the RDS instance."
  default     = "admin"
}

variable "rds_password" {
  description = "The password for the RDS instance."
  default     = "securepassword"
}

resource "aws_route53_zone" "private" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public" {
  name = "public.example.com"
}

resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = [var.private_subnet_ids, var.public_subnet_ids]
}

resource "aws_db_instance" "internal" {
  identifier             = "internal"
  engine                 = var.rds_engine
  engine_version         = var.rds_engine_version
  instance_class         = var.rds_instance_class
  db_name                = var.rds_db_name
  username               = var.rds_username
  password               = var.rds_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = ["sg-12345678"]
  skip_final_snapshot    = true
  storage_type           = "gp2"
  allocated_storage      = 20
  backup_retention_period = 7
  preferred_backup_window = "07:00-08:00"
  preferred_maintenance_window = "08:00-09:00"
  iam_role               = aws_iam_role.rds_role.name
}

resource "aws_db_instance" "public" {
  identifier             = "public"
  engine                 = var.rds_engine
  engine_version         = var.rds_engine_version
  instance_class         = var.rds_instance_class
  db_name                = var.rds_db_name
  username               = var.rds_username
  password               = var.rds_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = ["sg-12345678"]
  skip_final_snapshot    = true
  storage_type           = "gp2"
  allocated_storage      = 20
  backup_retention_period = 7
  preferred_backup_window = "07:00-08:00"
  preferred_maintenance_window = "08:00-09:00"
  publicly_accessible    = true
  iam_role               = aws_iam_role.rds_role.name
}

resource "aws_iam_role" "rds_role" {
  name = "rds_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_role_policy" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}
```

