# IAM role for Elastic Beanstalk EC2 instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "elastic_beanstalk_ec2_role_eb1"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
