**Description of the Terraform Program:**

This Terraform configuration sets up a Blue/Green deployment strategy using AWS Elastic Beanstalk environments and Route53. It creates two Elastic Beanstalk environments named "blue" and "green", and configures Route53 to use a Weighted Routing Policy to route traffic between them. The Weighted Routing Policy allows for controlled traffic distribution, enabling a smooth Blue/Green deployment process. The configuration includes:

- Two Elastic Beanstalk environments with default settings.
- A Route53 hosted zone.
- Two A records for the environments, each with a weighted routing policy.
- A default Route53 record that routes traffic to the "blue" environment by default.
- IAM roles for Elastic Beanstalk and Route53 to ensure proper permissions.

All resources are defined with default values, and the configuration is ready to be deployed using Terraform 1.9.8 or later with the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "environment_name_blue" {
  description = "Name of the Blue Elastic Beanstalk environment"
  default     = "blue"
}

variable "environment_name_green" {
  description = "Name of the Green Elastic Beanstalk environment"
  default     = "green"
}

variable "domain_name" {
  description = "Domain name for the Route53 hosted zone"
  default     = "example.com"
}

variable "record_name" {
  description = "Record name for the Route53 A records"
  default     = "app"
}

variable "blue_weight" {
  description = "Weight for the Blue environment in Route53"
  default     = 100
}

variable "green_weight" {
  description = "Weight for the Green environment in Route53"
  default     = 0
}

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = var.environment_name_blue
  application = aws_elastic_beanstalk_application.example.name
  solution_stack_name = "64bit Amazon Linux 2 v4.0.0 running Python 3.11"
  tier                = "Standard"
  environment_type    = "ClassicLoadBalanced"
  wait_for_troops     = true
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = var.environment_name_green
  application = aws_elastic_beanstalk_application.example.name
  solution_stack_name = "64bit Amazon Linux 2 v4.0.0 running Python 3.11"
  tier                = "Standard"
  environment_type    = "ClassicLoadBalanced"
  wait_for_troops     = true
}

resource "aws_elastic_beanstalk_application" "example" {
  name = "blue-green-deployment"
}

resource "aws_route53_zone" "example" {
  name = var.domain_name
}

resource "aws_route53_record" "blue" {
  zone_id = aws_route53_zone.example.id
  name    = var.record_name
  type    = "A"
  weight  = var.blue_weight
  set_identifier = "blue"
  alias {
    name = aws_elastic_beanstalk_environment.blue.load_balancer_dns_name
  }
}

resource "aws_route53_record" "green" {
  zone_id = aws_route53_zone.example.id
  name    = var.record_name
  type    = "A"
  weight  = var.green_weight
  set_identifier = "green"
  alias {
    name = aws_elastic_beanstalk_environment.green.load_balancer_dns_name
  }
}

resource "aws_iam_role" "elasticbeanstalk" {
  name = "elasticbeanstalk-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "elasticbeanstalk" {
  role       = aws_iam_role.elasticbeanstalk.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkServiceRole"
}

resource "aws_iam_role" "route53" {
  name = "route53-service-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "route53.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "route53" {
  role       = aws_iam_role.route53.name
  policy_arn = "arn:aws:iam::aws:policy/Route53FullAccess"
}
