**Description of the Terraform Program:**

This Terraform configuration provisions two Elastic Beanstalk environments in different AWS regions: one in `us-west-2` (us_west) and one in `eu-central-1` (eu_central). Each environment is associated with a Route53 hosted zone and a Route53 record that uses geolocation-based routing to direct traffic to the closest environment. The configuration includes:

- Two AWS regions: `us-west-2` and `eu-central-1`.
- Two Elastic Beanstalk environments with appropriate IAM roles.
- A Route53 hosted zone for each region.
- Route53 records that use geolocation to route traffic to the closest environment.
- Default variables for environment names, domain names, and region settings.

All resources are created in their designated regions, and IAM roles are created as needed to support Elastic Beanstalk and Route53 operations.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

provider "aws" {
  region = "eu-central-1"
  alias  = "eu"
}

variable "us_west_environment_name" {
  default = "us_west"
}

variable "eu_central_environment_name" {
  default = "eu_central"
}

variable "domain_name" {
  default = "example.com"
}

variable "us_west_route53_zone_id" {
  default = "Z1234567890ABCDEF"
}

variable "eu_central_route53_zone_id" {
  default = "Z09876543210ZYXWVU"
}

resource "aws_iam_role" "us_west_elasticbeanstalk" {
  name = "us_west_elasticbeanstalk_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role" "eu_central_elasticbeanstalk" {
  name = "eu_central_elasticbeanstalk_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "us_west_elasticbeanstalk_policy" {
  role       = aws_iam_role.us_west_elasticbeanstalk.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBeanstalkServiceRole"
}

resource "aws_iam_role_policy_attachment" "eu_central_elasticbeanstalk_policy" {
  role       = aws_iam_role.eu_central_elasticbeanstalk.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBeanstalkServiceRole"
}

resource "aws_elasticbeanstalk_environment" "us_west_env" {
  name                = var.us_west_environment_name
  application = "my-app"
  solution_stack_name = "64bit Amazon Linux 2 v4.0.0 running Python 3.9"
  region             = "us-west-2"
  environment_type   = "LoadBalanced"
  tier               = "WebServer"
  resource_type      = "loadbalancer"
  iam_role_arn       = aws_iam_role.us_west_elasticbeanstalk.arn
}

resource "aws_elasticbeanstalk_environment" "eu_central_env" {
  name                = var.eu_central_environment_name
  application = "my-app"
  solution_stack_name = "64bit Amazon Linux 2 v4.0.0 running Python 3.9"
  region             = "eu-central-1"
  environment_type   = "LoadBalanced"
  tier               = "WebServer"
  resource_type      = "loadbalancer"
  iam_role_arn       = aws_iam_role.eu_central_elasticbeanstalk.arn
}

resource "aws_route53_record" "us_west_record" {
  name    = "us-west.${var.domain_name}"
  zone_id = var.us_west_route53_zone_id
  type    = "A"
  ttl     = 300
  records = [aws_elasticbeanstalk_environment.us_west_env.load_balancer_dns_name]
  set_identifier = "us-west"
  geo_location {
    country_code = "US"
    region_code  = "US-WEST"
  }
}

resource "aws_route53_record" "eu_central_record" {
  name    = "eu-central.${var.domain_name}"
  zone_id = var.eu_central_route53_zone_id
  type    = "A"
  ttl     = 300
  records = [aws_elasticbeanstalk_environment.eu_central_env.load_balancer_dns_name]
  set_identifier = "eu-central"
  geo_location {
    country_code = "DE"
    region_code  = "EU-CENTRAL"
  }
}
