**Description of the Terraform Program:**

This Terraform configuration creates two Elastic Beanstalk environments (production and staging) in AWS. Each environment is associated with an RDS database instance. The production environment uses a database named `prod_db`, and the staging environment uses `staging_db`. An IAM role named `eb_ec2_profile` is created to allow Elastic Beanstalk EC2 instances to access the RDS instances. The configuration uses the `hashicorp/aws` provider and is compatible with Terraform 1.9.8 and above.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment"
  default     = "production"
}

variable "db_instance_name" {
  description = "Name of the RDS database instance"
  default     = "prod_db"
}

variable "environment_name_staging" {
  description = "Name of the staging Elastic Beanstalk environment"
  default     = "staging"
}

variable "db_instance_name_staging" {
  description = "Name of the staging RDS database instance"
  default     = "staging_db"
}

variable "vpc_id" {
  description = "ID of the VPC to use for the Elastic Beanstalk environment"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the Elastic Beanstalk environment"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "Security group ID for the Elastic Beanstalk environment"
  default     = "sg-12345678"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Elastic Beanstalk EC2 instances"
  default     = "eb_ec2_profile"
}

resource "aws_iam_role" "eb_ec2_profile" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "elasticbeanstalk.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_profile_rds" {
  role       = aws_iam_role.eb_ec2_profile.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

resource "aws_rds_cluster" "prod_db" {
  cluster_identifier = var.db_instance_name
  engine             = "mysql"
  engine_version     = "8.0.33"
  master_username    = "admin"
  master_password    = "securepassword123"
  db_subnet_group_name = "default"
  vpc_security_group_ids = [var.security_group_id]
  skip_final_snapshot = true
}

resource "aws_rds_cluster" "staging_db" {
  cluster_identifier = var.db_instance_name_staging
  engine             = "mysql"
  engine_version     = "8.0.33"
  master_username    = "admin"
  master_password    = "securepassword123"
  db_subnet_group_name = "default"
  vpc_security_group_ids = [var.security_group_id]
  skip_final_snapshot = true
}

resource "aws_elasticbeanstalk_environment" "production_env" {
  name                = var.environment_name
  application_name    = "my-app"
  solution_stack_name = "64bit Amazon Linux 2 v4.0.0 running Python 3.10"
  tier                = "Production"
  environment_type    = "LoadBalanced"

  # RDS DB configuration
  option_settings {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceIdentifier"
    value     = var.db_instance_name
  }

  # EC2 instance profile
  ec2_vpc_id         = var.vpc_id
  ec2_subnet_ids     = var.subnet_ids
  ec2_security_group = var.security_group_id
  ec2_key_pair       = "my-key-pair"
}

resource "aws_elasticbeanstalk_environment" "staging_env" {
  name                = var.environment_name_staging
  application_name    = "my-app"
  solution_stack_name = "64bit Amazon Linux 2 v4.0.0 running Python 3.10"
  tier                = "Staging"
  environment_type    = "LoadBalanced"

  # RDS DB configuration
  option_settings {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceIdentifier"
    value     = var.db_instance_name_staging
  }

  # EC2 instance profile
  ec2_vpc_id         = var.vpc_id
  ec2_subnet_ids     = var.subnet_ids
  ec2_security_group = var.security_group_id
  ec2_key_pair       = "my-key-pair"
}
