LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up a blue/green deployment using AWS Elastic Beanstalk environments, each associated with an RDS database. The configuration includes:

- A VPC with a public and private subnet.
- A security group allowing access to the RDS database.
- An RDS database instance named `my_db`.
- A snapshot of the RDS database before deployment.
- Two Elastic Beanstalk environments (blue and green) with associated RDS database instances.
- An IAM instance profile `ec2_eb_profile1` for EC2 instances used by Elastic Beanstalk.
- A Route 53 hosted zone and record for DNS routing between environments.

The configuration ensures that the RDS database is backed up before deployment, and the environments are set up for blue/green deployment.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  default = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  default = "10.0.2.0/24"
}

variable "rds_db_name" {
  default = "my_db"
}

variable "rds_db_instance_class" {
  default = "db.t2.micro"
}

variable "rds_db_engine" {
  default = "mysql5.7"
}

variable "rds_db_username" {
  default = "admin"
}

variable "rds_db_password" {
  default = "securepassword"
}

variable "eb_environment_name_blue" {
  default = "blue-env"
}

variable "eb_environment_name_green" {
  default = "green-env"
}

variable "eb_app_name" {
  default = "my-app"
}

variable "iam_profile_name" {
  default = "ec2_eb_profile1"
}

variable "route53_zone_name" {
  default = "example.com"
}

variable "route53_record_name" {
  default = "myapp"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_route_table_assoc" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_security_group" "rds_sg" {
  name        = "rds_sg"
  description = "Allow access to RDS database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "rds_cluster" {
  cluster_identifier = var.rds_db_name
  engine              = var.rds_db_engine
  master_username     = var.rds_db_username
  master_password     = var.rds_db_password
  engine_version      = "5.7.39"
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds_subnet_group"
  subnet_ids = [aws_subnet.private_subnet.id]
}

resource "aws_rds_cluster_instance" "rds_instance" {
  cluster_identifier = aws_rds_cluster.rds_cluster.id
  instance_class     = var.rds_db_instance_class
}

resource "aws_rds_cluster_snapshot" "rds_snapshot" {
  cluster_identifier = aws_rds_cluster.rds_cluster.id
  snapshot_name      = "my_db_snapshot"
}

resource "aws_iam_role" "ec2_eb_profile" {
  name = var.iam_profile_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_eb_profile_attachment" {
  role       = aws_iam_role.ec2_eb_profile.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforEC2Instances"
}

resource "aws_elasticbeanstalk_application" "my_app" {
  name = var.eb_app_name
}

resource "aws_elasticbeanstalk_environment" "blue_env" {
  name                = var.eb_environment_name_blue
  application = aws_elasticbeanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.4.12 running Python 3.9"
  tier                = "Standard"
  environment_type    = "BlueGreen"
  version_label       = "v1"
  instance_profile_arn = aws_iam_role.ec2_eb_profile.arn
  database = {
    db_instance_identifier = aws_rds_cluster.rds_cluster.id
    db_password = var.rds_db_password
    db_username = var.rds_db_username
  }
}

resource "aws_elasticbeanstalk_environment" "green_env" {
  name                = var.eb_environment_name_green
  application = aws_elasticbeanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.4.12 running Python 3.9"
  tier                = "Standard"
  environment_type    = "BlueGreen"
  version_label       = "v1"
  instance_profile_arn = aws_iam_role.ec2_eb_profile.arn
  database = {
    db_instance_identifier = aws_rds_cluster.rds_cluster.id
    db_password = var.rds_db_password
    db_username = var.rds_db_username
  }
}

resource "aws_route53_zone" "example_zone" {
  name = var.route53_zone_name
}

resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_zone.example_zone.id
  name    = var.route53_record_name
  type    = "A"
  ttl     = 300
  records = [aws_elasticbeanstalk_environment.blue_env.endpoint.url]
}

resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_zone.example_zone.id
  name    = var.route53_record_name
  type    = "A"
  ttl     = 300
  records = [aws_elasticbeanstalk_environment.green_env.endpoint.url]
}
```

