**Description of the Terraform Program:**

This Terraform configuration creates a complete Elastic Beanstalk application that runs a Go application. It includes:

- A VPC with a public subnet.
- An Internet Gateway and Route Table.
- A Security Group allowing HTTP and SSH access.
- An IAM role for Elastic Beanstalk to manage the environment.
- An Elastic Beanstalk application and environment.
- A Go application version uploaded to an S3 bucket.
- A CloudFormation stack to deploy the Elastic Beanstalk environment.

The configuration is designed to be deployable in AWS using Terraform 1.9.8 or later and the `hashicorp/aws` provider version 5.75 or later.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment"
  default     = "go-app-env"
}

variable "application_name" {
  description = "Name of the Elastic Beanstalk application"
  default     = "go-app"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store the Go application version"
  default     = "go-app-bucket"
}

variable "s3_object_key" {
  description = "Key of the Go application version in the S3 bucket"
  default     = "go-app.zip"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk environment"
  default     = "t2.micro"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "go-app-sg"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Elastic Beanstalk"
  default     = "elasticbeanstalk-role"
}

variable "iam_role_policy_arn" {
  description = "ARN of the IAM policy for Elastic Beanstalk"
  default     = "arn:aws:iam::aws:policy/AWSelasticbeanstalkFullAccess"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "go-app-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
  tags = {
    Name = "go-app-public-subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "go-app-igw"
  }
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "go-app-public-route-table"
  }
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_security_group" "sg" {
  name        = var.security_group_name
  description = "Allow HTTP and SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.security_group_name
  }
}

resource "aws_iam_role" "eb_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticbeanstalk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eb_policy" {
  role       = aws_iam_role.eb_role.name
  policy_arn = var.iam_role_policy_arn
}

resource "aws_s3_bucket" "app_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  tags = {
    Name = var.s3_bucket_name
  }
}

resource "aws_s3_bucket_object" "app_version" {
  bucket = aws_s3_bucket.app_bucket.bucket
  key    = var.s3_object_key
  source = "app.zip" # This should be replaced with the actual path to your Go app zip file
}

resource "aws_elasticbeanstalk_application" "go_app" {
  name = var.application_name
}

resource "aws_elasticbeanstalk_environment" "go_env" {
  application = aws_elasticbeanstalk_application.go_app.name
  name        = var.environment_name
  solution_stack_name = "64bit Amazon Linux 2 v3.4.0 running Go 1.21"

