**Description of the Terraform Program:**

This Terraform configuration provisions and scales a web application using AWS resources. It includes:

- A VPC with a public and private subnet.
- A NAT Gateway to allow private instances to access the internet.
- A security group to allow HTTP and HTTPS traffic.
- An EC2 instance running a supported web application (e.g., Node.js, Python, or PHP).
- An Elastic Load Balancer (ELB) to distribute traffic to the EC2 instance.
- Auto Scaling Group to scale the number of EC2 instances based on demand.
- A CloudWatch Alarm to monitor CPU utilization and trigger scaling actions.
- An IAM role for the EC2 instance to allow it to communicate with other AWS services.

The configuration uses default values for variables where applicable and ensures all resources are properly declared and referenced.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_type" {
  description = "The type of EC2 instance to use."
  default     = "t2.micro"
}

variable "ami_id" {
  description = "The AMI ID for the web application."
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "The CIDR block for the public subnet."
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "The CIDR block for the private subnet."
  default     = "10.0.2.0/24"
}

variable "key_name" {
  description = "The name of the EC2 key pair to use."
  default     = "my-key-pair"
}

variable "security_group_name" {
  description = "The name of the security group."
  default     = "web-app-sg"
}

variable "load_balancer_name" {
  description = "The name of the load balancer."
  default     = "web-app-elb"
}

variable "auto_scaling_group_name" {
  description = "The name of the auto scaling group."
  default     = "web-app-asg"
}

variable "min_size" {
  description = "Minimum number of instances in the auto scaling group."
  default     = "1"
}

variable "max_size" {
  description = "Maximum number of instances in the auto scaling group."
  default     = "3"
}

variable "desired_capacity" {
  description = "Desired number of instances in the auto scaling group."
  default     = "2"
}

variable "alarm_threshold" {
  description = "CPU utilization threshold for scaling."
  default     = "70"
}

variable "alarm_duration" {
  description = "Duration for the CloudWatch alarm."
  default     = "300"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_nat_gateway" "nat" {
  subnet_id   = aws_subnet.public.id
  allocation_id = aws_eip.eip.id
}

resource "aws_eip" "eip" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table" "private_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "private_route" {
  route_table_id         = aws_route_table.private_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.nat.id
}

resource "aws_route_table_association" "private_assoc" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private_route_table.id
}

resource "aws_security_group" "web_app_sg" {
  name        = var.security_group_name
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_template" "web_app_template" {
  name = "web-app-launch-template"
  image_id = var.ami_id
  instance_type = var.instance_type
  key_name = var.key_name
  security_groups = [aws_security_group.web_app_sg.id]

  user_data = <<-EOF
              #!/bin/bash
              sudo yum update -y
              sudo yum install -y httpd
              sudo systemctl start httpd
              sudo systemctl enable httpd
              echo "Hello from Terraform!" > /var/www/html/index.html
              EOF

  metadata_options {
    http_tokens = "optional"
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "web-app-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_launch_configuration" "web_app_config" {
  name = "web-app-launch-configuration"
  image_id = var.ami_id
  instance_type = var.instance_type
  security_groups = [aws_security_group.web_app_sg.id]
  iam_instance_profile = aws_iam_role.ec2_role.name
  user_data = <<-EOF
              #!/bin/bash
              sudo yum update -y
              sudo yum install -y httpd
              sudo systemctl start httpd
              sudo systemctl enable httpd
              echo "Hello from Terraform!" > /var/www/html/index.html
              EOF
}

resource "aws_autoscaling_group" "web_app_asg" {
  name = var.auto_scaling_group_name
  launch_configuration = aws_launch_configuration.web_app_config.name
  vpc_zone_identifier = [aws_subnet.private.id]
  min_size = var.min_size
  max_size = var.max_size
  desired_capacity = var.desired_capacity
}

resource "aws_autoscaling_policy" "scale_out" {
  name               = "scale-out-policy"
  autoscaling_group_name = aws_autoscaling_group.web_app_asg.name
  policy_type        = "SimpleScaling"
  adjustment_type    = "ChangeInCapacity"
  scaling_adjustment = 1
}

resource "aws_autoscaling_policy" "scale_in" {
  name               = "scale-in-policy"
  autoscaling_group_name = aws_autoscaling_group.web_app_asg.name
  policy_type        = "SimpleScaling"
  adjustment_type    = "ChangeInCapacity"
  scaling_adjustment = -1
}

resource "aws_cloudwatch_metric_alarm" "cpu_alarm" {
  alarm_name          = "web-app-cpu-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = "1"
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  statistic           = "Average"
  threshold           = var.alarm_threshold
  period              = var.alarm_duration
  alarm_description   = "Alarm when CPU exceeds threshold"
  treat_missing_data  = "notBreaching"
  dimensions = {
    AutoScalingGroupName = aws_autoscaling_group.web_app_asg.name
  }

  actions_enabled = true
  alarm_actions = [aws_sns_topic.web_app_sns.arn]
}

resource "aws_sns_topic" "web_app_sns" {
  name = "web-app-sns-topic"
}

