variable "application_name" {
  description = "Name of the Elastic Beanstalk application"
  default     = "my-beanstalk-app"
}

variable "version_lifecycle_days" {
  description = "Number of days to retain app versions"
  default     = 5
}

resource "aws_elasticbeanstalk_application" "app" {
  name = var.application_name
}

resource "aws_elasticbeanstalk_application_version_lifecycle" "lifecycle" {
