The configuration includes a default region (us-east-1), and all resources are defined explicitly with no undeclared dependencies.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "codebuild_project_name" {
  description = "Name of the CodeBuild project"
  default     = "example-codebuild-project"
}

variable "codebuild_description" {
  description = "Description of the CodeBuild project"
  default     = "Example CodeBuild project with secondary sources and artifacts"
}

variable "codebuild_role_name" {
  description = "Name of the IAM role for CodeBuild"
  default     = "CodeBuildServiceRole"
}

variable "codebuild_environment_variables" {
  description = "Environment variables for the CodeBuild project"
  default     = {
    "ENV_VAR_1" = "value1"
    "ENV_VAR_2" = "value2"
  }
}

variable "codebuild_secondary_source_type" {
  description = "Type of secondary source (e.g., S3, CodeCommit)"
  default     = "S3"
}

variable "codebuild_secondary_source_location" {
  description = "Location of the secondary source"
  default     = "https://example.com/secondary-source.zip"
}

variable "codebuild_secondary_artifact_type" {
  description = "Type of secondary artifact (e.g., S3, CodeCommit)"
  default     = "S3"
}

variable "codebuild_secondary_artifact_location" {
  description = "Location of the secondary artifact"
  default     = "s3://example-bucket/secondary-artifact"
}

resource "aws_iam_role" "codebuild_role" {
  name = var.codebuild_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_role_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRole"
}

resource "aws_codebuild_project" "codebuild_project" {
  name        = var.codebuild_project_name
  description = var.codebuild_description

  service_role = aws_iam_role.codebuild_role.arn

  environment {
    type = "LINUX_CONTAINER"
    image = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
  }

  environment_variables = jsonencode(var.codebuild_environment_variables)

  source {
    type = "CODECOMMIT"
    location = "https://git-codecommit.us-east-1.amazonaws.com/v1/repos/example-repo"
  }

