**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lex Bot using the `aws_lex_bot` resource. The bot will be configured with a name, description, and a set of intents. The configuration includes default values for all variables to ensure the program is deployable without additional input. The AWS provider is configured with a default region (us-east-1), and the necessary IAM permissions are assumed to be in place for the AWS credentials used by Terraform.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lex_bot_name" {
  description = "Name of the Lex Bot"
  default     = "MyLexBot"
}

variable "lex_bot_description" {
  description = "Description of the Lex Bot"
  default     = "A sample Lex Bot created by Terraform"
}

variable "lex_bot_intent_name" {
  description = "Name of the intent to be associated with the bot"
  default     = "GreetingIntent"
}

resource "aws_lex_bot" "lex_bot" {
  name        = var.lex_bot_name
  description = var.lex_bot_description
  intent_name = var.lex_bot_intent_name
  role_arn    = "arn:aws:iam::123456789012:role/LexBotRole" # Replace with your IAM role ARN

  depends_on = [aws_iam_role_policy_attachment.lex_bot_policy]
}

resource "aws_iam_role" "lex_bot_role" {
  name = "LexBotRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "lex.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lex_bot_policy" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonLexFullAccess"
}
```

---

**Note:**  
- Replace the `role_arn` in the `aws_lex_bot` resource with the actual ARN of the IAM role that will be used by the Lex Bot.
- Ensure that the AWS credentials are properly configured in your Terraform environment (e.g., via `AWS_ACCESS_KEY_ID` and `AWS_SECRET_ACCESS_KEY` environment variables or a shared credentials file).

