  description = "NLU intent confidence threshold for the bot"
  default     = 0.5
}

resource "aws_lex_bot" "pizza_order_bot" {
  name                 = var.bot_name
  nlu_intent_confidence_threshold = var.nlu_intent_confidence_threshold
  idle_session_ttl_seconds = 300
  child_directed        = false
  role_arn              = aws_iam_role.lex_bot_role.arn
