**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lex Bot for ordering pizzas and integrates it with a Lambda function. The Lex Bot will handle user input to gather pizza order details, and the Lambda function will process the order. The configuration includes:

- An AWS Lambda function to handle the pizza order logic.
- An AWS Lex Bot with a Lambda function as its intent backend.
- IAM roles for the Lambda function and the Lex Bot to ensure proper permissions.
- A default region (us-east-1) and default values for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function to handle pizza orders."
  default     = "pizza-order-lambda"
}

variable "lex_bot_name" {
  description = "Name of the Lex Bot for ordering pizzas."
  default     = "pizza-order-bot"
}

variable "lex_bot_description" {
  description = "Description of the Lex Bot."
  default     = "A bot for ordering pizzas."
}

variable "lambda_role_name" {
  description = "Name of the IAM role for the Lambda function."
  default     = "pizza-order-lambda-role"
}

resource "aws_iam_role" "lambda_role" {
  name = var.lambda_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "pizza_order_lambda" {
  function_name    = var.lambda_function_name
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda.zip"
  role             = aws_iam_role.lambda_role.arn
  source_code_hash = filebase64sha256("lambda.zip")
  timeout          = 30

  environment {
    variables = {
      "LOG_LEVEL" = "INFO"
    }
  }
}

resource "aws_lex_bot" "pizza_order_bot" {
  name        = var.lex_bot_name
  description = var.lex_bot_description
  role_arn    = aws_iam_role.lambda_role.arn
  idle_session_ttl_seconds = 300
  clarification_prompt {
    message = "I didn't understand that. Could you please clarify?"
    response_card = ""
  }
}

resource "aws_lex_bot_alias" "pizza_order_bot_alias" {
  name        = "live"
  bot_name    = var.lex_bot_name
  bot_version = "DRAFT"
  description = "Live version of the pizza order bot"
}
```

---

**Note:** This configuration assumes that you have a `lambda.zip` file containing the Lambda function code. You will need to replace this with your actual Lambda code and ensure it is properly zipped and uploaded to the correct location.

