  type        = string
  default     = "arn:aws:connect:us-east-1:123456789012:instance/abcd1234"
}

variable "bot_association_name" {
  description = "The name of the bot association."
  type        = string
  default     = "MyBotAssociation"
}

variable "bot_arn" {
  description = "The ARN of the bot to be associated."
  type        = string
  default     = "arn:aws:connect:us-east-1:123456789012:bot/abcd1234"
}

resource "aws_connect_bot_association" "bot_association" {
  instance_arn = var.connect_instance_arn
  bot_arn      = var.bot_arn
  name         = var.bot_association_name
  saml_config {
    saml_provider_arn = "arn:aws:iam::123456789012:saml-provider/abcd1234"
  }
}
```

---

**Notes:**

- The `saml_provider_arn` must be a valid SAML provider ARN in the same AWS account and region as the Connect instance.
- The `bot_arn` and `connect_instance_arn` should be valid ARNs for the bot and Connect instance, respectively.
- This configuration assumes that the SAML provider is already set up and associated with the bot. If not, additional steps are required to configure the SAML provider and link it to the bot.

