**Description:**

This Terraform configuration creates a Kinesis Firehose Delivery Stream that delivers data to an extended S3 destination with dynamic partitioning enabled. The configuration includes:

- A Kinesis Firehose Delivery Stream resource.
- An S3 bucket to store the delivered data.
- An IAM role for the Firehose service to access the S3 bucket.
- Dynamic partitioning is enabled to allow the Firehose to automatically create partitions based on the data.

The configuration uses default values for variables where applicable and includes a valid AWS provider configuration in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "firehose_name" {
  description = "Name of the Kinesis Firehose Delivery Stream"
  default     = "firehose-delivery-stream"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store Firehose data"
  default     = "firehose-s3-bucket"
}

variable "s3_prefix" {
  description = "Prefix for Firehose data in the S3 bucket"
  default     = "firehose-data"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Firehose"
  default     = "firehose-iam-role"
}

resource "aws_s3_bucket" "firehose_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "firehose_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "firehose.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_s3_access" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name           = var.firehose_name
  delivery_stream_type = "direct_put"

  destination = "extended_s3"

  extended_s3_destination_configuration {
    role_arn = aws_iam_role.firehose_role.arn

    bucket_arn = aws_s3_bucket.firehose_bucket.arn

    prefix = var.s3_prefix

    error_output_prefix = "error/"

    buffering_hints {
      size_in_mbs = 5
      interval_in_seconds = 60
    }

    dynamic_partitioning_configuration {
      enabled = true
      timestamp_field = "timestamp"
      time_zone = "UTC"
      partition_key = "partition_key"
    }

    compression_format = "UNCOMPRESSED"
  }
}
```

---

**Note:** This configuration assumes that the data being delivered to the Firehose stream includes a `timestamp` field and a `partition_key` field for dynamic partitioning. You may need to adjust these based on your data schema.

