---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream"
  default     = "firehose-delivery-stream"
}

variable "elasticsearch_endpoint" {
  description = "Elasticsearch endpoint URL"
  default     = "https://search-xxxxxx.us-east-1.es.amazonaws.com"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Firehose to use"
  default     = "firehose-es-iam-role"
}

resource "aws_iam_role" "firehose_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_es_policy" {
  name = "${var.iam_role_name}-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "es:ESHttpPost",
          "es:ESHttpPut"
        ]
        Resource = var.elasticsearch_endpoint
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name           = var.firehose_delivery_stream_name
