    processing_configuration {
      processors = []
    }
  }
}
```

> **Note:** Replace `"arn:aws:es:us-east-1:123456789012:domain/my-elasticsearch-domain"` with the actual ARN of your Elasticsearch domain. Also, ensure that the Elasticsearch endpoint is correctly formatted and accessible from the Firehose service.

