**Description:**

This Terraform configuration creates a Kinesis Firehose Delivery Stream that delivers data to a Splunk destination. The configuration includes:

- A Kinesis Firehose Delivery Stream resource.
- An IAM role for the Firehose stream to assume when delivering data to Splunk.
- A Splunk destination configuration with the necessary parameters such as HTTP Event Collector (HEC) URL, token, and index.
- A default region set to `us-east-1` (you can change this as needed).
- All required variables are defined with default values for easy deployment.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "firehose_name" {
  description = "Name of the Kinesis Firehose delivery stream"
  default     = "splunk-delivery-stream"
}

variable "splunk_hec_url" {
  description = "Splunk HTTP Event Collector URL"
  default     = "https://splunk-hec-endpoint.com/services/collector"
}

variable "splunk_hec_token" {
  description = "Splunk HTTP Event Collector token"
  default     = "your-splunk-hec-token"
}

variable "splunk_index" {
  description = "Splunk index to send data to"
  default     = "main"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Firehose"
  default     = "firehose-splunk-role"
}

resource "aws_iam_role" "firehose_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "firehose.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "firehose_splunk_policy" {
  name = "${var.iam_role_name}-splunk-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogStreams"
      ]
      Resource = "arn:aws:logs:*:*:*"
    }]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "splunk_delivery_stream" {
  name           = var.firehose_name
  destination    = "splunk"
  splunk_endpoint_config {
    url          = var.splunk_hec_url
    hec_token    = var.splunk_hec_token
    hec_url      = var.splunk_hec_url
    hec_token_arn = "arn:aws:iam::123456789012:role/${var.iam_role_name}"
    index        = var.splunk_index
  }

  role_arn = aws_iam_role.firehose_role.arn
}
```

---

**Note:** Replace the `hec_token_arn` with the actual ARN of the IAM role that has the necessary permissions to write to Splunk. This configuration assumes that the Splunk HEC endpoint is properly configured and accessible from the AWS environment.

