LLM Output #0:
**Description:**

This Terraform configuration creates a Kinesis Firehose Delivery Stream that delivers data to an extended S3 destination. The configuration includes:

- A Kinesis Firehose Delivery Stream resource.
- An S3 bucket to store the delivered data.
- An IAM role for the Firehose service to write to the S3 bucket.
- A policy that allows the Firehose service to write to the S3 bucket.
- A default region (us-east-1) and default values for variables where applicable.

The configuration is designed to be deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store Firehose data."
  default     = "firehose-delivery-bucket"
}

variable "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream."
  default     = "firehose-delivery-stream"
}

resource "aws_s3_bucket" "firehose_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose-s3-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "firehose_s3_policy" {
  name = "firehose-s3-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:PutObject",
        "s3:PutObjectAcl",
        "s3:GetBucketLocation"
      ]
      Resource = [
        "${aws_s3_bucket.firehose_bucket.arn}",
        "${aws_s3_bucket.firehose_bucket.arn}/*"
      ]
    }]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name           = var.firehose_delivery_stream_name
  delivery_stream_type = "direct_put"

  destination = "extended_s3"

  extended_s3_destination_configuration {
    role_arn = aws_iam_role.firehose_role.arn
    bucket_arn = aws_s3_bucket.firehose_bucket.arn
    compression_format = "UNCOMPRESSED"
    prefix = "firehose/"
    error_output_prefix = "error/"
    buffering_hints {
      size_in_mbs = 5
      interval_in_seconds = 60
    }
    s3_backup_mode = "ENABLED"
    backup_s3_bucket_arn = aws_s3_bucket.firehose_bucket.arn
    backup_compression_format = "UNCOMPRESSED"
    backup_buffering_hints {
      size_in_mbs = 5
      interval_in_seconds = 60
    }
  }
}
```

