**Description:**

This Terraform configuration creates a basic Amazon Kinesis Analytics Application using AWS. The application will be set up with a SQL-based application to process data from a Kinesis stream. The configuration includes:

- A Kinesis stream for input data.
- A Kinesis Analytics application with a SQL query.
- An IAM role for the Kinesis Analytics service to access the Kinesis stream.
- A default region set to `us-east-1`.
- All necessary resources are declared and referenced properly.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "kinesis_stream_name" {
  description = "Name of the Kinesis stream to use as input."
  default     = "kinesis-stream"
}

variable "kinesis_analytics_app_name" {
  description = "Name of the Kinesis Analytics application."
  default     = "kinesis-analytics-app"
}

variable "sql_query" {
  description = "SQL query to process the data."
  default     = "SELECT * FROM kinesisStream;"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kinesisanalytics.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_role_policy" {
  role       = aws_iam_role.kinesis_analytics_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSKinesisAnalyticsFullAccess"
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name        = var.kinesis_stream_name
  shard_count = 1
}

resource "aws_kinesis_analytics_application" "kinesis_analytics_app" {
  name             = var.kinesis_analytics_app_name
  input {
    name             = "InputStream"
    kinesis_stream {
      arn = aws_kinesis_stream.kinesis_stream.arn
    }
    role_arn         = aws_iam_role.kinesis_analytics_role.arn
    input_schema {
      record_format {
        record_format_type = "JSON"
        mapping_parameters {
          json_mapping_parameters {
            attribute_paths = ["*"]
          }
        }
      }
      record_encoding = "UTF-8"
    }
  }
  output {
    name             = "OutputStream"
    kinesis_stream {
      arn = aws_kinesis_stream.kinesis_stream.arn
    }
    output_schema {
      record_format {
        record_format_type = "JSON"
        mapping_parameters {
          json_mapping_parameters {
            attribute_paths = ["*"]
          }
        }
      }
      record_encoding = "UTF-8"
    }
  }
  sql_query = var.sql_query
}
```

