**Description:**

This Terraform configuration sets up an Active-Passive failover setup using AWS Route 53. It creates a health check named `primary_health_check` with a fully qualified domain name (FQDN) to monitor the primary resource. It also creates a Route 53 hosted zone named `primary` and configures a failover record that routes traffic to a secondary resource if the primary health check fails. The configuration includes necessary IAM roles and assumes the use of default values for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "primary_fqdn" {
  description = "The FQDN of the primary resource to be monitored."
  default     = "example.com"
}

variable "secondary_fqdn" {
  description = "The FQDN of the secondary resource to be used in failover."
  default     = "secondary.example.com"
}

variable "primary_health_check_name" {
  description = "Name of the health check for the primary resource."
  default     = "primary_health_check"
}

variable "hosted_zone_name" {
  description = "Name of the Route 53 hosted zone."
  default     = "primary"
}

resource "aws_route53_health_check" "primary_health_check" {
  name    = var.primary_health_check_name
  fqdn    = var.primary_fqdn
  type    = "HTTP"
  port    = 80
  protocol = "HTTP"
  resource_path = "/"
  failure_threshold = 3
}

resource "aws_route53_zone" "primary" {
  name = var.hosted_zone_name
}

resource "aws_route53_record" "primary_record" {
  zone_id = aws_route53_zone.primary.id
  name    = var.primary_fqdn
  type    = "A"
  ttl     = 300
  records = ["192.0.2.1"]
  set_identifier = "primary"
  failover = "PRIMARY"
}

resource "aws_route53_record" "secondary_record" {
  zone_id = aws_route53_zone.primary.id
  name    = var.secondary_fqdn
  type    = "A"
  ttl     = 300
  records = ["192.0.2.2"]
  set_identifier = "secondary"
  failover = "SECONDARY"
  health_check_id = aws_route53_health_check.primary_health_check.id
}
```

---

**Note:**  
- This configuration assumes that the primary and secondary resources are already available and have public IP addresses.
- The `failover` attribute in the secondary record is set to `SECONDARY`, and the `health_check_id` is linked to the primary health check.
- The `primary_health_check` is configured to monitor the primary FQDN using HTTP. Adjust the `port`, `protocol`, and `resource_path` as needed for your specific use case.

