}

variable "period" {
  description = "Period in seconds for the metric"
  default     = "120"
}

variable "comparison_operator" {
  description = "Comparison operator for the alarm"
  default     = "GreaterThanOrEqualToThreshold"
}

variable "health_check_name" {
  description = "Name of the Route 53 health check"
  default     = "foobar-health-check"
}

variable "health_check_type" {
  description = "Type of health check (e.g., CLOUDWATCH_METRIC)"
  default     = "CLOUDWATCH_METRIC"
}

variable "health_check_failure_threshold" {
  description = "Number of consecutive health check failures before a health check is considered unhealthy"
  default     = "3"
}

variable "health_check_inverted" {
  description = "Whether the health check is inverted"
  default     = false
}

variable "health_check_port" {
  description = "Port for the health check"
  default     = "80"
}

variable "health_check_protocol" {
  description = "Protocol for the health check"
  default     = "HTTP"
}

variable "health_check_timeout" {
  description = "Timeout in seconds for the health check"
  default     = "30"
}

variable "health_check_interval" {
  description = "Interval in seconds between health checks"
  default     = "30"
}

variable "health_check_failure_status" {
  description = "Status to return when the health check is unhealthy"
  default     = "Healthy"
}

resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = var.alarm_name
  metric_name         = var.metric_name
  namespace           = var.namespace
  statistic           = var.statistic
  period              = var.period
  comparison_operator = var.comparison_operator
  evaluation_periods  = "1"
  threshold           = 80
  alarm_description   = "Alarm when CPU utilization exceeds 80%"
  treat_missing_data  = "notBreaching"
}

resource "aws_route53_health_check" "foobar_health_check" {
  name                    = var.health_check_name
  type                    = var.health_check_type
  ip_address              = ""
  port                    = var.health_check_port
  protocol                = var.health_check_protocol
  region                  = "us-east-1"
  resource_path           = "/"
  failure_threshold       = var.health_check_failure_threshold
