**Description of the Terraform Program:**

This Terraform configuration sets up a Route 53 hosted zone named "primary" and creates a routing policy that directs traffic to the least congested endpoint using a latency-based routing policy. The configuration includes two endpoints in the specified regions: `us-east-1` and `eu-central-1`. The routing policy ensures that users are directed to the endpoint with the least network latency.

The configuration includes:
- A Route 53 hosted zone named "primary".
- Two Route 53 latency-based routing policies, one for each region.
- An alias record that points to the routing policy, allowing traffic to be directed based on latency.

All resources are created in the `us-east-1` region, and the configuration is compatible with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "zone_name" {
  description = "The name of the Route 53 hosted zone."
  default     = "primary"
}

variable "region1" {
  description = "First region for latency-based routing."
  default     = "us-east-1"
}

variable "region2" {
  description = "Second region for latency-based routing."
  default     = "eu-central-1"
}

resource "aws_route53_zone" "primary" {
  name = var.zone_name
}

resource "aws_route53_traffic_policy" "latency_policy1" {
  name        = "latency-policy-${var.region1}"
  type        = "latency"
  comment     = "Latency-based routing policy for ${var.region1}"
  region      = var.region1
  zone_id     = aws_route53_zone.primary.id
  traffic_type = "weighted"
}

resource "aws_route53_traffic_policy" "latency_policy2" {
  name        = "latency-policy-${var.region2}"
  type        = "latency"
  comment     = "Latency-based routing policy for ${var.region2}"
  region      = var.region2
  zone_id     = aws_route53_zone.primary.id
  traffic_type = "weighted"
}

resource "aws_route53_traffic_policy_instance" "latency_instance1" {
  name        = "latency-instance-${var.region1}"
  zone_id     = aws_route53_zone.primary.id
  traffic_policy_id = aws_route53_traffic_policy.latency_policy1.id
  type        = "weighted"
  comment     = "Instance for latency policy in ${var.region1}"
}

resource "aws_route53_traffic_policy_instance" "latency_instance2" {
  name        = "latency-instance-${var.region2}"
  zone_id     = aws_route53_zone.primary.id
  traffic_policy_id = aws_route53_traffic_policy.latency_policy2.id
  type        = "weighted"
  comment     = "Instance for latency policy in ${var.region2}"
}

resource "aws_route53_record" "alias_record" {
  name    = "www.${var.zone_name}"
  zone_id = aws_route53_zone.primary.id
  type    = "A"
  alias {
    name                   = aws_route53_traffic_policy_instance.latency_instance1.traffic_policy_instance_id
    zone_id                = aws_route53_zone.primary.id
    evaluate_target_health = true
  }
}
```

