**Description of the Terraform Program:**

This Terraform configuration defines a variable `cluster_name` of type string, which is used to name an AWS EKS cluster. It creates an IAM role with the necessary permissions for EKS cluster and service management. The EKS cluster is created with specified VPC subnet IDs for networking. The configuration includes IAM role creation and policy attachment, and uses `local-exec` provisioners to manage `kubectl` configuration during cluster creation and destruction. The provider is configured for AWS in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "The name of the EKS cluster."
  type        = string
  default     = "my-eks-cluster"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the EKS cluster."
  type        = string
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the EKS cluster."
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role-${var.cluster_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = var.subnet_ids
    vpc_id     = var.vpc_id
  }

  tags = {
    Name = var.cluster_name
  }
}

resource "aws_iam_role" "eks_node_role" {
  name = "eks-node-role-${var.cluster_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_cni_policy" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodeAccess"
}

resource "aws_iam_role_policy_attachment" "eks_cni_policy_2" {
  role       = aws_iam_role.eks_node_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_eks_node_group" "eks_node_group" {
  cluster_name    = var.cluster_name
  node_group_name = "node-group-${var.cluster_name}"
  node_role_arn   = aws_iam_role.eks_node_role.arn
  subnet_ids      = var.subnet_ids
  version         = "1.28"

  scaling_config {
    desired size = 2
    max size    = 4
    min size    = 2
  }

  launch_template {
    id      = "lt-12345678"
    version = "$Latest"
  }
}

provisioner "local-exec" {
  when    = "create"
  command = "aws eks update-kubeconfig --name ${var.cluster_name} --region us-east-1"
}

provisioner "local-exec" {
  when    = "destroy"
  command = "aws eks update-kubeconfig --name ${var.cluster_name} --region us-east-1 --no-verify"
}
```

