    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_service_policy,
  ]

  # Manage kubectl configuration
  provisioner "local-exec" {
    command = "aws eks --region ${data.aws_region.current.name} update-kubeconfig --name ${self.name}"
  }

  provisioner "local-exec" {
    when    = destroy
    command = "kubectl config unset users.${self.arn}"
  }
  provisioner "local-exec" {
    when    = destroy
    command = "kubectl config unset clusters.${self.arn}"
  }
  provisioner "local-exec" {
    when    = destroy
    command = "kubectl config unset contexts.${self.arn}"
  }
}

LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up an AWS provider in a specified region and retrieves the current caller identity. It optionally fetches the latest stable ECR image from a specified repository. It defines local variables for the image tag, AWS tags, and workspace name. It then instantiates an EKS module to create an EKS cluster with specified configurations, including IAM policies, instance types, and node count. The configuration retrieves information about the EKS cluster and its authentication data. Finally, it sets up the Helm and Kubernetes providers using the EKS cluster details for cluster communication.

---

```hcl
provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

locals {
  image_tag      = "stable"
  aws_tags      = {
    Project = "eks-cluster"
    Env     = "dev"
  }
  workspace_name = terraform.workspace
}

data "aws_ecr_image" "latest_stable" {
  repository_name = var.ecr_repository_name
  image_tag       = local.image_tag
  # Optional: If you want to fetch the latest image digest, you can use the image_digest attribute
}

module "eks_cluster" {
  source  = "terraform-aws-modules/eks/aws"
  version = "19.0.0"

  name         = local.workspace_name
  cluster_version = "1.28"
  vpc_id       = data.aws_vpc.default.id
  subnet_ids   = data.aws_subnet_ids.default.ids
  instance_type = "t3.medium"
  node_count   = 3
  managed_node_group = true
  managed_node_group_desired_size = 3
  managed_node_group_max_size = 5
  managed_node_group_min_size = 2
  managed_node_group_update_config {
    max_unavailable = 1
  }

  iam {
    create_service_account = true
    create_cluster_role    = true
    create_cluster_role_binding = true
  }

  tags = local.aws_tags
}

data "aws_eks_cluster" "this" {
  name = module.eks_cluster.cluster_name
}

data "aws_eks_cluster_auth" "this" {
  name = module.eks_cluster.cluster_name
}

provider "kubernetes" {
  host                   = data.aws_eks_cluster.this.cluster_endpoint
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.this.cluster_certificate_authority_data)
  token                  = data.aws_eks_cluster_auth.this.token
}

provider "helm" {
  kubeconfig = data.aws_eks_cluster_auth.this.kubeconfig
}
```

---

**Variables (to be defined in `variables.tf`):**

```hcl
variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-west-2"
}

variable "ecr_repository_name" {
  description = "Name of the ECR repository to fetch the stable image from"
  default     = "my-ecr-repository"
}
```

---

**Notes:**

- This configuration assumes that a default VPC and subnets are available in the specified region. If not, you may need to define them separately.
- The `aws_eks_cluster` and `aws_eks_cluster_auth` data sources are used to retrieve information about the EKS cluster and its authentication data.
- The `kubernetes` and `helm` providers are configured using the EKS cluster's endpoint and authentication token.
- The EKS module version used is `19.0.0`, which is compatible with Terraform 1.9.8 and AWS provider 5.75.

