LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates an IAM role for EKS Fargate profiles with the necessary policies for pod execution. It attaches the `AmazonEKSFargatePodExecutionRolePolicy` to the IAM role. It then defines an EKS Fargate profile for the `kube-system` namespace, associating it with an EKS cluster and specifying the pod execution role ARN. The configuration ensures that the specified subnets have the required resource tag for cluster association. Finally, it uses a `null_resource` to patch the Kubernetes deployment `coredns` in the `kube-system` namespace using the EKS cluster's endpoint, certificate authority, and authentication token for communication.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "eks_cluster_name" {
  description = "Name of the EKS cluster"
  default     = "my-eks-cluster"
}

variable "eks_cluster_endpoint" {
  description = "Endpoint of the EKS cluster"
  default     = "https://api.my-eks-cluster.us-west-2.eks.amazonaws.com"
}

variable "eks_cluster_ca" {
  description = "CA certificate of the EKS cluster"
  default     = "-----BEGIN CERTIFICATE-----\n...\n-----END CERTIFICATE-----"
}

variable "eks_cluster_token" {
  description = "Authentication token for the EKS cluster"
  default     = "your-auth-token"
}

variable "fargate_pod_role_name" {
  description = "Name of the IAM role for Fargate pods"
  default     = "eks-fargate-pod-role"
}

variable "fargate_pod_role_arn" {
  description = "ARN of the IAM role for Fargate pods"
  default     = "arn:aws:iam::123456789012:role/eks-fargate-pod-role"
}

variable "fargate_profile_name" {
  description = "Name of the EKS Fargate profile"
  default     = "kube-system-fargate-profile"
}

variable "fargate_subnets" {
  description = "List of subnet IDs for the Fargate profile"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "fargate_namespace" {
  description = "Namespace for the Fargate profile"
  default     = "kube-system"
}

variable "fargate_pod_execution_role_policy" {
  description = "Policy ARN for Fargate pod execution"
  default     = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
}

resource "aws_iam_role" "fargate_pod_role" {
  name = var.fargate_pod_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "eks-fargate-pod.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "fargate_pod_role_policy" {
  role       = aws_iam_role.fargate_pod_role.name
  policy_arn = var.fargate_pod_execution_role_policy
}

resource "aws_eks_fargate_profile" "fargate_profile" {
  name        = var.fargate_profile_name
  cluster_name = var.eks_cluster_name
  namespace   = var.fargate_namespace
  pod_execution_role_arn = var.fargate_pod_role_arn

  subnet_ids = var.fargate_subnets

  tags = {
    eks: "fargate"
  }
}

resource "null_resource" "patch_coredns" {
  provisioner "local-exec" {
    command = <<EOT
      kubectl apply -f - <<EOF
      apiVersion: apps/v1
      kind: Deployment
      metadata:
        name: coredns
        namespace: kube-system
        annotations:
          eks.amazonaws.com/fargate: "true"
      spec:
        replicas: 1
        selector:
          matchLabels:
            k8s-app: coredns
        template:
          metadata:
            labels:
              k8s-app: coredns
          spec:
            containers:
            - name: coredns
              image: coredns/coredns:latest
              resources:
                limits:
                  memory: "128Mi"
                  cpu: "100m"
                requests:
                  memory: "64Mi"
                  cpu: "50m"
            imagePullSecrets:
            - name: regcred
      EOF
    EOT
  }

  depends_on = [aws_eks_fargate_profile.fargate_profile]
}
```

