---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "eks_cluster_name" {
  default = "example"
  description = "Name of the EKS cluster"
}

variable "node_group_name" {
  default = "example"
  description = "Name of the EKS node group"
}

variable "node_role_arn" {
  description = "ARN of the IAM role for the EKS node group"
  default = "arn:aws:iam::123456789012:role/eks-node-role"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the node group"
  default = ["subnet-12345678", "subnet-87654321"]
}

variable "iam_role_name" {
  default = "eks-node-role"
  description = "Name of the IAM role for the EKS node group"
}

variable "iam_role_policy_attachments" {
  description = "List of IAM policy names to attach to the node role"
  default = [
    "AmazonEKSServicePolicy",
    "AmazonEKSWorkerNodePolicy",
    "AmazonEC2ContainerRegistryReadOnlyPolicy"
  ]
}

