LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up an AWS S3 bucket and a DynamoDB table to be used for Terraform state management. The S3 bucket is configured with the following security and management features:

- **Versioning enabled** to allow recovery of previous versions of objects.
- **Server-side encryption (SSE-AES256)** to protect data at rest.
- **Block public access** to prevent unauthorized access.
- **Preventive measures against accidental deletion** using `versioning.rules` to lock specific versions.

The DynamoDB table is configured with:

- A **hash key named 'LockID'**.
- **PAY_PER_REQUEST** billing mode for Terraform locking.

The configuration includes IAM roles and policies to ensure proper access control for Terraform to interact with the S3 bucket and DynamoDB table.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket for Terraform state"
  default     = "terraform-state-bucket"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table for Terraform locking"
  default     = "terraform-lock-table"
}

resource "aws_s3_bucket" "terraform_state_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Prevent accidental deletion
  versioning {
    rule {
      id      = "prevent-accidental-deletion"
      status  = "Enabled"
      prefix  = ""
      expiration {
        days = 30
      }
    }
  }

  # Block public access
  block_public_access {
    block_public_acls        = true
    block_public_policy      = true
    ignore_public_acls       = true
    restrict_public_buckets  = true
  }
}

resource "aws_dynamodb_table" "terraform_lock_table" {
  name           = var.dynamodb_table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "LockID"
  read_capacity  = 1
  write_capacity = 1

  # IAM policy for Terraform to access the DynamoDB table
  dynamodb_table_iam_policy {
    name   = "terraform-lock-table-policy"
    users  = ["terraform"]
    actions = [
      "dynamodb:PutItem",
      "dynamodb:GetItem",
      "dynamodb:DeleteItem",
      "dynamodb:BatchGetItem"
    ]
  }
}

resource "aws_iam_role" "terraform_state_role" {
  name = "terraform-state-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "terraform_state_policy" {
  name = "terraform-state-policy"
  role = aws_iam_role.terraform_state_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:PutObject",
        "s3:GetObject",
        "s3:ListBucket",
        "s3:DeleteObject",
        "s3:PutObjectAcl",
        "s3:GetObjectAcl",
        "s3:ListBucketVersions",
        "s3:DeleteBucketPolicy"
      ]
      Resource = [
        "${aws_s3_bucket.terraform_state_bucket.arn}",
        "${aws_s3_bucket.terraform_state_bucket.arn}/*"
      ]
    }]
  })
}
```

---

**Note:** This configuration assumes that Terraform is running in an environment where it can assume the `terraform_state_role` to interact with the S3 bucket and DynamoDB table. You may need to adjust the IAM role and policy based on your specific use case or environment.

