```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_sns_topic" "s3_event_notification_topic" {
  name = "s3-event-notification-topic"
}

resource "aws_iam_policy" "s3_to_sns_policy" {
  name        = "s3-to-sns-policy"
  description = "Allows S3 to publish to SNS topic for object creation events"

  policy = jsonencode({
    "Version" = "2012-10-17"
    "Statement" = [{
      "Effect" = "Allow"
      "Action" = ["SNS:Publish"]
      "Resource" = [aws_sns_topic.s3_event_notification_topic.arn]
