**Description of the Terraform Program:**

This Terraform configuration creates a custom VPC with a CIDR block of `10.0.0.0/16` in the `us-east-1` region. It provisions two subnets: one in `us-east-1a` and another in `us-east-1b`. For each subnet, an EC2 instance is launched using the latest Amazon Linux 2 AMI with a `t2.micro` instance type. Each instance is also associated with a 50 GB EBS volume. The configuration includes necessary IAM roles and security groups to ensure the instances can communicate with the internet and have proper permissions.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_a_cidr" {
  description = "CIDR block for subnet in us-east-1a"
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr" {
  description = "CIDR block for subnet in us-east-1b"
  default     = "10.0.2.0/24"
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "Amazon Machine Image ID"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (2023.09)
}

variable "ebs_volume_size" {
  description = "Size of the EBS volume in GB"
  default     = 50
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_a_cidr
  availability_zone = "us-east-1a"
  tags = {
    Name = "subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_b_cidr
  availability_zone = "us-east-1b"
  tags = {
    Name = "subnet-b"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "main_route_table" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "main-route-table"
  }
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.main_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_security_group" "allow_all" {
  name        = "allow-all"
  description = "Allow all traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    self        = true
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_instance" "instance_a" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.subnet_a.id
  security_groups = [aws_security_group.allow_all.name]
  iam_instance_profile = aws_iam_role.ec2_role.name

  root_block_device {
    volume_size = var.ebs_volume_size
    volume_type = "gp2"
  }

  tags = {
    Name = "instance-a"
  }
}

resource "aws_instance" "instance_b" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.subnet_b.id
  security_groups = [aws_security_group.allow_all.name]
  iam_instance_profile = aws_iam_role.ec2_role.name

  root_block_device {
    volume_size = var.ebs_volume_size
    volume_type = "gp2"
  }

  tags = {
    Name = "instance-b"
  }
}
```

