**Description:**

This Terraform configuration creates a VPC with a public and private subnet. It defines an EC2 Fleet that includes a combination of 5 On-Demand and 4 Spot Instances, all running the latest AWS Linux 2 AMI. The fleet uses a Launch Template to ensure consistent instance configuration. The configuration includes necessary IAM roles and security groups to support the EC2 Fleet. The VPC is created in the `us-east-1` region, and all resources are defined with default values for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "instance_type" {
  description = "EC2 instance type for the fleet"
  default     = "t3.medium"
}

variable "key_name" {
  description = "Name of the EC2 key pair to use"
  default     = "my-key-pair"
}

variable "security_group_name" {
  description = "Name of the security group for the EC2 Fleet"
  default     = "ec2-fleet-sg"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = "us-east-1a"
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_security_group" "ec2_fleet_sg" {
  name        = var.security_group_name
  description = "Allow SSH and HTTP access for EC2 Fleet"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_template" "ec2_fleet_template" {
  name = "ec2-fleet-template"
  image_id = "ami-0c55b159cbfafe1f0" # AWS Linux 2 (ami-0c55b159cbfafe1f0) as of 2025-04-05
