**Description of the Terraform Program:**

This Terraform configuration creates a VPC with two private subnets. It provisions two of the newest AWS Linux 2 EC2 instances in those private subnets. Each EC2 instance is configured to mount an EFS (Elastic File System) file system for shared storage. The EFS file system is created in the same region as the VPC and is configured to be accessible from the private subnets. IAM roles are created to allow the EC2 instances to access the EFS file system and to launch the instances in the private subnets.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidr_1" {
  description = "CIDR block for the first private subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr_2" {
  description = "CIDR block for the second private subnet"
  default     = "10.0.2.0/24"
}

variable "instance_type" {
  description = "Type of EC2 instance to launch"
  default     = "t3.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instance (AWS Linux 2)"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (2023) in us-west-2
}

variable "efs_file_system_name" {
  description = "Name for the EFS file system"
  default     = "shared-efs"
}

variable "efs_security_group_id" {
  description = "Security group ID for EFS access"
  default     = "sg-0123456789abcdef0" # Placeholder, will be created
}

variable "key_pair_name" {
  description = "Name of the key pair to use for SSH access"
  default     = "terraform-key"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_1
  map_public_ip_on_launch = false
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_2
  map_public_ip_on_launch = false
  availability_zone = "us-west-2b"
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "private_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "private_subnet_1_assoc" {
  subnet_id      = aws_subnet.private_subnet_1.id
  route_table_id = aws_route_table.private_route_table.id
}

resource "aws_route_table_association" "private_subnet_2_assoc" {
  subnet_id      = aws_subnet.private_subnet_2.id
  route_table_id = aws_route_table.private_route_table.id
}

resource "aws_security_group" "efs_access_sg" {
  name        = var.efs_security_group_id
  description = "Allow EFS access from EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_efs_file_system" "efs" {
  creation_token = var.efs_file_system_name
}

resource "aws_efs_mount_target" "efs_mount_target_1" {
  file_system_id = aws_efs_file_system.efs.id
  subnet_id      = aws_subnet.private_subnet_1.id
  security_group_id = aws_security_group.efs_access_sg.id
}

resource "aws_efs_mount_target" "efs_mount_target_2" {
  file_system_id = aws_efs_file_system.efs.id
  subnet_id      = aws_subnet.private_subnet_2.id
  security_group_id = aws_security_group.efs_access_sg.id
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2-efs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_efs_access" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEFSFullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_ssm_access" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMAccessFullAccess"
}

resource "aws_instance" "ec2_instance_1" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private_subnet_1.id
  vpc_security_group_ids = [aws_security_group.efs_access_sg.id]
  iam_instance_profile = aws_iam_role.ec2_role.name
  key_name      = var.key_pair_name

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y amazon-efs-utils
    sudo mkdir /mnt/efs
    sudo mount -t efs ${aws_efs_file_system.efs.id}:/ /mnt/efs
    echo "efs mounted" >> /mnt/efs/mount_success.txt
  EOF
}

resource "aws_instance" "ec2_instance_2" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private_subnet_2.id
  vpc_security_group_ids = [aws_security_group.efs_access_sg.id]
  iam_instance_profile = aws_iam_role.ec2_role.name
  key_name      = var.key_pair_name

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y amazon-efs-utils
    sudo mkdir /mnt/efs
    sudo mount -t efs ${aws_efs_file_system.efs.id}:/ /mnt/efs
    echo "efs mounted" >> /mnt/efs/mount_success.txt
  EOF
}
