This Terraform configuration creates a Redis instance using AWS ElastiCache. It sets up a Redis cluster with a single node, configures the necessary security group, and ensures the instance is accessible via a public endpoint. The configuration includes a default VPC, security group, and Redis instance with a specified engine version and port. The Redis instance is configured to be publicly accessible for simplicity, though in production, it's recommended to use a private subnet and VPC endpoint.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "redis_instance_name" {
  description = "Name of the Redis instance"
  default     = "redis-instance"
}

variable "redis_engine_version" {
  description = "Engine version for Redis"
  default     = "redis6.x"
}

variable "redis_port" {
  description = "Port for Redis instance"
  default     = 6379
}

variable "redis_node_type" {
  description = "Node type for Redis instance"
  default     = "cache.r5.large"
}

variable "redis_subnet_id" {
  description = "Subnet ID for the Redis instance"
  default     = "subnet-0123456789abcdef0"
}

variable "redis_security_group_id" {
  description = "Security group ID for Redis instance"
  default     = "sg-0123456789abcdef0"
}

resource "aws_elasticache_cluster" "redis_cluster" {
  cluster_name           = var.redis_instance_name
  engine                 = "redis"
  engine_version         = var.redis_engine_version
  port                   = var.redis_port
  node_type              = var.redis_node_type
  num_cache_nodes        = 1
  subnet_group_name      = "default"
  security_group_ids     = [var.redis_security_group_id]
  auto_minor_version_upgrade = true
  maintenance_window    = "sun:05:00-sun:06:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"
  snapshot_retention_limit = 7
  snapshot_window        = "00:00-01:00"
  transit_encryption_enabled = true
  at_rest_encryption_enabled = true
  preferred_availability_zone = "us-east-1a"
  apply_immediately      = true
}

resource "aws_elasticache_subnet_group" "redis_subnet_group" {
  name       = "default"
  subnet_ids = [var.redis_subnet_id]
}
```

---

**Note:**  
- Replace the default values for `redis_subnet_id` and `redis_security_group_id` with actual values from your AWS environment before deployment.
- This configuration assumes a default VPC and subnet. For production use, consider creating a dedicated VPC and subnet group.

