**Description:**  
This Terraform configuration creates an ElastiCache user in AWS. The user is associated with a specific cache cluster or replication group. The configuration includes the necessary IAM role to ensure the user has the appropriate permissions to interact with ElastiCache resources. The IAM role is created and attached to the ElastiCache user to grant access.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cache_cluster_id" {
  description = "The ID of the ElastiCache cluster to associate the user with."
  default     = "my-cache-cluster"
}

variable "user_name" {
  description = "The name of the ElastiCache user."
  default     = "my-cache-user"
}

variable "password" {
  description = "The password for the ElastiCache user."
  default     = "SecureP@ssw0rd!"
  sensitive  = true
}

variable "iam_role_name" {
  description = "The name of the IAM role to be created for the ElastiCache user."
  default     = "elasti-cache-user-role"
}

resource "aws_elasticache_user" "cache_user" {
  user_id         = aws_elasticache_user.cache_user.id
  user_name       = var.user_name
  password        = var.password
  cache_cluster_id = var.cache_cluster_id
  engine = "redis"
}

resource "aws_iam_role" "elasti_cache_user_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticache.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "elasti_cache_user_policy" {
  name = "${var.iam_role_name}-policy"
  role = aws_iam_role.elasti_cache_user_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "elasticache:DescribeCacheClusters",
        "elasticache:DescribeReplicationGroups",
        "elasticache:DescribeUsers",
        "elasticache:CreateUser",
        "elasticache:ModifyUser",
        "elasticache:DeleteUser",
        "elasticache:AuthorizeCacheClusterSecurityGroupIngress",
        "elasticache:AuthorizeCacheSecurityGroupIngress",
        "elasticache:RevokeCacheClusterSecurityGroupIngress",
        "elasticache:RevokeCacheSecurityGroupIngress"
      ]
      Resource = "*"
    }]
  })
}
```

