**Description of the Terraform Program:**

This Terraform configuration creates a 2-node Amazon Redshift cluster with a specified concurrency scaling limit of 60 minutes. The cluster will be configured with the necessary IAM roles and security settings to ensure it can be managed and accessed securely. The configuration includes:

- A Redshift cluster with 2 nodes.
- A concurrency scaling limit set to 60 minutes.
- An IAM role for the Redshift cluster to access AWS services.
- A default region (us-east-1) and default IAM role name for flexibility.
- All required resources are declared and referenced properly.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_count" {
  description = "Number of nodes in the Redshift cluster"
  default     = 2
}

variable "concurrency_scaling_limit" {
  description = "Concurrency scaling limit in minutes"
  default     = 60
}

variable "iam_role_name" {
  description = "Name of the IAM role for Redshift"
  default     = "RedshiftServiceRole"
}

resource "aws_iam_role" "redshift_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_role_attachment" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftFullAccess"
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier           = var.cluster_name
  node_type                    = "dc2.large"
  number_of_nodes              = var.node_count
  database_name                = "mydb"
  master_username              = "admin"
  master_password              = "SecureP@ssw0rd!"
  port                         = 5439
  cluster_type                 = "multi-node"
  automated_snapshot_retention_period = 7
  iam_role_arn                 = aws_iam_role.redshift_role.arn
  concurrency_scaling_limit   = var.concurrency_scaling_limit
  skip_final_snapshot         = true
}
```

---

**Notes:**

- The `master_password` is hardcoded for simplicity, but in a production environment, it should be managed via a secure secret management system.
- The IAM role is attached with the `AmazonRedshiftFullAccess` policy to ensure the cluster has the necessary permissions.
- The `concurrency_scaling_limit` is set to 60 minutes as requested.
- The cluster is configured with 2 nodes and uses the `dc2.large` node type, which is a common choice for Redshift clusters.

