**Description of the Terraform Program:**

This Terraform configuration creates a single-node Amazon Redshift cluster and sets up an automated snapshot schedule to take snapshots every 12 hours. The configuration includes:

- A Redshift cluster with a single node.
- A Redshift snapshot schedule that runs every 12 hours.
- IAM roles and policies to ensure the Redshift cluster has the necessary permissions to create and manage snapshots.
- Default variables for cluster name, snapshot retention, and schedule interval.
- A valid AWS provider configuration in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the Redshift cluster"
  default     = "redshift-cluster-1"
}

variable "snapshot_retention" {
  description = "Number of days to retain snapshots"
  default     = 7
}

variable "snapshot_schedule_interval" {
  description = "Interval for snapshot schedule (e.g., '12h')"
  default     = "12h"
}

resource "aws_iam_role" "redshift_snapshot_role" {
  name = "redshift-snapshot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "redshift.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "redshift_snapshot_policy" {
  name = "redshift-snapshot-policy"
  role = aws_iam_role.redshift_snapshot_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "redshift:CreateClusterSnapshot",
        "redshift:DescribeClusterSnapshots",
        "redshift:DeleteClusterSnapshot"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = var.cluster_name
  node_type          = "dc2.large"
  number_of_nodes    = 1
  database_name      = "mydb"
  master_username    = "admin"
  master_password    = "SecureP@ssw0rd!"
  port               = 5439
  iam_role_arn       = aws_iam_role.redshift_snapshot_role.arn
}

resource "aws_redshift_snapshot_schedule" "snapshot_schedule" {
  cluster_identifier = aws_redshift_cluster.redshift_cluster.cluster_identifier
  schedule_identifier = "daily-snapshot-schedule"
  schedule_expression = var.snapshot_schedule_interval
  retention_days      = var.snapshot_retention
}
