**Description:**

This Terraform configuration sets up a highly available Amazon Redshift cluster across two Availability Zones (`us-east-1a` and `us-east-1b`) in the `us-east-1` region. The cluster is configured for high availability by using a multi-node cluster with a primary and standby node. The configuration includes:

- A Redshift cluster with a primary and standby node.
- A VPC with a public and private subnet in each Availability Zone.
- A security group to allow access to the Redshift cluster.
- IAM roles and policies to ensure the cluster can be managed securely.
- Default variables for easy customization.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the Redshift cluster"
  default     = "high-availability-redshift-cluster"
}

variable "cluster_version" {
  description = "Redshift cluster version"
  default     = "latest"
}

variable "node_type" {
  description = "Type of nodes to use for the cluster"
  default     = "ra3.4xlarge"
}

variable "number_of_nodes" {
  description = "Number of nodes in the cluster (must be at least 2 for HA)"
  default     = 2
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_a" {
  description = "CIDR block for the public subnet in us-east-1a"
  default     = "10.0.1.0/24"
}

variable "public_subnet_cidr_b" {
  description = "CIDR block for the public subnet in us-east-1b"
  default     = "10.0.2.0/24"
}

variable "private_subnet_cidr_a" {
  description = "CIDR block for the private subnet in us-east-1a"
  default     = "10.0.101.0/24"
}

variable "private_subnet_cidr_b" {
  description = "CIDR block for the private subnet in us-east-1b"
  default     = "10.0.102.0/24"
}

variable "security_group_id" {
  description = "Security group ID for the Redshift cluster"
  default     = "sg-0abcdef1234567890"
}

variable "iam_role_arn" {
  description = "ARN of the IAM role for the Redshift cluster"
  default     = "arn:aws:iam::123456789012:role/redshift-cluster-role"
}

resource "aws_vpc" "redshift_vpc" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet_a" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = var.public_subnet_cidr_a
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "public_subnet_b" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = var.public_subnet_cidr_b
  map_public_ip_on_launch = true
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "private_subnet_a" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = var.private_subnet_cidr_a
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "private_subnet_b" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = var.private_subnet_cidr_b
  availability_zone = "us-east-1b"
}

resource "aws_internet_gateway" "redshift_igw" {
  vpc_id = aws_vpc.redshift_vpc.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.redshift_vpc.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.redshift_igw.id
}

resource "aws_route_table_association" "public_subnet_a_assoc" {
  subnet_id      = aws_subnet.public_subnet_a.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table_association" "public_subnet_b_assoc" {
  subnet_id      = aws_subnet.public_subnet_b.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-cluster-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.redshift_vpc.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
