---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster."
  default     = "my-redshift-cluster"
}

variable "number_of_nodes" {
  description = "The number of nodes in the Redshift cluster."
  default     = 2
}

variable "iam_role_name" {
  description = "The name of the IAM role to be created."
  default     = "RedshiftClusterRole"
}

resource "aws_iam_role" "redshift_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "redshift.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_role_policy" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftFullAccess"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier    = var.cluster_identifier
  node_type             = "dc2.large"
  number_of_nodes       = var.number_of_nodes
  iam_role_arn          = aws_iam_role.redshift_role.arn
  cluster_type          = "multi-node"
