  default     = 2
}

variable "iam_role_name" {
  description = "The name of the IAM role for the Redshift cluster."
  default     = "RedshiftClusterRole"
}

resource "aws_iam_role" "redshift_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
