**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lambda function with the following components:

- An IAM role that allows the Lambda function to execute.
- An IAM policy document that grants the necessary permissions for the Lambda function to run.
- A Lambda function using the `nodejs18.x` runtime, with a specified handler and source file (`lambda.js`).
- A ZIP archive file containing the Lambda function code.

The configuration includes a provider block for AWS in the `us-east-1` region and ensures all resources are properly defined and referenced.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  default     = "my-lambda-function"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the Lambda function"
  default     = "lambda-execution-role"
}

variable "lambda_handler" {
  description = "The handler for the Lambda function"
  default     = "lambda.handler"
}

variable "lambda_source_file" {
  description = "The source file for the Lambda function"
  default     = "lambda.js"
}

resource "aws_iam_role" "lambda_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  name = "${var.iam_role_name}-policy"
  role = aws_iam_role.lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_lambda_function" "lambda_function" {
  function_name    = var.lambda_function_name
  handler          = var.lambda_handler
  runtime          = "nodejs18.x"
  role             = aws_iam_role.lambda_role.arn
  filename         = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")
  timeout          = 30
}

resource "local_file" "lambda_zip" {
  filename = "lambda.zip"
  content  = filebase64("lambda.js")
}
```

---

**Note:**  
You need to have a `lambda.js` file in the same directory as this Terraform configuration. This file will be zipped and used as the Lambda function's code. The `local_file` resource creates a ZIP file from the `lambda.js` source file. You can replace `lambda.js` with your actual Lambda function code.

