**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lambda function named "example_lambda" and sets up an IAM role for it. The Lambda function is configured to be invoked by itself, which is a simple example of a self-invoking Lambda function. The configuration includes:

- An IAM role for the Lambda function with the necessary permissions.
- A Lambda function with a basic handler and runtime.
- A Lambda invocation policy to allow the function to invoke itself.
- A provider block for AWS in the `us-east-1` region.

All resources are defined explicitly, and no external variables are used. The configuration is ready to be deployed using Terraform 1.9.8 or later.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  name = "lambda_policy"
  role = aws_iam_role.lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = "lambda:InvokeFunction"
      Resource = "arn:aws:lambda:${aws_region.current.name}:${aws_caller_identity.current.account_id}:function:example_lambda"
    }]
  })
}

resource "aws_lambda_function" "example_lambda" {
  function_name    = "example_lambda"
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda.zip"
  role             = aws_iam_role.lambda_role.arn
  source_code_hash = "base64:example_lambda_code"
  timeout          = 30

  environment {
    variables = {
      ENVIRONMENT = "dev"
    }
  }
}
```

