**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lambda function named `test_lambda` that is triggered by an EC2 image creation event. To achieve this, we will:

1. Create an IAM role for the Lambda function with the necessary permissions to invoke the Lambda function.
2. Create an IAM role for EC2 instances that allows them to publish events to Amazon CloudWatch Events.
3. Create a CloudWatch Events rule that triggers the Lambda function when an EC2 image is created.
4. Create the Lambda function with the specified IAM role and a basic handler (e.g., a simple "Hello World" function).
5. Ensure all resources are properly configured and referenced.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM role for EC2 instances to allow publishing events to CloudWatch Events
resource "aws_iam_role" "ec2_role" {
  name = "ec2-cloudwatch-events-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_events" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchEventsFullAccess"
}

# IAM role for Lambda function
resource "aws_iam_role" "lambda_role" {
  name = "lambda-test-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  name = "lambda-test-policy"
  role = aws_iam_role.lambda_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# CloudWatch Events rule to trigger Lambda on EC2 image creation
resource "aws_cloudwatch_event_rule" "ec2_image_created" {
  name = "ec2-image-created-rule"

  event_pattern = jsonencode({
    source = ["aws.ec2"]
    detail = {
      eventSource = ["ec2.amazonaws.com"]
      eventName   = ["CreateImage"]
    }
  })
}

# Lambda function to be triggered
resource "aws_lambda_function" "test_lambda" {
  function_name    = "test_lambda"
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  source_code_hash = "base64:example-base64-encoded-hash"
  timeout          = 30

  # Example inline code for the Lambda function
  source_code = <<EOF
exports.handler = async (event) => {
  console.log("EC2 image created event received:", event);
  return {
    statusCode: 200,
    body: JSON.stringify('Lambda triggered by EC2 image creation'),
  };
};
EOF
}
```

---

**Note:**  
- The `source_code_hash` and `filename` fields are placeholders. In a real deployment, you would need to provide the actual ZIP file containing your Lambda code.
- The `source_code` block is an example of a simple Lambda function in Node.js. You can replace it with your own logic.
- This configuration assumes you are using the `us-east-1` region. You can change the region as needed.

