LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lambda function that runs a JavaScript file named `lambda.js`. The Lambda function is deployed in the `us-east-1` region. The configuration includes:

- A Lambda function with a specified handler and runtime (Node.js 18.x).
- A ZIP file containing the `lambda.js` file, which is uploaded as the Lambda function's code.
- An IAM role for the Lambda function to execute with basic permissions.
- A provider block configured for AWS in the `us-east-1` region.

Variables are used to allow customization of the function name, role name, and file path, with default values provided.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  default     = "my-lambda-function"
}

variable "lambda_role_name" {
  description = "Name of the IAM role for the Lambda function"
  default     = "lambda-execution-role"
}

variable "lambda_file_path" {
  description = "Path to the lambda.js file"
  default     = "lambda.js"
}

resource "aws_iam_role" "lambda_role" {
  name = var.lambda_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "lambda_function" {
  function_name    = var.lambda_function_name
  handler          = "lambda.handler"
  runtime          = "nodejs18.x"
  role             = aws_iam_role.lambda_role.arn
  filename         = "lambda.zip"
  source_code_hash = filebase64sha256(var.lambda_file_path)
  timeout          = 30
}

resource "local_file" "lambda_zip" {
  content = filebase64(var.lambda_file_path)
  filename = "lambda.zip"
}
```

---

**Note:** This configuration assumes that the `lambda.js` file is present in the same directory as the Terraform configuration and that it contains a valid Lambda handler function (e.g., `exports.handler = async (event) => { ... };`). You can customize the `lambda_file_path` variable if the file is located elsewhere.

