**Description:**  
This Terraform configuration creates a CloudWatch Metric Alarm resource in AWS. The alarm is configured to monitor the CPU utilization of an EC2 instance. The alarm will trigger an alert if the CPU usage exceeds 70% for a duration of 5 minutes. The configuration includes a default EC2 instance ID, which can be customized as needed. The provider is configured for the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "ec2_instance_id" {
  description = "The ID of the EC2 instance to monitor."
  default     = "i-1234567890abcdef0"
}

variable "alarm_name" {
  description = "The name of the CloudWatch Metric Alarm."
  default     = "HighCPUUsageAlarm"
}

variable "threshold" {
  description = "The threshold percentage for CPU utilization."
  default     = 70
}

variable "evaluation_periods" {
  description = "The number of periods over which data is evaluated."
  default     = 5
}

variable "comparison_operator" {
  description = "The comparison operator to use for the alarm."
  default     = "GreaterThanThreshold"
}

variable "alarm_description" {
  description = "A description for the CloudWatch Metric Alarm."
  default     = "Triggers when CPU utilization exceeds 70% for 5 minutes."
}

resource "aws_cloudwatch_metric_alarm" "cpu_alarm" {
  alarm_name          = var.alarm_name
  comparison_operator = var.comparison_operator
  evaluation_periods  = var.evaluation_periods
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  statistic           = "Average"
  threshold           = var.threshold
  period              = 300
  alarm_description   = var.alarm_description
  dimensions = {
    InstanceId = var.ec2_instance_id
  }
}
```

**Description:**

This Terraform configuration defines an AWS CloudWatch Metric Alarm named 'foobar' that monitors the average CPUUtilization metric of EC2 instances. The alarm is configured to trigger when the CPU utilization is greater than or equal to 80% for two consecutive 2-minute periods. The alarm will not take any actions when there is insufficient data. The configuration includes a valid AWS provider setup in the 'us-east-1' region and uses default values for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "alarm_name" {
  description = "Name of the CloudWatch Metric Alarm"
  default     = "foobar"
}

variable "metric_name" {
  description = "Name of the metric to monitor"
  default     = "CPUUtilization"
}

variable "namespace" {
  description = "Namespace of the metric"
  default     = "AWS/EC2"
}

variable "dimensions" {
  description = "Dimensions for the metric (e.g., {InstanceId = "i-1234567890abcdef0"}"
  default     = "{InstanceId = \"i-1234567890abcdef0\"}"
}

variable "threshold" {
  description = "Threshold value for the alarm"
  default     = 80
}

variable "comparison_operator" {
  description = "Comparison operator for the alarm"
  default     = "GreaterThanOrEqualToThreshold"
}

variable "evaluation_periods" {
  description = "Number of periods to evaluate"
  default     = 2
}

variable "period" {
  description = "Length of each period in seconds"
  default     = 120
}

variable "alarm_actions" {
  description = "List of alarm actions (e.g., SNS topics, Auto Scaling policies)"
  default     = []
}

variable "ok_actions" {
  description = "List of OK actions"
  default     = []
}

variable "insufficient_data_actions" {
  description = "List of actions to take when there is insufficient data"
  default     = []
}

resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = var.alarm_name
  metric_name         = var.metric_name
  namespace           = var.namespace
  dimensions          = var.dimensions
  period              = var.period
  evaluation_periods  = var.evaluation_periods
  threshold           = var.threshold
  comparison_operator = var.comparison_operator
  alarm_actions        = var.alarm_actions
  ok_actions           = var.ok_actions
  insufficient_data_actions = var.insufficient_data_actions
  treat_missing_data   = "notBreaching"
}
```

