**Description of the Terraform Program:**

This Terraform configuration creates a Kinesis Streaming Destination that points to a specific DynamoDB table. It includes the necessary AWS resources such as a DynamoDB table, a Kinesis stream, and a Kinesis Firehose delivery stream that writes data from the Kinesis stream to the DynamoDB table. The configuration also includes IAM roles and policies to ensure proper permissions for the resources to interact with each other.

The following resources are created:
- A DynamoDB table with a specified name and provisioned capacity.
- A Kinesis stream with a specified number of shards.
- A Kinesis Firehose delivery stream that delivers data from the Kinesis stream to the DynamoDB table.
- IAM roles and policies to allow the Kinesis Firehose to write to the DynamoDB table and for the Kinesis stream to interact with the Firehose.

Variables are used to make the configuration flexible, with default values provided for each.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table to use as the destination."
  default     = "kinesis-dynamodb-destination"
}

variable "kinesis_stream_name" {
  description = "Name of the Kinesis stream."
  default     = "kinesis-stream"
}

variable "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream."
  default     = "kinesis-firehose-delivery"
}

variable "kinesis_shard_count" {
  description = "Number of shards for the Kinesis stream."
  default     = 1
}

variable "dynamodb_provisioned_read_capacity" {
  description = "Provisioned read capacity units for the DynamoDB table."
  default     = 5
}

variable "dynamodb_provisioned_write_capacity" {
  description = "Provisioned write capacity units for the DynamoDB table."
  default     = 5
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = var.dynamodb_table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = var.dynamodb_provisioned_read_capacity
  write_capacity = var.dynamodb_provisioned_write_capacity

  attribute {
    name = "partitionKey"
    type = "S"
  }

  key_schema {
    attribute_name = "partitionKey"
    key_type       = "HASH"
  }
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name        = var.kinesis_stream_name
  shard_count = var.kinesis_shard_count
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "firehose.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "firehose_dynamodb_policy" {
  name = "firehose-dynamodb-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "dynamodb:PutItem",
        "dynamodb:PutRecord",
        "dynamodb:DescribeTable",
        "dynamodb:ListTables"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery" {
  name        = var.firehose_delivery_stream_name
  destination = "dynamodb"

  dynamodb_configuration {
    table_name          = aws_dynamodb_table.dynamodb_table.name
    role_arn            = aws_iam_role.firehose_role.arn
    processing_configuration {
      enabled = false
    }
  }

  depends_on = [aws_iam_role_policy.firehose_dynamodb_policy]
}
```

