---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The name of the SageMaker Domain."
  default     = "default-sagemaker-domain"
}

variable "iam_role_arn" {
  description = "The ARN of the IAM role to be used by the SageMaker Domain."
