**Description of the Terraform Program:**

This Terraform configuration creates a SageMaker JupyterServer application within an AWS SageMaker domain. The JupyterServer is configured with a specific IAM role that allows it to access necessary AWS services. The configuration includes a provider block for AWS, a SageMaker domain (if not already existing), and the JupyterServer application resource. The IAM role is created with the necessary permissions to support the JupyterServer functionality.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "sagemaker_domain_name" {
  description = "Name of the SageMaker domain"
  default     = "default-domain"
}

variable "sagemaker_app_name" {
  description = "Name of the JupyterServer application"
  default     = "jupyter-server-app"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the JupyterServer"
  default     = "sagemaker-jupyter-server-role"
}

resource "aws_iam_role" "sagemaker_jupyter_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "sagemaker.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_jupyter_policy" {
  role       = aws_iam_role.sagemaker_jupyter_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
}

resource "aws_sagemaker_domain" "sagemaker_domain" {
  domain_name = var.sagemaker_domain_name
  auth_mode   = "SageMakerStudioAuth"
}

resource "aws_sagemaker_app" "sagemaker_jupyter_app" {
  domain_id    = aws_sagemaker_domain.sagemaker_domain.domain_id
  app_name     = var.sagemaker_app_name
  app_type     = "JupyterServer"
  role_arn     = aws_iam_role.sagemaker_jupyter_role.arn
  lifecycle    = "Enabled"
}
```

