**Description of the Terraform Program:**

This Terraform configuration creates an AWS SageMaker model that uses the `kmeans` image. The model is built using the `aws_sagemaker_model` resource, which defines the model's name, the container image, and the execution role. The execution role is created using an IAM role and policy to grant the necessary permissions for SageMaker to operate.

The configuration includes:
- A default IAM role with the necessary permissions for SageMaker.
- A SageMaker model resource that uses the `kmeans` image.
- A provider block for AWS in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "model_name" {
  description = "Name of the SageMaker model"
  default     = "kmeans-model"
}

variable "role_arn" {
  description = "ARN of the IAM role to be used by the SageMaker model"
  default     = "arn:aws:iam::123456789012:role/sagemaker-role"
}

resource "aws_iam_role" "sagemaker_role" {
  name = "sagemaker-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "sagemaker.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "sagemaker_policy" {
  name = "sagemaker-policy"
  role = aws_iam_role.sagemaker_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:ListBucket"
      ]
      Resource = "*"
    },
    {
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = "arn:aws:logs:*:*:*"
    }]
  ])
}

resource "aws_sagemaker_model" "kmeans_model" {
  name         = var.model_name
  execution_role_arn = var.role_arn

  containers {
    image = "175324221121.dkr.ecr.us-east-1.amazonaws.com/eks-ml-pipeline-kmeans:latest"
    model_data_url = "s3://my-bucket/kmeans-model.tar.gz"
    mode = "SingleModel"
  }
}
```

