**Description:**

This Terraform configuration creates a SageMaker endpoint configuration for a given SageMaker model. The endpoint configuration defines the settings for the endpoint, such as the production variant, which includes the model, instance type, and other deployment parameters. The configuration assumes a SageMaker model already exists and is referenced by its ARN. It also includes a default region and provider configuration for AWS.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "sagemaker_model_arn" {
  description = "The Amazon Resource Name (ARN) of the SageMaker model."
  type        = string
  default     = "arn:aws:sagemaker:us-east-1:123456789012:model/my-model"
}

variable "endpoint_name" {
  description = "The name of the SageMaker endpoint."
  type        = string
  default     = "my-sagemaker-endpoint"
}

variable "production_variant_name" {
  description = "The name of the production variant."
  type        = string
  default     = "variant-1"
}

variable "instance_type" {
  description = "The instance type for the production variant."
  type        = string
  default     = "ml.m5.large"
}

variable "initial_instance_count" {
  description = "The initial number of instances for the production variant."
  type        = number
  default     = 1
}

resource "aws_sagemaker_endpoint_configuration" "sagemaker_endpoint_config" {
  name         = var.endpoint_name
  production_variant {
    variant_name         = var.production_variant_name
    model_name           = data.aws_sagemaker_model.model.name
    instance_type        = var.instance_type
    initial_instance_count = var.initial_instance_count
  }
}

data "aws_sagemaker_model" "model" {
  arn = var.sagemaker_model_arn
}
```

---

**Note:** This configuration assumes that the SageMaker model ARN is known and valid. If you're deploying this in a real environment, ensure that the model exists in the specified AWS region and that the IAM role used by Terraform has the necessary permissions to create and manage SageMaker endpoints.

