**Description of the Terraform Program:**

This Terraform configuration creates a new Amazon Linux 2 AMI using AWS EC2. The AMI is built by launching a temporary instance with the specified CPU count (2 vCPUs) and cores per thread (2 cores per thread). The instance is configured to run a script that installs and configures the system, then creates a snapshot of the resulting AMI. The AMI is tagged for easy identification.

The configuration includes:
- A VPC and subnet (default configuration).
- A security group allowing SSH access.
- A launch template with the specified CPU and core settings.
- A temporary EC2 instance to build the AMI.
- A script to install and configure the system.
- A snapshot of the instance's root volume to create the AMI.
- A final AMI resource with a name and description.

Variables are provided with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "ami_name" {
  description = "Name for the new AMI"
  default     = "amazon-linux-2-custom-ami"
}

variable "instance_type" {
  description = "EC2 instance type to use for building the AMI"
  default     = "t2.medium"
}

variable "cpu_count" {
  description = "Number of vCPUs for the AMI"
  default     = 2
}

variable "cores_per_thread" {
  description = "Number of cores per thread for the AMI"
  default     = 2
}

variable "key_pair_name" {
  description = "Name of the key pair to use for SSH access"
  default     = "terraform-key"
}

variable "security_group_name" {
  description = "Name of the security group to allow SSH access"
  default     = "terraform-ami-builder"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "allow_ssh" {
  name        = var.security_group_name
  description = "Allow SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_template" "builder" {
  name          = "ami-builder-launch-template"
  description   = "Launch template for building AMI"
  instance_type = var.instance_type

  vpc_id       = aws_vpc.main.id
  subnet_id    = aws_subnet.main.id
  security_groups = [aws_security_group.allow_ssh.id]

  key_name = var.key_pair_name

  user_data = <<EOF
#!/bin/bash
yum update -y
yum install -y httpd
systemctl start httpd
systemctl enable httpd
echo "Custom AMI built" > /var/www/html/index.html
EOF
}

resource "aws_instance" "builder" {
  launch_template {
    id      = aws_launch_template.builder.id
    version = 1
  }

  tags = {
    Name = "ami-builder"
  }
}

resource "aws_ami" "custom_ami" {
  name        = var.ami_name
  description = "Custom Amazon Linux 2 AMI with specified CPU and core settings"
  instance_id = aws_instance.builder.id
  tags = {
    Name = var.ami_name
  }
}
```

---

**Note:** This configuration assumes that the key pair `terraform-key` exists in your AWS account and that you have the necessary permissions to create AMIs. You can customize the `user_data` script to perform additional setup tasks as needed.

