**Description of the Terraform Program:**

This Terraform configuration creates a new Amazon Machine Image (AMI) based on the latest Amazon Linux 2 AMI. It uses the AWS provider to launch an EC2 instance, install necessary packages, and create a custom AMI from that instance. The AMI is tagged for easy identification and cleanup. The configuration includes a default AMI ID, which can be overridden if needed.

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "ami_name" {
  description = "Name for the custom AMI"
  default     = "custom-amazon-linux-2"
}

variable "instance_type" {
  description = "Type of EC2 instance to use for creating the AMI"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "Base AMI ID to use (e.g., Amazon Linux 2)"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (2023.09) in us-east-1
}

variable "key_name" {
  description = "Name of the EC2 key pair to use"
  default     = "my-key-pair"
}

variable "security_group_name" {
  description = "Name of the security group to use"
  default     = "allow-ssh"
}

resource "aws_security_group" "allow_ssh" {
  name        = var.security_group_name
  description = "Allow SSH access"
  vpc_id      = aws_vpc.default.id

  ingress {
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "terraform-vpc"
  }
}

resource "aws_instance" "ami_builder" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  security_groups = [aws_security_group.allow_ssh.name]
  vpc_id        = aws_vpc.default.id

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    yum install -y httpd
    systemctl start httpd
    systemctl enable httpd
    echo "Custom AMI" > /var/www/html/index.html
    EOF

  tags = {
    Name = "ami-builder"
  }
}

resource "aws_imagebuilder_image" "custom_ami" {
  name        = var.ami_name
  description = "Custom Amazon Linux 2 AMI"
  image_build_version = "1"
  image_recipe_arn = "arn:aws:imagebuilder:us-east-1:137112412989:recipe/amazon-linux-2/amazon-linux-2-20230905-x86_64"
  image_scanning_configuration {
    image_scanning_enabled = true
  }
  tags = {
    Name = var.ami_name
  }
}

resource "aws_imagebuilder_image_pipeline" "custom_ami_pipeline" {
  name        = var.ami_name
  description = "Custom AMI pipeline"
  image_recipe_arn = "arn:aws:imagebuilder:us-east-1:137112412989:recipe/amazon-linux-2/amazon-linux-2-20230905-x86_64"
  image_scanning_configuration {
    image_scanning_enabled = true
  }
  output_bucket_name = "terraform-ami-output-bucket"
  schedule {
    schedule_expression = "rate(1 hour)"
  }
  tags = {
    Name = var.ami_name
  }
}
```

**Notes:**
- This configuration assumes you have an S3 bucket named `terraform-ami-output-bucket` in the same region (`us-east-1`) for storing the AMI.
- The `image_recipe_arn` is for Amazon Linux 2 (2023.09) and may need to be updated if a newer version is required.
- The `aws_imagebuilder_image` and `aws_imagebuilder_image_pipeline` resources are used to create and manage the AMI using AWS Image Builder.

