  image_id = "ami-0c55b159cbfafe1f0" # AWS Linux 2 (ami-0c55b159cbfafe1f0 is the latest as of 2025-04)
  instance_type = var.instance_type
  key_name = var.key_name
  security_groups = [aws_security_group.ec2_fleet_sg.id]

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 20
      volume_type = "gp2"
    }
  }

  networkInterfaces {
    subnet_id = aws_subnet.public.id
    security_groups = [aws_security_group.ec2_fleet_sg.id]
  }

  user_data = <<-EOF
              #!/bin/bash
              echo "Hello from EC2 Fleet" > /var/www/html/index.html
              EOF
}

resource "aws_ec2_fleet" "ec2_fleet" {
  name = "ec2-fleet"
  launch_template {
    launch_template_id = aws_launch_template.ec2_fleet_template.id
    version = "$Latest"
  }

  target_capacity {
    on_demand_capacity = 5
    spot_capacity = 4
    default_target_capacity_type = "spot"
  }

  context {
    key = "spot_price"
    value = var.spot_price
  }

  context {
    key = "instance_type"
    value = var.instance_type
  }

  context {
    key = "launch_template_name"
    value = "ec2-fleet-launch-template"
  }
}
