LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates two latest AWS Linux instances in private subnets, each configured to mount a shared EFS (Elastic File System) file system. The instances are launched in a specified VPC with private subnets, and an IAM role is created to allow them to mount the EFS file system. The EFS file system is created and configured with a lifecycle policy to retain data. All resources are deployed in a single AWS region, and default values are provided for variables to ensure the configuration is deployable without additional input.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the instances."
  default     = "vpc-12345678"
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs to launch the instances."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "instance_type" {
  description = "The type of EC2 instance to launch."
  default     = "t3.micro"
}

variable "key_name" {
  description = "The name of the EC2 key pair to use."
  default     = "my-key-pair"
}

variable "efs_file_system_name" {
  description = "Name for the EFS file system."
  default     = "shared-efs"
}

variable "efs_lifecycle_policy" {
  description = "Lifecycle policy for the EFS file system (e.g., 'retain')."
  default     = "retain"
}

resource "aws_iam_role" "efs_access_role" {
  name = "efs-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "efs_access_policy" {
  role       = aws_iam_role.efs_access_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEFSFullAccess"
}

resource "aws_efs_file_system" "efs" {
  creation_token = var.efs_file_system_name
  lifecycle_policy = var.efs_lifecycle_policy
}

resource "aws_efs_mount_target" "efs_mount_targets" {
  for_each = toset(var.private_subnet_ids)
  file_system_id = aws_efs_file_system.efs.id
  subnet_id       = each.value
  security_groups = [aws_security_group.efs_sg.id]
}

resource "aws_security_group" "efs_sg" {
  name        = "efs-sg"
  description = "Allow EFS access"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "linux_instances" {
  count             = 2
  ami              = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 (latest)
  instance_type    = var.instance_type
  key_name         = var.key_name
  subnet_id        = var.private_subnet_ids[count.index]
  vpc_id           = var.vpc_id
  security_groups  = [aws_security_group.efs_sg.id]
  iam_instance_profile = aws_iam_role.efs_access_role.name

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y amazon-efs-utils
    sudo mkdir /mnt/efs
    sudo mount -t efs ${aws_efs_file_system.efs.id}:/ /mnt/efs
    echo "EFS mounted successfully"
  EOF
}
```

