**Description of the Terraform Program:**

This Terraform configuration creates 3 EC2 instances within an EC2 placement group using the **clustering** strategy. The instances will be launched in the same Availability Zone to ensure they are tightly coupled for high performance and low latency. The configuration includes:

- A VPC with a public subnet.
- A security group allowing SSH access.
- An EC2 placement group with the `clustering` strategy.
- 3 EC2 instances launched within the placement group.
- A default IAM role for the instances to allow basic EC2 operations.
- A default region (`us-east-1`) and default AMI (`ami-0c55b159cbfafe1f0` for Amazon Linux 2).

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_count" {
  description = "Number of EC2 instances to create"
  default     = 3
}

variable "instance_type" {
  description = "Type of EC2 instance"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "Amazon Machine Image ID"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
}

variable "key_name" {
  description = "EC2 key pair name"
  default     = "my-key-pair"
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "allow-ssh"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_security_group" "allow_ssh" {
  name        = var.security_group_name
  description = "Allow SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.security_group_name
  }
}

resource "aws_placement_group" "clustering" {
  name = "clustering-group"
  strategy = "cluster"
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_instance" "cluster_instances" {
  count             = var.instance_count
  ami              = var.ami_id
  instance_type    = var.instance_type
  subnet_id        = aws_subnet.public.id
  security_groups  = [aws_security_group.allow_ssh.name]
  iam_instance_profile = aws_iam_role.ec2_role.name
  key_name         = var.key_name
  placement {
    group_name = aws_placement_group.clustering.name
  }
  tags = {
    Name = "cluster-instance-${count.index}"
  }
}
```

