**Description:**  
To reduce the number of database calls, we can implement a caching layer using Amazon ElastiCache (Redis). This resource will create a Redis cache cluster that can be used to store frequently accessed data, thereby reducing the load on the database and improving application performance.

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cache_cluster_name" {
  description = "Name of the ElastiCache Redis cluster"
  default     = "my-redis-cache"
}

variable "cache_node_type" {
  description = "Type of cache node to use"
  default     = "cache.r5.large"
}

variable "cache_engine_version" {
  description = "Version of Redis engine to use"
  default     = "redis6.x"
}

variable "num_cache_nodes" {
  description = "Number of cache nodes in the cluster"
  default     = 1
}

variable "cache_subnet_group_name" {
  description = "Name of the subnet group for the cache"
  default     = "my-redis-subnet-group"
}

variable "cache_security_group_name" {
  description = "Name of the security group for the cache"
  default     = "my-redis-sg"
}

resource "aws_elasticache_cluster" "redis_cache" {
  cluster_name           = var.cache_cluster_name
  engine                 = "redis"
  engine_version         = var.cache_engine_version
  node_type              = var.cache_node_type
  num_cache_nodes        = var.num_cache_nodes
  cache_subnet_group_name = var.cache_subnet_group_name
  security_group_ids     = [aws_security_group.redis_cache_sg.id]

  tags = {
    Environment = "production"
    Purpose     = "Caching"
  }
}

resource "aws_security_group" "redis_cache_sg" {
  name        = var.cache_security_group_name
  description = "Security group for Redis cache"

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = "production"
    Purpose     = "Caching"
  }
}

resource "aws_subnet" "redis_subnet" {
  count                   = 2
  cidr_block              = "10.0.${count.index + 1}.0/24"
  availability_zone       = "us-west-2a"
  vpc_id                  = aws_vpc.main.id
  map_public_ip_on_launch = true

  tags = {
    Environment = "production"
    Purpose     = "Caching"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Environment = "production"
    Purpose     = "Caching"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Environment = "production"
    Purpose     = "Caching"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Environment = "production"
    Purpose     = "Caching"
  }
}

resource "aws_route_table_association" "main" {
  count          = length(aws_subnet.redis_subnet)
  subnet_id      = aws_subnet.redis_subnet[count.index].id
  route_table_id = aws_route_table.main.id
}
```

**Note:**  
This configuration assumes that the necessary VPC, subnets, and internet gateway are already set up. If not, the VPC and subnet resources are created as part of this configuration. You can adjust the `cidr_block`, `availability_zone`, and other parameters as needed for your environment.

