**Description of the Terraform Program:**

This Terraform configuration creates an AWS ElastiCache cluster and an IAM user with the necessary permissions to authenticate and interact with the ElastiCache cluster. The IAM user is granted access via an IAM access key and secret key, which are stored securely in AWS Secrets Manager. The configuration includes:

- An IAM role for the ElastiCache cluster to allow it to access other AWS services.
- An IAM user with programmatic access and permissions to manage ElastiCache.
- A Secrets Manager secret to store the IAM user's access key and secret key.
- A Redis ElastiCache cluster with a single node.
- A security group to allow access to the ElastiCache cluster.

All resources are created in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "elasti_cache_cluster_name" {
  description = "Name of the ElastiCache cluster"
  default     = "my-redis-cluster"
}

variable "elasti_cache_node_type" {
  description = "Type of node for the ElastiCache cluster"
  default     = "cache.r5.large"
}

variable "elasti_cache_engine" {
  description = "Engine for the ElastiCache cluster (e.g., redis, memcached)"
  default     = "redis"
}

variable "elasti_cache_engine_version" {
  description = "Engine version for the ElastiCache cluster"
  default     = "7.0"
}

variable "iam_user_name" {
  description = "Name of the IAM user to authenticate with ElastiCache"
  default     = "elasti-cache-user"
}

variable "iam_user_password" {
  description = "Password for the IAM user (used for Secrets Manager)"
  default     = "SecureP@ssw0rd!"
}

resource "aws_iam_role" "elasti_cache_role" {
  name = "elasti-cache-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "elasticache.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "elasti_cache_role_policy" {
  role       = aws_iam_role.elasti_cache_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElastiCacheFullAccess"
}

resource "aws_iam_user" "elasti_cache_user" {
  name = var.iam_user_name
}

resource "aws_iam_access_key" "elasti_cache_user_access_key" {
  user = aws_iam_user.elasti_cache_user.name
}

resource "aws_secretsmanager_secret" "elasti_cache_user_credentials" {
  name = "elasti-cache-user-credentials"
}

resource "aws_secretsmanager_secret_version" "elasti_cache_user_credentials_version" {
  secret_id     = aws_secretsmanager_secret.elasti_cache_user_credentials.id
  secret_string = jsonencode({
    access_key = aws_iam_access_key.elasti_cache_user_access_key.id
    secret_key = aws_iam_access_key.elasti_cache_user_access_key.secret
  })
}

resource "aws_elasticache_cluster" "elasti_cache_cluster" {
  cluster_name           = var.elasti_cache_cluster_name
  engine                 = var.elasti_cache_engine
  engine_version         = var.elasti_cache_engine_version
  node_type              = var.elasti_cache_node_type
  num_cache_nodes        = 1
  port                   = 6379
  security_group_ids     = [aws_security_group.elasti_cache_sg.id]
  subnet_group_name      = "default"
  auto_minor_version_upgrade = true
}

resource "aws_security_group" "elasti_cache_sg" {
  name        = "elasti-cache-sg"
  description = "Security group for ElastiCache cluster"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
}
```

