LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates a Managed Streaming for Kafka (MSK) cluster with 3 broker nodes. The cluster is deployed in AWS using the `hashicorp/aws` provider. The configuration includes:

- A VPC with a public and private subnet.
- A security group allowing access to the MSK brokers.
- An IAM role for the MSK cluster to interact with other AWS services.
- The MSK cluster itself with 3 broker nodes.
- A Kafka topic for testing purposes (optional).
- All necessary resources are defined within the configuration, and no external dependencies are assumed.

The configuration uses default values for variables where applicable and is compatible with Terraform 1.9.8 and `hashicorp/aws` version 5.75.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_public" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "subnet_cidr_private" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "security_group_name" {
  description = "Name of the security group for MSK"
  default     = "msk-security-group"
}

variable "iam_role_name" {
  description = "Name of the IAM role for MSK"
  default     = "msk-iam-role"
}

variable "kafka_topic_name" {
  description = "Name of the Kafka topic to create"
  default     = "test-topic"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = var.subnet_cidr_public
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = var.subnet_cidr_private
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "msk_sg" {
  name        = var.security_group_name
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_iam_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_iam_role_policy" {
  role       = aws_iam_role.msk_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMQReadOnlyAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name         = "msk-cluster"
  kafka_version        = "3.6.1"
  number_of_broker_nodes = 3
  broker_node_group_info {
    instance_type         = "m5.large"
    client_subnets        = [aws_subnet.private_subnet.id]
    security_group_ids    = [aws_security_group.msk_sg.id]
    storage_type          = "EBS"
    ebs_volume_size       = 100
  }
  encryption_info {
    encryption_in_transit {
      in_cluster = true
    }
  }
  logging_info {
    cloudwatch {
      enabled = true
    }
  }
  iam_arns = [aws_iam_role.msk_iam_role.arn]
}

resource "aws_msk_cluster_policy" "msk_cluster_policy" {
  cluster_arn = aws_msk_cluster.msk_cluster.arn
  policy      = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [{
      "Effect" : "Allow",
      "Principal" : { "Service" : "kafka.amazonaws.com" },
      "Action" : "kafka:DescribeCluster",
      "Resource" : "*"
    }]
  })
}

resource "aws_msk_topic" "msk_topic" {
  cluster_arn = aws_msk_cluster.msk_cluster.arn
  name        = var.kafka_topic_name
  number_of_partitions = 1
  replication_factor = 1
}
```

