**Description:**

This Terraform configuration creates a managed Amazon MSK (Amazon Managed Streaming for Apache Kafka) cluster with 3 broker nodes in the `us-east-1` region. The cluster will be configured with default settings, including a Kafka version, number of brokers, and basic IAM roles for access. The configuration includes a provider block for AWS, a managed MSK cluster resource, and necessary IAM roles for the cluster to function properly.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the MSK cluster"
  default     = "terraform-msk-cluster"
}

variable "number_of_brokers" {
  description = "Number of broker nodes in the cluster"
  default     = 3
}

variable "kafka_version" {
  description = "Kafka version for the cluster"
  default     = "3.6.1"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the MSK cluster"
  default     = "msk-cluster-role"
}

resource "aws_iam_role" "msk_cluster_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cluster_policy" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.number_of_brokers

  broker_node_group_info {
    instance_type         = "m5.large"
    client_subnets        = ["subnet-12345678"]  # Replace with actual subnet IDs
    security_groups       = ["sg-12345678"]      # Replace with actual security group IDs
    storage_type          = "EBS"
    ebs_volume_size       = 100
    ebs_volume_encrypted  = true
  }

  iam_arns = [aws_iam_role.msk_cluster_role.arn]
}
```

**Note:**  
- Replace `subnet-12345678` and `sg-12345678` with actual subnet and security group IDs from your VPC.
- This configuration assumes that the necessary VPC, subnets, and security groups are already created and available in the `us-east-1` region.

