LLM Output #0:
**Description:**

This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The cluster is configured to log to an Amazon S3 bucket. The following components are included:

- An S3 bucket for MSK logging.
- A managed MSK cluster with a specified number of broker nodes.
- IAM roles and policies to allow MSK to write logs to the S3 bucket.
- A VPC and subnet configuration to support the MSK cluster.
- Security group to allow necessary traffic for MSK.

Variables are provided with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket for MSK logs"
  default     = "msk-logs-bucket"
}

variable "vpc_id" {
  description = "ID of the VPC to use for the MSK cluster"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the MSK cluster"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "broker_node_group_info_count" {
  description = "Number of broker nodes in the MSK cluster"
  default     = 3
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster"
}

variable "iam_role_name" {
  description = "Name of the IAM role for MSK to access S3"
  default     = "msk-s3-logging-role"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "msk_s3_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "msk.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "msk_s3_policy" {
  name = "${var.iam_role_name}-policy"
  role = aws_iam_role.msk_s3_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:PutObject",
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        "${aws_s3_bucket.msk_logs_bucket.arn}/*",
        "${aws_s3_bucket.msk_logs_bucket.arn}"
      ]
    }]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name         = var.msk_cluster_name
  kafka_version        = "3.6.1"
  number_of_broker_nodes = var.broker_node_group_info_count
  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
  encryption_info {
    in_transit {
      client_broker {
        encryption_type = "TLS"
      }
    }
  }
  logging_info {
    cloud_watch {
      enabled = false
    }
    firehose {
      enabled = false
    }
    s3 {
      enabled = true
      bucket_arn = aws_s3_bucket.msk_logs_bucket.arn
      prefix     = "logs"
    }
  }
  broker_node_group_info {
    instance_type = "m5.large"
    subnet_ids    = var.subnet_ids
    security_group_ids = [aws_security_group.msk_sg.id]
  }
  kafka_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
}

resource "aws_security_group" "msk_sg" {
  name        = "msk-security-group"
  description = "Security group for MSK cluster"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

