**Description:**

This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The cluster is configured to log its audit and application logs to a Kinesis Data Firehose delivery stream. The configuration includes:

- A Kinesis Data Firehose delivery stream.
- An IAM role for the MSK cluster to write logs to the Firehose stream.
- A managed MSK cluster with appropriate configurations.
- All necessary IAM roles and policies for the cluster and Firehose to function.

Variables are provided with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream."
  default     = "mks-logs-firehose"
}

variable "mks_cluster_name" {
  description = "Name of the MSK cluster."
  default     = "mks-cluster"
}

variable "mks_cluster_version" {
  description = "Version of the MSK cluster."
  default     = "6.2.1"
}

variable "mks_number_of_broker_nodes" {
  description = "Number of broker nodes in the MSK cluster."
  default     = "3"
}

variable "mks_broker_node_group_info_instance_type" {
  description = "Instance type for the broker nodes."
  default     = "t3.large"
}

variable "mks_encryption_in_transit_enabled" {
  description = "Whether encryption in transit is enabled."
  default     = true
}

variable "mks_enforce_ssl" {
  description = "Whether SSL is enforced for the cluster."
  default     = true
}

variable "mks_log_group_name" {
  description = "Name of the CloudWatch log group for MSK logs."
  default     = "/aws/mks/logs"
}

variable "mks_log_retention_in_days" {
  description = "Retention period for MSK logs in days."
  default     = 7
}

variable "mks_firehose_role_name" {
  description = "Name of the IAM role for MSK to write logs to Firehose."
  default     = "mks-firehose-logs-role"
}

variable "mks_firehose_role_policy_name" {
  description = "Name of the IAM policy for the Firehose role."
  default     = "mks-firehose-logs-policy"
}

resource "aws_kinesis_firehose_delivery_stream" "mks_logs" {
  name           = var.firehose_delivery_stream_name
  destination    = "firehose"
  delivery_stream_type = "direct_put"

  firehose_configuration {
    role_arn = aws_iam_role.mks_firehose_role.arn
  }
}

resource "aws_iam_role" "mks_firehose_role" {
  name = var.mks_firehose_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "mks_firehose_role_policy" {
  name = var.mks_firehose_role_policy_name
  role = aws_iam_role.mks_firehose_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "firehose:PutRecord",
        "firehose:PutRecordBatch"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_msk_cluster" "mks_cluster" {
  cluster_name                   = var.mks_cluster_name
  kafka_version                 = var.mks_cluster_version
  number_of_broker_nodes        = var.mks_number_of_broker_nodes
  broker_node_group_info {
    instance_type = var.mks_broker_node_group_info_instance_type
    client_subnets = ["subnet-12345678", "subnet-87654321"] # Replace with actual subnets
    security_groups = ["sg-12345678"] # Replace with actual security group
  }
  encryption_info {
    in_transit {
      encryption_type = "TLS"
    }
  }
  enforce_ssl = var.mks_enforce_ssl
  logging_info {
    cloudwatch {
      log_group_name = var.mks_log_group_name
      log_retention_in_days = var.mks_log_retention_in_days
    }
    firehose {
      delivery_stream = aws_kinesis_firehose_delivery_stream.mks_logs.name
    }
  }
}
