LLM Output #0:
**Description:**

This Terraform configuration creates a managed Amazon MSK (Amazon Managed Streaming for Apache Kafka) cluster with encryption at rest enabled. The cluster will be configured with a specific number of broker nodes, and the data stored on disk will be encrypted using AWS Key Management Service (KMS). The configuration includes the necessary IAM roles and policies to allow the MSK cluster to access the KMS key and other AWS services.

The cluster will be deployed in a specified AWS region, and the KMS key will be created if it does not already exist. The configuration includes default values for variables such as the number of brokers, cluster name, and KMS key ARN, which can be overridden if needed.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster-encrypted"
}

variable "number_of_brokers" {
  description = "Number of brokers in the MSK cluster"
  default     = 3
}

variable "kms_key_arn" {
  description = "ARN of the KMS key to use for encryption at rest"
  default     = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
}

variable "vpc_id" {
  description = "ID of the VPC to deploy the MSK cluster in"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the MSK cluster"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "ID of the security group for the MSK cluster"
  default     = "sg-12345678"
}

resource "aws_kms_key" "msk_encryption_key" {
  description = "KMS key for encryption at rest in MSK cluster"
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_service_role_policy" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKafkaFullAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  number_of_broker_nodes = var.number_of_brokers
  kafka_version          = "3.6.1"
  encryption_info {
    encryption_at_rest {
      kmk_arn = var.kms_key_arn
    }
  }
  client_authentication {
    sasl {
      scram {
        username = "admin"
        password = "securepassword"
      }
    }
  }
  broker_node_group_info {
    instance_type         = "m5.large"
    client_subnets        = var.subnet_ids
    security_group_id     = var.security_group_id
    vpc_id                = var.vpc_id
    ebs_volume_size       = 100
    storage_type          = "gp2"
  }
}
```

---

**Note:**  
- Replace the default values for `kms_key_arn`, `vpc_id`, `subnet_ids`, and `security_group_id` with your actual AWS resources.
- The `aws_kms_key` resource is created by default, but if you already have a KMS key, you can remove it and use the existing one.
- The `aws_iam_role` and `aws_iam_role_policy_attachment` are used to grant the MSK service the necessary permissions to access the KMS key and other AWS services.

