LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates a managed Amazon MSK (Amazon Managed Streaming for Apache Kafka) cluster with both `jmx_exporter` and `node_exporter` enabled. The configuration includes:

- A VPC with a public and private subnet.
- A security group allowing access to the MSK cluster.
- An IAM role for the MSK cluster to access AWS services.
- A managed MSK cluster with the specified exporters enabled.
- Default values for variables to ensure the configuration is deployable without additional input.

The configuration uses the `hashicorp/aws` provider and is compatible with Terraform 1.9.8 and above.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_public" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "subnet_cidr_private" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "security_group_name" {
  description = "Name of the security group for the MSK cluster"
  default     = "msk-cluster-sg"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the MSK cluster"
  default     = "msk-cluster-role"
}

variable "cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes in the cluster"
  default     = "3"
}

variable "broker_node_group_info" {
  description = "Broker node group information"
  default = {
    instance_type         = "m5.large"
    client_subnets        = ["subnet-12345678"]
    ebs_volume_size       = 100
    storage_type          = "gp2"
    security_group_ids    = ["sg-12345678"]
    auto_scaling_enabled  = false
  }
}

variable "jmx_exporter_enabled" {
  description = "Enable JMX Exporter for the MSK cluster"
  default     = true
}

variable "node_exporter_enabled" {
  description = "Enable Node Exporter for the MSK cluster"
  default     = true
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_public
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_private
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "msk_sg" {
  name        = var.security_group_name
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_role_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name              = var.cluster_name
  kafka_version             = "3.6.1"
  number_of_broker_nodes    = var.number_of_broker_nodes
  broker_node_group_info {
    instance_type         = var.broker_node_group_info.instance_type
    client_subnets        = [aws_subnet.private.id]
    ebs_volume_size       = var.broker_node_group_info.ebs_volume_size
    storage_type          = var.broker_node_group_info.storage_type
    security_group_ids    = [aws_security_group.msk_sg.id]
    auto_scaling_enabled  = var.broker_node_group_info.auto_scaling_enabled
  }
  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
  encryption_info {
    in_transit {
      client_broker {
        encryption_type = "TLS"
      }
    }
  }
  logging_info {
    cloud_watch {
      enabled = true
    }
  }
  kafka_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
  jmx_exporter {
    enabled = var.jmx_exporter_enabled
  }
  node_exporter {
    enabled = var.node_exporter_enabled
  }
}
```

