This Terraform configuration creates a serverless Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region. The cluster is configured with default settings suitable for a serverless deployment, including the creation of necessary IAM roles and policies to ensure secure and functional operation. The configuration includes a single Kafka broker, a default number of client authentication policies, and a default number of client authentication policies for producers and consumers. The cluster is set up to be serverless, meaning it automatically scales based on workload and does not require manual management of broker instances.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the MSK cluster"
  default     = "serverless-msk-cluster"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes in the cluster"
  default     = 1
}

variable "client_authentication_iam_arn" {
  description = "ARN of the IAM role for client authentication"
  default     = "arn:aws:iam::123456789012:role/msk-client-role"
}

variable "client_authentication_producer_iam_arn" {
  description = "ARN of the IAM role for producer authentication"
  default     = "arn:aws:iam::123456789012:role/msk-producer-role"
}

variable "client_authentication_consumer_iam_arn" {
  description = "ARN of the IAM role for consumer authentication"
  default     = "arn:aws:iam::123456789012:role/msk-consumer-role"
}

resource "aws_msk_serverless_cluster" "serverless_cluster" {
  cluster_name                   = var.cluster_name
  number_of_broker_nodes         = var.number_of_broker_nodes
  client_authentication_iam_arn  = var.client_authentication_iam_arn
  client_authentication_producer_iam_arn = var.client_authentication_producer_iam_arn
  client_authentication_consumer_iam_arn = var.client_authentication_consumer_iam_arn
}
```

---

**Note:**  
- The IAM roles referenced in the `client_authentication_*_iam_arn` variables must already exist in your AWS account and be properly configured with the necessary permissions for MSK access.
- This configuration assumes that the IAM roles are already created and managed separately. If you need Terraform to create and manage these roles as well, additional resources and policies would be required.

