**Description:**

This Terraform configuration creates a fully serverless AWS MSK (Amazon Managed Streaming for Apache Kafka) cluster with 3 broker nodes. It includes the necessary AWS resources such as the MSK cluster, IAM roles, and VPC configuration. The cluster is set up to be serverless, meaning it automatically scales and manages the underlying infrastructure. The configuration uses default values for variables where applicable and ensures all required resources are declared and properly referenced.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the MSK cluster."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs to use for the MSK cluster."
  default     = ["subnet-12345678", "subnet-87654321", "subnet-11122233"]
}

variable "security_group_id" {
  description = "The ID of the security group to use for the MSK cluster."
  default     = "sg-12345678"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster."
  default     = "serverless-msk-cluster"
}

variable "number_of_broker_nodes" {
  description = "Number of broker nodes in the MSK cluster."
  default     = 3
}

variable "kafka_version" {
  description = "Kafka version to use for the MSK cluster."
  default     = "3.6.1"
}

resource "aws_msk_serverless_cluster" "serverless_msk_cluster" {
  cluster_name         = var.msk_cluster_name
  kafka_version        = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  client_authentication {
    iam {
      enabled = true
    }
  }

  network_configuration {
    vpc_id              = var.vpc_id
    subnet_ids          = var.subnet_ids
    security_group_ids  = [var.security_group_id]
  }
}
```

---

**Note:** This configuration assumes that the VPC, subnets, and security group already exist. If you need to create them as part of the Terraform configuration, additional resources like `aws_vpc`, `aws_subnet`, and `aws_security_group` should be added. This version is compatible with Terraform 1.9.8 and `hashicorp/aws` version 5.75.

