LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates a serverless Amazon MSK (Managed Streaming for Apache Kafka) cluster with 3 broker nodes in the `us-east-1` region. The cluster is configured to be serverless, which means it automatically scales based on the workload and does not require manual management of broker nodes. The configuration includes the necessary AWS provider setup, IAM roles, and resource definitions to deploy the MSK cluster.

The configuration includes:
- A provider block for AWS in the `us-east-1` region.
- An IAM role for the MSK cluster to allow necessary permissions.
- A serverless MSK cluster with 3 broker nodes.
- Default variables for cluster name, Kafka version, and IAM role name.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the MSK cluster"
  default     = "serverless-msk-cluster"
}

variable "kafka_version" {
  description = "Kafka version for the cluster"
  default     = "3.6.1"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the MSK cluster"
  default     = "msk-cluster-role"
}

resource "aws_iam_role" "msk_cluster_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "kafka.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cluster_policy" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
}

resource "aws_msk_serverless_cluster" "msk_cluster" {
  cluster_name         = var.cluster_name
  kafka_version        = var.kafka_version
  number_of_broker_nodes = 3
  client_authentication {
    unauthenticated {
      enabled = false
    }
  }
  encryption_info {
    encryption_in_transit {
      in_cluster = true
    }
  }
  iam_arn = aws_iam_role.msk_cluster_role.arn
}
```

