LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates a fully integrated AWS MSK (Managed Streaming for Apache Kafka) cluster with the following components:

- **MSK Cluster**: A 3-broker cluster with encryption at rest enabled.
- **CloudWatch Log Group**: A log group to collect logs from the MSK cluster.
- **S3 Bucket**: A storage bucket for data archival or processing.
- **Kinesis Firehose Delivery Stream**: A delivery stream that sends data to the S3 bucket.
- **IAM Roles**: Necessary IAM roles are created to allow MSK to access CloudWatch logs and Kinesis Firehose.

All resources are configured with default values where applicable, and the configuration is ready to be deployed using Terraform 1.9.8 or later with the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "Name of the MSK cluster"
  default     = "msk-cluster"
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch log group"
  default     = "msk-logs"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket"
  default     = "msk-s3-bucket"
}

variable "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream"
  default     = "msk-firehose-stream"
}

variable "vpc_id" {
  description = "ID of the VPC where the MSK cluster will be deployed"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the MSK cluster"
  default     = ["subnet-12345678", "subnet-87654321", "subnet-11122233"]
}

variable "security_group_id" {
  description = "ID of the security group for the MSK cluster"
  default     = "sg-12345678"
}

variable "iam_role_name" {
  description = "Name of the IAM role for MSK"
  default     = "msk-iam-role"
}

variable "iam_role_policy_name" {
  description = "Name of the IAM role policy for MSK"
  default     = "msk-iam-role-policy"
}

resource "aws_iam_role" "msk_role" {
  name = var.iam_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kafka.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "msk_role_policy" {
  name = var.iam_role_policy_name
  role = aws_iam_role.msk_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogGroups",
        "logs:DescribeLogStreams"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name = var.cloudwatch_log_group_name
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name           = var.firehose_delivery_stream_name
  destination    = "s3"
  s3_configuration {
    role_arn        = aws_iam_role.msk_role.arn
    bucket_arn      = aws_s3_bucket.s3_bucket.arn
    prefix          = "msk-logs/"
    buffering_hints {
      size_in_mbs = 5
      interval_in_seconds = 60
    }
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name         = var.msk_cluster_name
  kafka_version        = "3.6.1"
  number_of_broker_nodes = 3
  encryption_info {
    encryption_at_rest {
      kafka_authentication_ssl {
        certificate_arn = "arn:aws:acm:us-east-1:123456789012:certificate/12345678-1234-1234-1234-123456789012"
      }
    }
  }
  open_monitoring {
    cloud_watch_metrics {
      dimensions = {
        "BrokerId" = "1"
        "BrokerName" = "Broker-1"
      }
    }
  }
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = var.subnet_ids
    security_groups = [var.security_group_id]
    ebs_volume_size = 100
    storage_type = "gp2"
  }
  kafka_authentication {
    sasl {
      scram {
        username = "admin"
        password = "admin-secret"
      }
    }
  }
  kafka_authorization {
    acls {
      acls = [
        {
          principal = "User:admin"
          host = "*"
          operation = "DESCRIBE"
          resource_type = "CLUSTER"
          permission = "READ"
        },
        {
          principal = "User:admin"
          host = "*"
          operation = "DESCRIBE"
          resource_type = "TOPIC"
          permission = "READ"
        }
      ]
    }
  }
}
