**Description of the Terraform Program:**

This Terraform configuration creates an Aurora PostgreSQL cluster using AWS RDS. It includes:

- A VPC with a public subnet.
- A security group allowing access to the cluster from a specific IP range.
- An Aurora PostgreSQL cluster with a master username and password.
- A database subnet group referencing the VPC subnets.
- A parameter group to configure the cluster (optional).
- An IAM role for the cluster to allow access to other AWS services (optional).

The configuration is designed to be deployable in AWS using Terraform version 1.9.8 or higher and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_1" {
  description = "CIDR block for the first subnet"
  default     = "10.0.1.0/24"
}

variable "subnet_cidr_2" {
  description = "CIDR block for the second subnet"
  default     = "10.0.2.0/24"
}

variable "security_group_ip_range" {
  description = "IP range allowed to access the cluster"
  default     = "0.0.0.0/0"
}

variable "master_username" {
  description = "Master username for the Aurora PostgreSQL cluster"
  default     = "admin"
}

variable "master_password" {
  description = "Master password for the Aurora PostgreSQL cluster"
  default     = "SecureP@ssw0rd!"
}

variable "cluster_identifier" {
  description = "Identifier for the Aurora PostgreSQL cluster"
  default     = "aurora-postgres-cluster"
}

variable "engine_version" {
  description = "Engine version for Aurora PostgreSQL"
  default     = "16.3"
}

variable "db_instance_class" {
  description = "Instance class for the Aurora PostgreSQL cluster"
  default     = "db.r5.large"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the Aurora PostgreSQL cluster"
  default     = "aurora-postgres-role"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_1
  map_public_ip_on_launch = true
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_2
  map_public_ip_on_launch = true
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
}

resource "aws_security_group" "aurora_sg" {
  name        = "aurora-postgres-sg"
  description = "Allow access to Aurora PostgreSQL cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.security_group_ip_range]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "aurora_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "aurora_role_policy" {
  role       = aws_iam_role.aurora_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

resource "aws_rds_cluster" "aurora_cluster" {
  cluster_identifier      = var.cluster_identifier
  engine                  = "postgres"
  engine_version          = var.engine_version
  database_name           = "postgres"
  master_username         = var.master_username
  master_password         = var.master_password
  db_subnet_group_name    = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.aurora_sg.id]
  iam_role_arn            = aws_iam_role.aurora_role.arn
  port                    = 5432
  skip_final_snapshot     = true
  storage_type            = "gp2"
  db_cluster_parameter_group_name = "default.postgres16"
  preferred_backup_window = "07:00-08:00"
  preferred_maintenance_window = "08:00-09:00"
  backup_retention_period = 7
}

resource "aws_rds_cluster_instance" "aurora_instance" {
