**Description of the Terraform Program:**

This Terraform configuration creates an MySQL cluster with 100 GB of allocated storage in each availability zone. The cluster is deployed using AWS RDS (Relational Database Service), and it is configured to span multiple availability zones for high availability. The configuration includes:

- A VPC with a public subnet and a private subnet.
- A security group allowing access to the database from specific IP ranges.
- An RDS MySQL cluster with 100 GB storage per zone.
- An IAM role for the RDS instance to allow access to AWS services.
- A default variable for the database name, username, and password.

The configuration is designed to be deployable in AWS using Terraform version 1.9.8 or higher and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "database_name" {
  description = "Name of the database"
  default     = "mydb"
}

variable "username" {
  description = "Username for the database"
  default     = "admin"
}

variable "password" {
  description = "Password for the database"
  default     = "securepassword"
}

variable "allowed_ip_ranges" {
  description = "List of IP ranges allowed to access the database"
  default     = ["0.0.0.0/0"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group"
  description = "Allow access to MySQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.allowed_ip_ranges
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
