}

variable "allowed_cidr" {
  description = "The CIDR block that is allowed to connect to the MySQL instance."
  default     = "0.0.0.0/0"
}

variable "vpc_id" {
  description = "The ID of the VPC where the MySQL instance will be created."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
