LLM Output #0:
**Description:**

This Terraform configuration creates a DynamoDB table with server-side encryption enabled. The table will be configured with an AWS KMS key for encryption. A KMS key is created within the same AWS account and region as the DynamoDB table. The configuration includes a provider block with a valid AWS region, and all necessary resources are declared explicitly.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  default     = "encrypted-table"
}

variable "kms_key_alias" {
  description = "Alias for the KMS key to be used for encryption"
  default     = "alias/terraform-encryption-key"
}

resource "aws_kms_key" "dynamodb_encryption_key" {
  description = "KMS key for DynamoDB table encryption"
  provider    = aws

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${aws_caller_identity.current.account_id}:user/${aws_iam_user.terraform_user.name}" }
        Action    = [
          "kms:DescribeKey",
          "kms:GetKeyPolicy",
          "kms:ListKeys",
          "kms:PutKeyPolicy"
        ]
        Resource = "${aws_kms_key.dynamodb_encryption_key.arn}"
      }
    ]
  })
}

resource "aws_iam_user" "terraform_user" {
  name = "terraform-user"
}

resource "aws_iam_user_policy_attachment" "iam_user_policy" {
  user       = aws_iam_user.terraform_user.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonDynamoDBFullAccess"
}

resource "aws_dynamodb_table" "encrypted_table" {
  name           = var.dynamodb_table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"
  encryption     = "KMS"
  kms_key_id     = aws_kms_key.dynamodb_encryption_key.arn
  point_in_time_recovery = true

  dynamodb_table_arn = aws_dynamodb_table.encrypted_table.arn
}

resource "aws_caller_identity" "current" {}
```

---

**Note:** This configuration assumes that the AWS provider is properly configured with credentials. You may need to set `AWS_ACCESS_KEY_ID`, `AWS_SECRET_ACCESS_KEY`, and `AWS_SESSION_TOKEN` in your environment or use a Terraform backend with appropriate credentials.

