**Description of the Terraform Program:**

This Terraform configuration creates an AWS VPC with a single public subnet and associated network ACLs (NACLs) to control both ingress and egress traffic. The VPC is configured with a CIDR block, and the subnet is created within the VPC. Network ACLs are defined to allow specific traffic rules for both incoming and outgoing traffic. The configuration uses the `aws_vpc`, `aws_subnet`, and `aws_network_acl` resources. A default region (`us-east-1`) is specified, and all resources are created in that region. The configuration is self-contained and does not require external variables or resources.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "The CIDR block for the subnet."
  default     = "10.0.1.0/24"
}

variable "network_acl_ingress_rules" {
  description = "List of ingress rules for the network ACL. Each rule is a map with 'from_port', 'to_port', 'protocol', and 'rule_action'."
  default     = [
    {
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      rule_action = "allow"
    },
    {
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      rule_action = "allow"
    },
    {
      from_port   = 0
      to_port     = 65535
      protocol    = "icmp"
      rule_action = "allow"
    }
  ]
}

variable "network_acl_egress_rules" {
  description = "List of egress rules for the network ACL. Each rule is a map with 'from_port', 'to_port', 'protocol', and 'rule_action'."
  default     = [
    {
      from_port   = 0
      to_port     = 65535
      protocol    = "-1"
      rule_action = "allow"
    }
  ]
}

resource "aws_vpc" "example_vpc" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "example_subnet" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = var.subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
}

resource "aws_network_acl" "example_nacl" {
  vpc_id = aws_vpc.example_vpc.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    rule_action = "deny"
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    rule_action = "deny"
  }

  dynamic "ingress" {
    for_each = var.network_acl_ingress_rules
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      rule_action = ingress.value.rule_action
    }
  }

  dynamic "egress" {
    for_each = var.network_acl_egress_rules
    content {
      from_port   = egress.value.from_port
      to_port     = egress.value.to_port
      protocol    = egress.value.protocol
      rule_action = egress.value.rule_action
    }
  }
}
