**Description of the Terraform Program:**

This Terraform configuration creates an AWS VPC with a single public subnet and launches an EC2 instance using an Ubuntu 20.04 AMI. The VPC is configured with a CIDR block, and the subnet is set to be public. The EC2 instance is launched into the subnet with a security group that allows SSH access. The AMI is looked up using the `aws_ami` data source to ensure it's the latest Ubuntu 20.04 AMI. The configuration uses the `us-east-1` region and includes necessary IAM roles and security groups for the EC2 instance.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

# Data source to find the latest Ubuntu 20.04 AMI
data "aws_ami" "ubuntu_20_04" {
  most_recent = true
  owners      = ["099720109477"] # Canonical's AWS account ID

  filter {
    name   = "name"
    values = ["ubuntu-20.04*"]
  }
}

# Create a VPC
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "example-vpc"
  }
}

# Create a public subnet
resource "aws_subnet" "example_subnet" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
  tags = {
    Name = "example-subnet"
  }
}

# Create a security group for the EC2 instance
resource "aws_security_group" "example_sg" {
  name        = "example-sg"
  description = "Allow SSH access"
  vpc_id      = aws_vpc.example_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-sg"
  }
}

# Launch an EC2 instance
resource "aws_instance" "example_instance" {
  ami           = data.aws_ami.ubuntu_20_04.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.example_subnet.id
  security_groups = [aws_security_group.example_sg.name]

  tags = {
    Name = "example-instance"
  }
}
```

