**Description of the Terraform Program:**

This Terraform configuration creates an AWS Chime Voice Connector with encryption enabled. It then configures the voice connector to stream audio with a retention period of 5 hours. It also sets up an SNS topic to receive notifications about the streaming activity and disables streaming to Amazon Kinesis. The configuration includes all necessary AWS resources such as the Chime Voice Connector, SNS topic, and IAM roles for proper permissions.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "chime_voice_connector_name" {
  description = "Name for the Chime Voice Connector"
  default     = "MyVoiceConnector"
}

variable "sns_topic_name" {
  description = "Name for the SNS topic"
  default     = "VoiceConnectorNotifications"
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic for notifications"
  default     = "arn:aws:sns:us-east-1:123456789012:VoiceConnectorNotifications"
}

variable "kms_key_arn" {
  description = "ARN of the KMS key for encryption"
  default     = "arn:aws:kms:us-east-1:123456789012:key/1234abcd-12ab-34cd-56ef-1234567890ab"
}

resource "aws_chime_voice_connector" "voice_connector" {
  name = var.chime_voice_connector_name
  encryption {
    require_encryption = true
    encryption_protocol = "SRTP"
  }
}

resource "aws_chime_voice_connector_streaming" "voice_connector_streaming" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id
  media_streaming_configuration {
    media_streaming_type = "VOICE"
    retention_hours      = 5
    streaming_status     = "ENABLED"
    kinesis_firehose_configuration {
      enabled = false
    }
    sns_topic_arn = var.sns_topic_arn
  }
}

resource "aws_sns_topic" "sns_topic" {
  name = var.sns_topic_name
}

resource "aws_iam_role" "sns_role" {
  name = "sns_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "sns.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "sns_policy" {
  name = "sns_policy"
  role = aws_iam_role.sns_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "sns:Publish",
        "sns:GetTopicAttributes",
        "sns:SetTopicAttributes"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_iam_role" "kms_role" {
  name = "kms_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "kms.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "kms_policy" {
  name = "kms_policy"
  role = aws_iam_role.kms_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "kms:DescribeKey",
        "kms:GetKeyPolicy",
        "kms:ListKeys"
      ]
      Resource = "*"
    }]
  })
}
```

