**Description of the Terraform Program:**

This Terraform configuration creates an AWS Chime Voice Connector (VCC) and sets up a media streaming configuration to send media to an Amazon Kinesis stream. The VCC is configured with a media streaming configuration that points to a Kinesis data stream. The Kinesis stream is created with a default name and shard count. The configuration includes IAM roles and policies to allow the VCC to stream media to Kinesis.

**Terraform HCL Program:**

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "kinesis_stream_name" {
  description = "Name of the Kinesis stream to stream media to."
  default     = "chime-media-stream"
}

variable "kinesis_shard_count" {
  description = "Number of shards for the Kinesis stream."
  default     = "1"
}

resource "aws_kinesis_stream" "chime_media_stream" {
  name        = var.kinesis_stream_name
  shard_count = var.kinesis_shard_count
}

resource "aws_iam_role" "chime_vcc_role" {
  name = "chime_vcc_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "chime.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "chime_vcc_kinesis_policy" {
  name = "chime_vcc_kinesis_policy"
  role = aws_iam_role.chime_vcc_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "kinesis:PutRecord",
        "kinesis:PutRecords"
      ]
      Resource = "arn:aws:kinesis:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:stream/${var.kinesis_stream_name}"
    }]
  })
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_chime_voice_connector" "chime_vcc" {
  name = "chime-voice-connector"

  media_streaming_configuration {
    media_streaming_type = "Kinesis"
    kinesis_media_configuration {
      kinesis_stream_arn = aws_kinesis_stream.chime_media_stream.arn
    }
  }

  voice_connector_termination {
    calling_name = "Chime Voice Connector"
    outgoing_caller_id_name = "Chime Voice Connector"
    outgoing_caller_id_number = "1234567890"
  }

  tags = {
    Environment = "production"
    Purpose    = "Voice Streaming"
  }
}
```

**Notes:**

- The Kinesis stream is created with a default name and shard count. You can customize these via variables.
- The IAM role is created to allow the Chime Voice Connector to stream media to the Kinesis stream.
- The Chime Voice Connector is configured with a media streaming type of `Kinesis` and points to the Kinesis stream ARN.
- The `data` blocks are used to fetch the current AWS region and account ID for dynamic resource ARN construction.
- This configuration is compatible with Terraform 1.9.8 and `hashicorp/aws` version 5.75.

