**Description of the Terraform Program:**

This Terraform configuration creates an AWS Redshift cluster with endpoint access from two specified subnets. The cluster is configured with a single-node setup for simplicity, and the necessary IAM roles and security groups are defined to allow access from the specified subnets. The configuration includes a default VPC, subnets, security group, and Redshift cluster resource. All required variables are defined with default values for easy deployment.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the Redshift cluster."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the Redshift cluster."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to allow access to the Redshift cluster."
  default     = "sg-12345678"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster."
  default     = "my-redshift-cluster"
}

variable "master_username" {
  description = "The master username for the Redshift cluster."
  default     = "admin"
}

variable "master_password" {
  description = "The master password for the Redshift cluster."
  default     = "SecureP@ssw0rd!"
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster access"
  vpc_id      = var.vpc_id

  ingress {
    description = "Allow access from subnets"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [var.subnet_ids]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier         = var.cluster_identifier
  node_type                  = "dc2.large"
  master_username            = var.master_username
  master_password            = var.master_password
  cluster_type               = "single-node"
  automated_snapshot_retention_period = 7
  iam_roles                  = ["arn:aws:iam::123456789012:role/RedshiftRole"]
  skip_final_snapshot        = true
  port                       = 5439
  cluster_subnet_group_name  = aws_redshift_cluster_subnet_group.redshift_subnet_group.name
  vpc_security_group_ids     = [aws_security_group.redshift_sg.id]
}

resource "aws_redshift_cluster_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = var.subnet_ids
}
```

---

**Note:**  
- Replace the default values for `vpc_id`, `subnet_ids`, `security_group_id`, and other variables with your actual AWS resources.
- Ensure that the IAM role `RedshiftRole` exists in your AWS account and has the necessary permissions for Redshift.
- This configuration assumes that the subnets are in the same VPC and are properly configured for Redshift.

