This Terraform configuration creates an AWS Redshift cluster with event notifications enabled. The cluster will be configured with a basic setup, including a master username and password, and will be associated with an IAM role that allows it to interact with other AWS services. Event notifications will be set up to send alerts to an SNS topic, which can be used for monitoring and alerting purposes. The configuration includes a default provider block for AWS in the `us-east-1` region and defines necessary variables with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "redshift_cluster_name" {
  description = "Name of the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "redshift_master_username" {
  description = "Master username for the Redshift cluster"
  default     = "admin"
}

variable "redshift_master_password" {
  description = "Master password for the Redshift cluster"
  default     = "SecureP@ssw0rd!"
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic to receive event notifications"
  default     = "arn:aws:sns:us-east-1:123456789012:my-sns-topic"
}

variable "iam_role_name" {
  description = "Name of the IAM role to be created for Redshift"
  default     = "RedshiftServiceRole"
}

resource "aws_iam_role" "redshift_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_role_policy" {
