**Description of the Terraform Program:**

This Terraform configuration creates an AWS Redshift cluster with example cluster parameters and sets up an SNS topic to receive notifications for events associated with a parameter group. The cluster is configured with a default parameter group, and event notifications are set up to trigger alerts via SNS. The configuration includes:

- An AWS SNS topic for notifications.
- A Redshift parameter group with example settings.
- A Redshift cluster using the parameter group.
- Event notifications configured to send messages to the SNS topic.

All resources are created in the `us-east-1` region, and IAM roles are created as needed for the Redshift cluster to interact with SNS.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the Redshift cluster"
  default     = "example-redshift-cluster"
}

variable "cluster_version" {
  description = "Redshift cluster version"
  default     = "latest"
}

variable "cluster_type" {
  description = "Type of Redshift cluster (e.g., single-node, multi-node)"
  default     = "single-node"
}

variable "node_type" {
  description = "Type of node for the cluster (e.g., dc2.large)"
  default     = "dc2.large"
}

variable "number_of_nodes" {
  description = "Number of nodes in the cluster (only applicable for multi-node clusters)"
  default     = 1
}

variable "sns_topic_name" {
  description = "Name of the SNS topic for notifications"
  default     = "redshift-event-notifications"
}

variable "parameter_group_name" {
  description = "Name of the Redshift parameter group"
  default     = "example-redshift-parameter-group"
}

resource "aws_sns_topic" "redshift_event_notifications" {
  name = var.sns_topic_name
}

resource "aws_redshift_parameter_group" "example" {
  name        = var.parameter_group_name
  family      = "redshift-4.0"
  description = "Example Redshift parameter group for event notifications"

  parameter {
    name         = "enable_user_activity_logging"
    value        = "true"
    description  = "Enable user activity logging"
    apply_type   = "cluster"
    data_type    = "boolean"
  }

  parameter {
    name         = "query_group"
    value        = "example-group"
    description  = "Query group for the cluster"
    apply_type   = "cluster"
    data_type    = "string"
  }
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier           = var.cluster_name
  cluster_type                 = var.cluster_type
  node_type                    = var.node_type
  number_of_nodes              = var.number_of_nodes
  database_name                = "example_db"
  master_username              = "admin"
  master_password              = "SecureP@ssw0rd!"
  port                         = 5439
  cluster_version              = var.cluster_version
  skip_final_snapshot          = true
  iam_roles                    = ["arn:aws:iam::123456789012:role/RedshiftSNSRole"]
  parameter_group_name         = aws_redshift_parameter_group.example.name
  allow_version_upgrade       = true
  automated_snapshot_retention_period = 7
  iam_role_arns                = ["arn:aws:iam::123456789012:role/RedshiftSNSRole"]
}

resource "aws_redshift_event_subscription" "example" {
  name          = "example-redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_event_notifications.arn
  source_type   = "cluster"
  event_categories = ["cluster-availability", "cluster-snapshot", "cluster-configuration"]
  severity      = "ERROR"

  depends_on = [aws_redshift_cluster.example]
}
```

---

**Note:**  
- Replace `arn:aws:iam::123456789012:role/RedshiftSNSRole` with the actual ARN of an IAM role that allows Redshift to publish to the SNS topic.
- Ensure that the IAM role has the necessary permissions to publish to the SNS topic.
- This configuration assumes that the SNS topic is already created or will be created by the Terraform configuration.

