**Description of the Terraform Program:**

This Terraform configuration creates an AWS S3 bucket to store images for a website. The S3 bucket is configured with basic settings such as a name, region, and access control. It also enables static website hosting so that the images can be publicly accessible via a URL. An IAM role is created to allow the S3 bucket to be accessed by the website, and the bucket policy is set to grant public read access to the images.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store images."
  default     = "my-website-images"
}

variable "website_endpoint" {
  description = "The endpoint for the website (e.g., example.com)."
  default     = "example.com"
}

resource "aws_s3_bucket" "images_bucket" {
  bucket = var.bucket_name
  region = "us-east-1"

  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_policy" "images_policy" {
  bucket = aws_s3_bucket.images_bucket.id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "s3:GetObject"
        ]
        Resource = "${aws_s3_bucket.images_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role" "website_role" {
  name = "website-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "website_role_policy" {
  name = "website-access-policy"
  role = aws_iam_role.website_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = "${aws_s3_bucket.images_bucket.arn}/*"
      }
    ]
  })
}
```

