**Description of the Terraform Program:**

This Terraform configuration creates two AWS S3 buckets: one to store the main data (bucket1) and another to store the weekly CSV inventory reports (bucket2). It also sets up an IAM role and policy to allow the AWS Lambda function to access both buckets. A Lambda function is created to generate a CSV inventory report of all object versions in bucket1 and upload it to bucket2. The Lambda function is scheduled to run weekly using AWS CloudWatch Events.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "bucket1_name" {
  description = "Name of the main S3 bucket"
  default     = "main-bucket"
}

variable "bucket2_name" {
  description = "Name of the S3 bucket for inventory reports"
  default     = "inventory-bucket"
}

variable "lambda_name" {
  description = "Name of the Lambda function"
  default     = "s3-inventory-lambda"
}

variable "lambda_role_name" {
  description = "Name of the IAM role for the Lambda function"
  default     = "s3-inventory-lambda-role"
}

resource "aws_s3_bucket" "bucket1" {
  bucket = var.bucket1_name
  acl    = "private"
}

resource "aws_s3_bucket" "bucket2" {
  bucket = var.bucket2_name
  acl    = "private"
}

resource "aws_iam_role" "lambda_role" {
  name = var.lambda_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  name = "${var.lambda_role_name}-policy"
  role = aws_iam_role.lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:ListBucket",
        "s3:GetBucketVersioning",
        "s3:GetObjectVersion",
        "s3:PutObject"
      ]
      Resource = [
        "${aws_s3_bucket.bucket1.arn}",
        "${aws_s3_bucket.bucket2.arn}"
      ]
    }]
  })
}

resource "aws_lambda_function" "inventory_lambda" {
  function_name    = var.lambda_name
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda.zip"
  source_code_hash = "base64:example-hash"
  timeout          = 30

  environment {
    variables = {
      BUCKET1_NAME = var.bucket1_name
      BUCKET2_NAME = var.bucket2_name
    }
  }
}

resource "aws_cloudwatch_event_rule" "weekly_schedule" {
  schedule_expression = "cron(0 12 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.weekly_schedule.name
  target_arn = aws_lambda_function.inventory_lambda.arn
}

resource "aws_cloudwatch_event_rule" "daily_schedule" {
  schedule_expression = "rate(1 day)"
}

resource "aws_cloudwatch_event_target" "lambda_target_daily" {
  rule      = aws_cloudwatch_event_rule.daily_schedule.name
  target_arn = aws_lambda_function.inventory_lambda.arn
}
```

> **Note:** The `filename` and `source_code_hash` fields are placeholders. In a real deployment, you would need to package your Lambda function code into a ZIP file and compute the hash. You can use `terraform apply` with the `-target` flag to apply the Lambda function and its dependencies in the correct order.

