This Terraform configuration creates an AWS S3 bucket and applies KMS server-side encryption using a defined KMS key. The KMS key is created as a separate resource, and the S3 bucket is configured to use it for encryption. The configuration includes:

- A KMS key resource with a default name.
- An S3 bucket resource that uses the KMS key for server-side encryption.
- A provider block configured for AWS in the `us-east-1` region.
- Default values for variables to ensure the configuration is self-contained and deployable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket."
  default     = "my-encrypted-bucket"
}

variable "kms_key_name" {
  description = "The name of the KMS key to use for encryption."
  default     = "my-encryption-key"
}

resource "aws_kms_key" "encryption_key" {
  description = var.kms_key_name
  policy      = jsonencode({
    Version   = "2012-10-17"
    Statement = [{
      Sid       = "Enable IAM User Permissions"
      Effect    = "Allow"
      Principal = { AWS = "arn:aws:iam::${aws_caller_identity.current.account_id}:user/*" }
      Action     = [
        "kms:GenerateDataKey",
        "kms:Decrypt",
        "kms:Encrypt",
        "kms:DescribeKey"
      ]
      Resource = "*"
    }]
