**Description of the Terraform Program:**

This Terraform configuration sets up an isolated AWS environment to run an autograder for a CS class. The infrastructure includes:

- A **private VPC** with a **private subnet** to ensure the autograder environment is isolated from the internet.
- A **CodeBuild project** that runs the autograder, which pulls code from a GitHub repository.
- A **CodeBuild role** with necessary permissions to access GitHub and run builds.
- A **security group** that restricts outbound internet access to prevent student code from reaching the internet.
- A **CodeBuild service role** that allows CodeBuild to run in the VPC and access necessary AWS services.
- A **CodeBuild project** that is configured to run in the VPC and use the appropriate role.

All resources are created in a single AWS region (us-east-1), and the configuration is designed to be deployable with Terraform 1.9.8 and hashicorp/aws 5.75.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.1.0/24"
}

variable "github_owner" {
  description = "GitHub owner of the repository"
  default     = "example-owner"
}

variable "github_repo" {
  description = "GitHub repository name"
  default     = "example-repo"
}

variable "github_token" {
  description = "GitHub personal access token for CodeBuild to clone the repo"
  default     = "your-github-token"
}

variable "codebuild_role_name" {
  description = "Name of the CodeBuild service role"
  default     = "CodeBuildServiceRole"
}

variable "codebuild_project_name" {
  description = "Name of the CodeBuild project"
  default     = "AutograderCodeBuild"
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "autograder_private_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = var.private_subnet_cidr
  map_public_ip_on_launch = false
}

resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
}

resource "aws_route_table" "autograder_route_table" {
  vpc_id = aws_vpc.autograder_vpc.id
}

resource "aws_route" "autograder_route_to_internet" {
  route_table_id         = aws_route_table.autograder_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograder_igw.id
}

resource "aws_route_table_association" "autograder_route_table_association" {
  subnet_id      = aws_subnet.autograder_private_subnet.id
  route_table_id = aws_route_table.autograder_route_table.id
}

resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Security group for autograder in private subnet"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name = var.codebuild_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_service_role_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildRole"
}

resource "aws_iam_role" "codebuild_codecommit_role" {
  name = "CodeBuildCodeCommitRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
