**Description of the Terraform Program:**

This Terraform configuration sets up an isolated environment for an autograder system using AWS services. The infrastructure includes:

- A **private VPC** with a **private subnet** to ensure the autograder and CodeBuild resources cannot access the internet.
- A **CodeBuild project** that runs the autograder, which pulls code from a GitHub repository.
- An **S3 bucket** to store the results of the autograder runs.
- An **IAM role** for CodeBuild to access the S3 bucket and GitHub.
- A **CodeBuild service role** to allow CodeBuild to run in the private VPC.
- A **security group** that restricts access to only the CodeBuild service and prevents internet access.

All resources are deployed in a single AWS region (us-east-1), and the configuration is designed to be secure and isolated from the public internet.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.1.0/24"
}

variable "github_repository" {
  description = "GitHub repository URL for the autograder code"
  default     = "https://github.com/example/autograder.git"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store autograder results"
  default     = "autograder-results"
}

variable "codebuild_role_name" {
  description = "Name of the IAM role for CodeBuild"
  default     = "CodeBuildAutograderRole"
}

variable "codebuild_service_role_name" {
  description = "Name of the IAM role for CodeBuild service"
  default     = "CodeBuildServiceRole"
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "autograder_private_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = var.private_subnet_cidr
  map_public_ip_on_launch = false
}

resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
}

resource "aws_route_table" "autograder_route_table" {
  vpc_id = aws_vpc.autograder_vpc.id
}

resource "aws_route" "autograder_route_to_igw" {
  route_table_id         = aws_route_table.autograder_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograder_igw.id
}

resource "aws_route_table_association" "autograder_route_table_association" {
  subnet_id      = aws_subnet.autograder_private_subnet.id
  route_table_id = aws_route_table.autograder_route_table.id
}

resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Security group for autograder"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = var.codebuild_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_role_s3" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_iam_role" "codebuild_service_role" {
  name = var.codebuild_service_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "codebuild_service_role_policy" {
  name = "codebuild_service_role_policy"
  role = aws_iam_role.codebuild_service_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "ec2:DescribeSubnets",
        "ec2:DescribeSecurityGroups",
        "ec2:DescribeVpcs",
        "ec2:DescribeInstances",
        "ec2:DescribeVolumes",
        "ec2:DescribeTags",
        "ec2:DescribeNetworkInterfaces",
        "ec2:CreateNetworkInterface",
        "ec2:AttachNetworkInterface",
        "ec2:DescribeNetworkInterfaces",
        "ec2:DeleteNetworkInterface"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
}

resource "aws_s3_bucket_policy" "autograder_results_bucket_policy" {
  bucket = aws_s3_bucket.autograder_results_bucket.bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.codebuild_role_name}" }
      Action = [
        "s3:PutObject",
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        "arn:aws:s3:::${var.s3_bucket_name}",
        "arn:aws:s3:::${var.s3_bucket_name}/*"
      ]
    }]
  })
}

resource "aws_codebuild_project" "autograder_project" {
  name = "autograder-project"
  description = "Autograder project for CS class"
  service_role = aws_iam_role.codebuild_service_role.arn
  source {
    type = "GITHUB"
    location = var.github_repository
  }
  artifacts {
    type = "S3"
    location = var.s3_bucket_name
    name = "autograder-output"
  }
  environment {
    type = "LINUX_CONTAINER"
    image = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type = "BUILD_GENERAL1_SMALL"
    privileged_mode = true
  }
  logs {
    cloudwatch = true
  }
  vpc_config {
    vpc_id = aws_vpc.autograder_vpc.id
    subnets = [aws_subnet.autograder_private_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }
}

data "aws_caller_identity" "current" {}
