LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up an isolated environment for an autograder system that runs students' code from GitHub. The infrastructure includes:

- An **AWS VPC** with a private subnet to isolate the autograder environment.
- An **AWS CodeBuild project** that runs the autograder code.
- An **AWS S3 bucket** to store the results of the autograder runs.
- A **Security Group** that restricts internet access to ensure students' code cannot reach the internet.
- An **IAM role** for CodeBuild to access the S3 bucket and GitHub.
- A **VPC subnet** to host the CodeBuild project in a private network.

All resources are configured to ensure the autograder runs in a secure, isolated environment with no outbound internet access.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.1.0/24"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket for storing autograder results"
  default     = "autograder-results"
}

variable "codebuild_project_name" {
  description = "Name of the CodeBuild project"
  default     = "autograder-codebuild"
}

variable "github_repository" {
  description = "GitHub repository URL for student code"
  default     = "https://github.com/example-student-code/autograder-repo.git"
}

variable "github_owner" {
  description = "GitHub owner of the repository"
  default     = "example-owner"
}

variable "github_token" {
  description = "GitHub personal access token for CodeBuild to clone the repo"
  default     = "your-github-token"
}

variable "codebuild_role_name" {
  description = "Name of the IAM role for CodeBuild"
  default     = "CodeBuildAutograderRole"
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "Autograder VPC"
  }
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = var.subnet_cidr
  map_public_ip_on_launch = false
  tags = {
    Name = "Autograder Private Subnet"
  }
}

resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Security group for autograder with no internet access"
  vpc_id      = aws_vpc.autograder_vpc.id
  tags = {
    Name = "Autograder Security Group"
  }

  # No outbound internet access
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Allow CodeBuild to communicate within the VPC
  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    self        = true
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = var.codebuild_role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "codebuild.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "codebuild_github_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_codebuild_project" "autograder_project" {
  name    = var.codebuild_project_name
  service_role = aws_iam_role.codebuild_role.arn

  environment {
    type = "LINUX_CONTAINER"
    image = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type = "BUILD_GENERAL1_SMALL"
    privileged_mode = true
    image_pull_credentials_type = "CODEBUILD"
    environment_variables = {
      "GITHUB_REPOSITORY" = { value = var.github_repository, type = "PLAINTEXT" }
      "GITHUB_OWNER"       = { value = var.github_owner, type = "PLAINTEXT" }
      "GITHUB_TOKEN"       = { value = var.github_token, type = "PLAINTEXT" }
    }
  }

  source {
    type = "GITHUB"
    location = var.github_repository
    git_submodules_config = "DISABLED"
  }

  artifacts {
    type = "S3"
    location = var.s3_bucket_name
    name = "autograder-output"
  }

  logs {
    cloudwatch_logs {
      status = "ENABLED"
      group_name = "autograder-logs"
      stream_name = "autograder-stream"
    }
  }

  tags = {
    Name = "Autograder CodeBuild Project"
  }
}

resource "aws_s3_bucket" "autograder_results" {
  bucket = var.s3_bucket_name
  acl    = "private"

  tags = {
    Name = "Autograder Results Bucket"
  }
}
