LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates the following AWS resources:

1. **AWS S3 Bucket** - To store code build output.
2. **AWS VPC** - With a CIDR block of `10.0.0.0/16`.
3. **AWS Subnet** - Within the VPC, with a CIDR block of `10.0.0.0/24`.
4. **AWS Security Group** - Linked to the VPC, with no ingress or egress rules to allow internet access.
5. **AWS CodeBuild Project** - Configured to use the S3 bucket for artifacts, with a specific environment type, image, and source configuration. It is also linked to the VPC via a `vpc_config` block.

All resources are defined with default values where necessary, and the configuration is ready to be deployed using Terraform 1.9.8 or later with the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket for storing code build output."
  default     = "codebuild-output-bucket"
}

variable "vpc_name" {
  description = "Name of the VPC."
  default     = "codebuild-vpc"
}

variable "subnet_name" {
  description = "Name of the subnet."
  default     = "codebuild-subnet"
}

variable "security_group_name" {
  description = "Name of the security group."
  default     = "codebuild-sg"
}

variable "github_repository" {
  description = "GitHub repository URL for the source code."
  default     = "github.com/source-location"
}

variable "github_owner" {
  description = "GitHub owner or organization name."
  default     = "your-github-owner"
}

variable "github_access_token" {
  description = "GitHub personal access token for authentication."
  default     = "your-github-token"
}

resource "aws_s3_bucket" "codebuild_output_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc" "codebuild_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "codebuild_subnet" {
  vpc_id            = aws_vpc.codebuild_vpc.id
  cidr_block        = "10.0.0.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = var.subnet_name
  }
}

resource "aws_security_group" "codebuild_sg" {
  name        = var.security_group_name
  description = "Allow internet access for CodeBuild"
  vpc_id      = aws_vpc.codebuild_vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.security_group_name
  }
}

resource "aws_codebuild_project" "codebuild_project" {
  name = "codebuild-project"

  artifacts {
    type = "S3"
    location = aws_s3_bucket.codebuild_output_bucket.bucket
  }

  environment {
    type         = "LINUX_CONTAINER"
    image        = "alpine"
    compute_type = "BUILD_GENERAL1_SMALL"
  }

  source {
    type = "GITHUB"
    location = var.github_repository
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id     = aws_vpc.codebuild_vpc.id
    subnet_ids = [aws_subnet.codebuild_subnet.id]
    security_group_ids = [aws_security_group.codebuild_sg.id]
  }

  service_role = aws_iam_role.codebuild_role.arn

  tags = {
    Environment = "CodeBuild"
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "codebuild.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_role_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/CodeBuildEC2RolePolicy"
}
```

