**Description of the Terraform Program:**

This Terraform configuration sets up an AWS environment that includes:

- An **Amazon S3 bucket** to store uploaded cat pictures.
- An **AWS API Gateway** to expose a REST API endpoint for uploading and retrieving random cat pictures.
- An **AWS Lambda function** to handle the upload and retrieval logic.
- An **IAM role** for the Lambda function to access S3 and API Gateway.
- A **CloudFront distribution** (optional) to serve images more efficiently.
- A **CloudFormation stack** to manage the resources.

The API Gateway will have two endpoints:
- `POST /upload` to upload a cat picture to S3.
- `GET /random` to retrieve a random cat picture from S3.

All resources are configured with default values for variables, and the configuration is ready to be deployed using Terraform.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket for storing cat pictures."
  default     = "cat-pictures-bucket"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function to handle uploads and random picture retrieval."
  default     = "cat-picture-handler"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway."
  default     = "cat-picture-api"
}

variable "cloudfront_distribution_name" {
  description = "Name of the CloudFront distribution (optional)."
  default     = "cat-picture-distribution"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  lifecycle_rule {
    id      = "EnableVersioning"
    enabled = true
  }
}

resource "aws_s3_bucket_policy" "cat_pictures_policy" {
  bucket = aws_s3_bucket.cat_pictures_bucket.id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "arn:aws:s3:::${aws_s3_bucket.cat_pictures_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role" "lambda_role" {
  name = "cat-picture-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_s3_access" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_lambda_function" "cat_picture_handler" {
  function_name    = var.lambda_function_name
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  role             = aws_iam_role.lambda_role.arn
  source_code_hash = "base64:example-hash"
  timeout          = 10

  environment {
    variables = {
      S3_BUCKET_NAME = var.s3_bucket_name
    }
  }
}

resource "aws_iam_role" "api_gateway_role" {
  name = "cat-picture-api-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway_s3_access" {
  role       = aws_iam_role.api_gateway_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name        = var.api_gateway_name
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path        = "/upload"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization  = "NONE"
}

resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = "POST"
  type                    = "AWS_PROXY"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:us-east-1:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_picture_handler.arn}/invocations"
  passthrough_behavior   = "NEVER"
}

resource "aws_api_gateway_method_response" "upload_response" {
