**Description of the Terraform Program:**

This Terraform configuration sets up a complete AWS infrastructure to support a web service that allows users to upload cat pictures and retrieve random cat pictures on demand. The service uses the following AWS resources:

- **AWS S3 Bucket**: To store uploaded cat pictures.
- **AWS DynamoDB Table**: To store metadata about uploaded cat pictures (e.g., keys, timestamps).
- **AWS Lambda Function**: To handle the upload and retrieval logic.
- **AWS Lambda Permission**: To grant the Lambda function permission to write to the S3 bucket.
- **AWS API Gateway REST API**: To expose the service via HTTP endpoints.
- **AWS API Gateway Resource and Method**: To define the endpoints for uploading and retrieving cat pictures.

The configuration includes all necessary IAM roles and permissions to ensure secure and functional operation.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables with default values
variable "s3_bucket_name" {
  default = "cat-pictures-bucket"
}

variable "dynamodb_table_name" {
  default = "cat-pictures-table"
}

variable "lambda_function_name" {
  default = "cat-pictures-lambda"
}

variable "api_gateway_name" {
  default = "cat-pictures-api"
}

# Create S3 Bucket for storing cat pictures
resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  # Enable versioning
  versioning {
    enabled = true
  }

  # Enable server-side encryption
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Create DynamoDB Table to store metadata
resource "aws_dynamodb_table" "cat_pictures_table" {
  name           = var.dynamodb_table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

# Create IAM Role for Lambda
resource "aws_iam_role" "lambda_role" {
  name = "lambda-cat-pictures-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach S3 Access Policy to Lambda Role
resource "aws_iam_role_policy_attachment" "lambda_s3_access" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

# Create Lambda Function
resource "aws_lambda_function" "cat_pictures_lambda" {
  function_name    = var.lambda_function_name
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda.zip"
  role             = aws_iam_role.lambda_role.arn
  source_code_hash = filebase64sha256("lambda.zip")

  environment {
    variables = {
      S3_BUCKET_NAME = var.s3_bucket_name
      DYNAMODB_TABLE_NAME = var.dynamodb_table_name
    }
  }
}

# Create Lambda Permission to write to S3
resource "aws_lambda_permission" "lambda_s3_permission" {
  function_name = aws_lambda_function.cat_pictures_lambda.function_name
  action        = "s3:PutObject"
  principal     = "lambda.amazonaws.com"
  source_arn    = "arn:aws:s3:::${var.s3_bucket_name}/*"
}

# Create API Gateway REST API
resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = var.api_gateway_name
  description = "API for uploading and retrieving cat pictures"
  minimum_version = "2.0"
}

# Create API Gateway Resource for upload endpoint
resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path        = "/upload"
}

# Create API Gateway Method for upload endpoint
resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization  = "NONE"
}

# Create API Gateway Integration for upload endpoint
resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "POST"
  uri                     = aws_lambda_function.cat_pictures_lambda.arn
}

# Create API Gateway Resource for random picture endpoint
resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path        = "/random"
}

# Create API Gateway Method for random picture endpoint
resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random_resource.id
  http_method   = "GET"
  authorization  = "NONE"
}

# Create API Gateway Integration for random picture endpoint
resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random_resource.id
  http_method             = aws_api_gateway_method.random_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "GET"
  uri                     = aws_lambda_function.cat_pictures_lambda.arn
}

# Create API Gateway Deployment
resource "aws_api_gateway_deployment" "cat_pictures_deployment" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"
  description = "Deployment for cat pictures API"
}
