**Description of the Terraform Program:**

This Terraform configuration provisions an AWS EC2 instance and sets up an AWS Backup plan to back up the instance daily at midnight. The configuration includes:

- A VPC with a public subnet.
- A security group allowing SSH access.
- An EC2 instance running a default AMI (Amazon Linux 2).
- An IAM role for the EC2 instance to allow AWS Backup to access the instance.
- An AWS Backup plan that schedules daily backups at midnight.
- A backup vault to store the backups.

All resources are defined within a single AWS region (us-east-1), and default values are provided for variables where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the EC2 instance"
  default     = "backup-ec2-instance"
}

variable "backup_vault_name" {
  description = "Name of the AWS Backup vault"
  default     = "backup-vault"
}

variable "backup_plan_name" {
  description = "Name of the AWS Backup plan"
  default     = "daily-backup-plan"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "backup-vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-ssh"
  }
}

resource "aws_iam_role" "ec2_backup_role" {
  name = "ec2-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_backup_role_policy" {
  role       = aws_iam_role.ec2_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRoleForBackup"
}

resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.public_subnet.id
  security_groups = [aws_security_group.allow_ssh.name]
  key_name      = "my-key-pair" # Ensure this key pair exists in your AWS account
  tags = {
    Name = var.instance_name
  }

  iam_instance_profile = aws_iam_role.ec2_backup_role.name
}

resource "aws_backup_vault" "backup_vault" {
  name = var.backup_vault_name
  tags = {
    Name = var.backup_vault_name
  }
}

resource "aws_backup_plan" "backup_plan" {
  name = var.backup_plan_name
  tags = {
    Name = var.backup_plan_name
  }

  backup_plan_rule {
    name                   = "daily-backup"
    schedule_expression    = "cron(0 0 * * ? *)"
    start_window_days      = 1
    completion_window_minutes = 1440
    copy_actions {
      lifecycle {
        move_to冷存储_after_days = 30
      }
    }
  }

  advanced_schedule {
    schedule_expression = "cron(0 0 * * ? *)"
  }
}

resource "aws_backup_plan_rule" "backup_plan_rule" {
  name = "daily-backup"
  backup_plan_id = aws_backup_plan.backup_plan.id
  schedule_expression = "cron(0 0 * * ? *)"
  start_window_days = 1
  completion_window_minutes = 1440
  copy_actions {
    lifecycle {
      move_to冷存储_after_days = 30
    }
  }
}
```

---

**Notes:**

- The `key_name` variable assumes you have a key pair named `my-key-pair` in your AWS account. You can replace this with a variable or use a key pair created via Terraform.
- The `aws_backup_plan` and `aws_backup_plan_rule` are used together to define the backup schedule.
- The IAM role `ec2-backup-role` is necessary for the EC2 instance to interact with AWS Backup.
- The backup is scheduled to run daily at midnight (`cron(0 0 * * ? *)`).

This configuration is ready to be deployed using Terraform 1.9.8 or later and the `hashicorp/aws` provider version 5.75 or later.

