**Description of the Terraform Program:**

This Terraform configuration provisions an AWS EC2 instance and sets up a daily backup plan using AWS Backup. The EC2 instance is launched with a key pair for secure access. A Backup Vault is created to store the backups, and a Backup Plan is configured to run daily at midnight. The configuration includes all necessary resources such as the EC2 instance, key pair, Backup Vault, and Backup Plan. The EC2 instance is tagged for easy identification, and IAM roles are created to grant the necessary permissions for the Backup service to access the EC2 instance and the Backup Vault.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables
variable "instance_type" {
  default = "t2.micro"
}

variable "ami_id" {
  default = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
}

variable "key_pair_name" {
  default = "my-ec2-key"
}

variable "backup_vault_name" {
  default = "my-backup-vault"
}

variable "backup_plan_name" {
  default = "daily-ec2-backup-plan"
}

variable "backup_schedule" {
  default = "cron(0 0 * * ? *)"
}

variable "backup_retention_days" {
  default = "7"
}

# Create EC2 Key Pair
resource "aws_key_pair" "ec2_key" {
  name = var.key_pair_name
  public_key = file("~/.ssh/id_rsa.pub")
}

# Create EC2 Instance
resource "aws_instance" "ec2_instance" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = aws_key_pair.ec2_key.name
  tags = {
    Name = "daily-backup-ec2"
  }
}

# Create IAM Role for EC2 to allow Backup access
resource "aws_iam_role" "backup_role" {
  name = "backup_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach IAM Policy for Backup Access
resource "aws_iam_role_policy_attachment" "backup_role_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRoleForBackup"
}

# Create Backup Vault
resource "aws_backup_vault" "backup_vault" {
  name = var.backup_vault_name
}

# Create Backup Plan
resource "aws_backup_plan" "backup_plan" {
  name = var.backup_plan_name
  advanced_schedule {
    schedule_expression = var.backup_schedule
  }
  rules {
    name = "daily-ec2-backup"
    schedule = var.backup_schedule
    target {
      backup_vault_name = aws_backup_vault.backup_vault.name
    }
    lifecycle {
      move_to_cold_storage_after_days = 30
      delete_after_days              = var.backup_retention_days
    }
    recovery_point_tags = {
      Environment = "Production"
    }
  }
}

# Associate EC2 Instance with Backup Plan
resource "aws_backup_plan_rule" "backup_rule" {
  backup_plan_id = aws_backup_plan.backup_plan.id
  name           = "daily-ec2-backup"
  schedule       = var.backup_schedule
  target {
    backup_vault_name = aws_backup_vault.backup_vault.name
  }
  lifecycle {
    move_to_cold_storage_after_days = 30
    delete_after_days              = var.backup_retention_days
  }
  recovery_point_tags = {
    Environment = "Production"
  }
}
