**Description of the Terraform Program:**

This Terraform configuration sets up an AWS EventBridge rule that triggers a Lambda function every day at 7:00 UTC. The Lambda function is created with a basic structure and is given a role that allows it to be invoked by EventBridge. The configuration includes:

- An AWS Lambda function with a default handler and runtime.
- An IAM role for the Lambda function with necessary permissions.
- An EventBridge rule that triggers the Lambda function daily at 7:00 UTC.
- A default region (us-east-1) and default values for variables like the Lambda function name and rule name.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_name" {
  default = "daily-task-lambda"
}

variable "eventbridge_rule_name" {
  default = "daily-task-rule"
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda-execution-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "daily_task" {
  function_name    = var.lambda_function_name
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda.zip"
  role             = aws_iam_role.lambda_role.arn
  source_code_hash = "base64:example-hash"
  timeout          = 30
  memory_size      = 128

  environment {
    variables = {
      ENVIRONMENT = "production"
    }
  }
}

resource "aws_eventbridge_rule" "daily_task_rule" {
  name                = var.eventbridge_rule_name
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_eventbridge_target" "daily_task_target" {
  rule      = aws_eventbridge_rule.daily_task_rule.name
  arn       = aws_lambda_function.daily_task.arn
  input     = jsonencode({ "message": "Daily task executed at 7:00 UTC" })
  input_type = "JSON"
}
```

