```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  default     = "lambda_func"
}

variable "lambda_zip_file" {
  description = "Path to the Lambda deployment package"
  default     = "./supplement/lambda_func.zip"
