**Description of the Terraform Program:**

This Terraform configuration sets up the infrastructure for a video streaming site that distributes video content globally using AWS CloudFront and AWS S3. The solution includes:

- A private S3 bucket to store video content.
- An IAM role and policy to allow S3 access.
- A CloudFront distribution that uses the S3 bucket as an origin.
- A CloudFront origin access identity (OAI) to secure the S3 bucket.
- A CloudFront distribution with a custom domain (optional, but can be extended).
- A Route 53 hosted zone and record for the custom domain (optional, but can be extended).

The configuration is designed to be deployable in AWS using Terraform version 1.9.8 or higher and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store video content."
  default     = "video-streaming-bucket"
}

variable "cloudfront_distribution_name" {
  description = "Name of the CloudFront distribution."
  default     = "video-streaming-distribution"
}

variable "custom_domain" {
  description = "Custom domain for the CloudFront distribution (optional)."
  default     = ""
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for the custom domain (optional)."
  default     = ""
}

resource "aws_s3_bucket" "video_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "s3_access_role" {
  name = "s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "s3_access_policy" {
  name = "s3-access-policy"
  role = aws_iam_role.s3_access_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:ListBucket",
        "s3:PutObject"
      ]
      Resource = [
        "${aws_s3_bucket.video_bucket.arn}",
        "${aws_s3_bucket.video_bucket.arn}/*"
      ]
    }]
  })
}

resource "aws_cloudfront_origin_access_identity" "oai" {
  comment = "OAI for video streaming"
}

resource "aws_s3_bucket_policy" "bucket_policy" {
  bucket = aws_s3_bucket.video_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { AWS = aws_iam_role.s3_access_role.arn }
      Action = [
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        "${aws_s3_bucket.video_bucket.arn}",
        "${aws_s3_bucket.video_bucket.arn}/*"
      ]
    }]
  })
}

resource "aws_cloudfront_distribution" "distribution" {
  comment = var.cloudfront_distribution_name
  is_ipv6_enabled = true

  origin {
    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name
    origin_id  = "s3-origin-${var.s3_bucket_name}"
    custom_origin_config {
      http_port         = 80
      https_port        = 443
      origin_protocol_policy = "https-only"
    }
  }

  origin_access_identity {
    origin_access_identity_id = aws_cloudfront_origin_access_identity.oai.id
  }

  default_cache_behavior {
    allowed_methods = ["GET", "HEAD"]
    cached_methods = ["GET", "HEAD"]
    target_origin_id = "s3-origin-${var.s3_bucket_name}"
    forward_cookies = {
      forward = "none"
    }
    viewer_protocol_policy = "redirect-to-http"
    min_ttl = 0
    default_ttl = 3600
    max_ttl = 86400
  }

  price_class = "PriceClass_100"

  enabled = true

  viewer_certificate {
    acm_certificate_arn = ""
    ssl_protocol        = "TLSv1.2"
    minimum_protocol_version = "TLSv1.2"
  }
}

resource "aws_route53_record" "custom_domain" {
  if var.custom_domain != "" {
    name    = var.custom_domain
    type    = "A"
    zone_id = var.route53_zone_id
    records = [aws_cloudfront_distribution.distribution.domain_name]
    ttl     = 300
  }
}
```

