  name = "CloudFrontOriginAccessIdentityRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "cloudfront_policy" {
  name        = "CloudFrontOriginAccessPolicy"
  description = "Policy allowing CloudFront to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
        ]
        Resource = "${aws_s3_bucket.video_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudfront_role_attachment" {
  role       = aws_iam_role.cloudfront_role.name
  policy_arn = aws_iam_policy.cloudfront_policy.arn
}

resource "aws_cloudfront_origin_access_identity" "origin_access_identity" {
  comment = "Origin Access Identity for video streaming"
}

resource "aws_cloudfront_distribution" "video_distribution" {
  comment = var.cloudfront_distribution_name

  origin {
    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name
    origin_id   = "s3-origin-${var.s3_bucket_name}"
    custom_origin_config {
      http_port         = 80
      https_port        = 443
      origin_protocol_policy = "https-only"
    }
  }

  origin_access_identity = aws_cloudfront_origin_access_identity.origin_access_identity.id

  default_cache_behavior {
    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]
    target_origin   = { id = "s3-origin-${var.s3_bucket_name}" }
    forward_cookies = {
      forward = "none"
    }
    viewer_protocol_policy = "redirect-to-http"
    min_ttl = 0
    default_ttl = 3600
    max_ttl = 86400
  }

  price_class = "PriceClass_100"

  enabled = true

  tags = {
    Name        = var.cloudfront_distribution_name
    Environment = "production"
  }
}

resource "aws_route53_record" "video_record" {
  name    = var.domain_name
  zone_id = var.route53_zone_id
  type    = "A"
  ttl     = 300

  alias {
    name    = aws_cloudfront_distribution.video_distribution.domain_name
    zone_id = aws_cloudfront_distribution.video_distribution.aliases[0].zone_id
    evaluate_target_health = false
  }
}

resource "aws_acm_certificate" "video_certificate" {
  certificate_authority_arn = var.certificate_arn
  certificate              = file("path/to/certificate.pem")
  private_key              = file("path/to/private.key")
}
```

> **Note:** Replace the `certificate_arn`, `certificate`, and `private_key` values with your actual ACM certificate details. The certificate must be issued for the domain name used in the configuration.

