**Description of the Terraform Program:**

This Terraform configuration sets up the infrastructure for a video streaming site that distributes video content globally. It includes the following key components:

- **AWS Route53 Zone**: Creates a private or public DNS zone for the domain used by the video streaming site.
- **AWS S3 Bucket**: Stores the video content. It is configured with a static website endpoint and appropriate permissions.
- **AWS CloudFront Distribution**: Distributes the video content globally using CloudFront, with an origin access control (OAC) to secure the S3 bucket.
- **AWS Route53 Record**: Points the domain to the CloudFront distribution's domain name.
- **IAM Roles and Policies**: Ensures secure access between S3 and CloudFront, and proper permissions for Route53.

All resources are configured with default values where necessary, and the configuration is ready to be deployed using Terraform 1.9.8 or later with the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site."
  default     = "example.com"
}

variable "zone_id" {
  description = "The Route53 hosted zone ID for the domain."
  default     = "Z1234567890ABCDEF"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket to store video content."
  default     = "video-content-bucket"
}

variable "cloudfront_distribution_name" {
  description = "The name of the CloudFront distribution."
  default     = "video-streaming-distribution"
}

resource "aws_s3_bucket" "video_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  lifecycle_rule {
    id      = "EnableVersioning"
    enabled = true
  }
}

resource "aws_s3_bucket_policy" "video_bucket_policy" {
  bucket = aws_s3_bucket.video_bucket.id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::aws:root"
        }
        Action = "s3:GetObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_bucket.bucket}/*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::aws:root"
        }
        Action = "s3:ListBucket"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_bucket.bucket}"
      }
    ]
  })
}

resource "aws_iam_role" "cloudfront_role" {
  name = "cloudfront-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudfront_s3_access" {
  name = "cloudfront-s3-access"
  role = aws_iam_role.cloudfront_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::${aws_s3_bucket.video_bucket.bucket}",
          "arn:aws:s3:::${aws_s3_bucket.video_bucket.bucket}/*"
        ]
      }
    ]
  })
}

resource "aws_cloudfront_origin_access_control" "origin_access_control" {
  name = "video-origin-access-control"
  comment = "Origin Access Control for video streaming"
}

resource "aws_cloudfront_distribution" "video_distribution" {
  comment = "Video Streaming Distribution"
  origin {
    domain_name = aws_s3_bucket.video_bucket.website_endpoint
    origin_id   = "s3-origin-${var.s3_bucket_name}"
  }
  origin_access_control_id = aws_cloudfront_origin_access_control.origin_access_control.id
  default_cache_behavior {
    allowed_methods = ["GET", "HEAD"]
    cached_methods = ["GET", "HEAD"]
    target_origin_id = "s3-origin-${var.s3_bucket_name}"
    forward_cookies = {
      forward = "none"
    }
    viewer_protocol_policy = "redirect-to-http"
    min_ttl = 0
    default_ttl = 3600
    max_ttl = 86400
  }
  enabled = true
  is_ipv4_only = false
  price_class = "PriceClass_100"
  viewer_certificate {
    acm_certificate_arn = ""
    ssl_protocol = "TLSv1.2"
    minimum_protocol_version = "TLSv1.2"
  }
  aliases = [var.domain_name]
  tags = {
    Name = var.cloudfront_distribution_name
  }
}

resource "aws_route53_record" "cloudfront_record" {
  name    = var.domain_name
  zone_id = var.zone_id
  type    = "A"
  ttl     = 300
  records = [aws_cloudfront_distribution.video_distribution.domain_name]
}
```

