LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up the infrastructure for a video streaming site that uses AWS Load Balancing to distribute traffic across multiple servers. The infrastructure includes:

- A VPC to isolate the network.
- A public subnet to host the load balancer and EC2 instances.
- A security group to allow HTTP traffic.
- An Application Load Balancer (ALB) to distribute traffic.
- Two EC2 instances running a web server (e.g., Nginx) to serve video content.
- IAM roles for the EC2 instances to allow them to communicate with the load balancer and access necessary services.
- A default route for internet access via an Internet Gateway.

All resources are created in the `us-east-1` region, and default values are provided for variables to ensure the configuration is deployable without additional input.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "instance_type" {
  description = "Type of EC2 instance to use"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instance"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "video-streaming-sg"
}

variable "load_balancer_name" {
  description = "Name of the load balancer"
  default     = "video-streaming-alb"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_security_group" "web_sg" {
  name        = var.security_group_name
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "video-streaming-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_lb" "alb" {
  name               = var.load_balancer_name
  subnets           = [aws_subnet.public.id]
  security_groups   = [aws_security_group.web_sg.id]
  idle_timeout_sec  = 60
  enable_deletion_protection = false
}

resource "aws_lb_target_group" "target_group" {
  name        = "video-streaming-target-group"
  port        = 80
  protocol    = "http"
  vpc_id      = aws_vpc.main.id
  health_check {
    path                = "/health"
    protocol            = "HTTP"
    port                = "80"
    interval_seconds     = 30
    timeout_seconds      = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    forward {
      target_group_arns = [aws_lb_target_group.target_group.arn]
    }
  }
}

resource "aws_instance" "web_server_1" {
  count             = 2
  ami              = var.ami_id
  instance_type    = var.instance_type
  subnet_id        = aws_subnet.public.id
  vpc_id           = aws_vpc.main.id
  security_groups  = [aws_security_group.web_sg.id]
  iam_instance_profile = aws_iam_role.ec2_role.name
  key_name         = "my-key-pair" # Ensure this key pair exists in AWS
  user_data        = <<-EOF
                    #!/bin/bash
                    sudo yum update -y
                    sudo yum install -y httpd
                    sudo systemctl start httpd
                    sudo systemctl enable httpd
                    echo "Hello, Video Streaming!" > /var/www/html/index.html
                    EOF

  tags = {
    Name = "web-server-${count.index + 1}"
  }
}

resource "aws_lb_target_group_attachment" "target_group_attachment" {
  count             = 2
  target_group_arn = aws_lb_target_group.target_group.arn
  target_id        = aws_instance.web_server_1[count.index].id
  port             = 80
}
```

