    path          = "/index.html"
    protocol      = "HTTP"
    port          = "80"
    interval      = 30
    timeout       = 10
    healthy_threshold = 3
    unhealthy_threshold = 3
  }
}

resource "aws_lb_listener" "http_listener" {
