LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration sets up the infrastructure for a video streaming site that uses AWS resources to balance load across multiple servers. The infrastructure includes:

- A **VPC** with public and private subnets.
- A **security group** to control inbound and outbound traffic.
- **EC2 instances** that act as web servers.
- A **Load Balancer** (Application Load Balancer) to distribute traffic.
- A **Target Group** to register the EC2 instances.
- A **Route 53 hosted zone** and a **DNS record** to point the domain to the Load Balancer.

All resources are created in a single AWS region, and IAM roles are defined as needed for security and access control.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "instance_type" {
  description = "Type of EC2 instance to launch"
  default     = "t2.micro"
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "video-streaming-sg"
}

variable "domain_name" {
  description = "Domain name for the video streaming site"
  default     = "streaming.example.com"
}

variable "route53_zone_name" {
  description = "Name of the Route 53 hosted zone"
  default     = "example.com"
}

variable "load_balancer_name" {
  description = "Name of the Application Load Balancer"
  default     = "video-streaming-alb"
}

variable "target_group_name" {
  description = "Name of the target group"
  default     = "video-streaming-tg"
}

variable "num_instances" {
  description = "Number of EC2 instances to launch"
  default     = 2
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  map_public_ip_on_launch = false
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_security_group" "web_sg" {
  name        = var.security_group_name
  description = "Allow HTTP and SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_key_pair" "ssh_key" {
  key_name   = "video-streaming-key"
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_instance" "web_server" {
  count             = var.num_instances
  ami              = "ami-0c55b159cbfafe1f0" # Amazon Linux 2
  instance_type    = var.instance_type
  subnet_id        = aws_subnet.public.id
  security_groups   = [aws_security_group.web_sg.name]
  key_name         = aws_key_pair.ssh_key.key_name
  associate_public_ip_address = true

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y httpd
    sudo systemctl start httpd
    sudo systemctl enable httpd
    echo "Hello from instance ${count.index + 1}" > /var/www/html/index.html
  EOF

  tags = {
    Name = "web-server-${count.index + 1}"
  }
}

resource "aws_lb" "alb" {
  name               = var.load_balancer_name
  subnets           = [aws_subnet.public.id]
  security_groups   = [aws_security_group.web_sg.id]
}

resource "aws_lb_target_group" "tg" {
  name        = var.target_group_name
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  health_check {
    path          = "/index.html"
    protocol      = "HTTP"
    port          = "80"
    interval      = 30
    timeout       = 10
    healthy_threshold = 5
    unhealthy_threshold = 3
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.tg.arn
  }
}

resource "aws_route53_zone" "zone" {
  name = var.route53_zone_name
}

resource "aws_route53_record" "record" {
  name    = var.domain_name
  zone_id = aws_route53_zone.zone.id
  type    = "A"
  ttl     = 300
  records = [aws_lb.alb.dns_name]
}
