**Description of the Terraform Program:**

This Terraform configuration defines a complete AWS infrastructure for a video streaming application. It includes:

- A VPC with CIDR `10.0.0.0/16`.
- Three subnets within the VPC with CIDRs `10.0.4.0/24`, `10.0.5.0/24`, and `10.0.6.0/24`.
- A security group that allows ingress from the VPC CIDR range on port 80 (TCP) and egress from any IP on port 80 (TCP).
- An Application Load Balancer (ALB) with the specified subnets and security group.
- A target group for the ALB that listens on port 80 with HTTP protocol.
- A listener on the ALB that forwards traffic to the target group.
- A target group attachment that links an EC2 instance (latest Ubuntu) to the target group.
- A Route 53 hosted zone for the domain `test-video-stream.com`.
- Two Route 53 alias records for `lb.test-video-stream.com` that point to the ALB's DNS names (IPv4 and IPv6), with health checks enabled.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  default = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

variable "security_group_name" {
  default = "video-stream-sg"
}

variable "lb_name" {
  default = "video-stream-alb"
}

variable "target_group_name" {
  default = "video-stream-tg"
}

variable "ec2_instance_type" {
  default = "t2.micro"
}

variable "ami_id" {
  default = "ami-0c55b159cbfafe1f0" # Ubuntu 22.04 LTS (HVM), SSD Volume Type - us-east-1
}

variable "domain_name" {
  default = "test-video-stream.com"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "main" {
  count = length(var.subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = var.subnet_cidrs[count.index]
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "main" {
  name        = var.security_group_name
  description = "Allow HTTP traffic and VPC CIDR ingress"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "main" {
  name               = var.lb_name
  load_balancer_type = "application"
  security_groups    = [aws_security_group.main.id]
  subnets           = aws_subnet.main.*.id
}

resource "aws_lb_target_group" "main" {
  name        = var.target_group_name
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
}

resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_ec2_instance" "main" {
  ami           = var.ami_id
  instance_type = var.ec2_instance_type
  subnet_id     = aws_subnet.main[0].id
  vpc_security_group_ids = [aws_security_group.main.id]

  user_data = <<-EOF
    #!/bin/bash
    apt update && apt install -y nginx
    systemctl start nginx
    systemctl enable nginx
  EOF

  tags = {
    Name = "video-stream-ec2"
  }
}

resource "aws_lb_target_group_attachment" "main" {
  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_ec2_instance.main.id
  port             = 80
}

resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_route53_record" "lb_alias_ipv4" {
  name    = "lb.${var.domain_name}"
  zone_id = aws_route53_zone.main.id
  type    = "A"
  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "lb_alias_ipv6" {
  name    = "lb.${var.domain_name}"
  zone_id = aws_route53_zone.main.id
  type    = "AAAA"
  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}
```

