**Description of the Terraform Program:**

This Terraform configuration sets up a VPC with public subnets, creates a security group to control access to a PostgreSQL database instance, and provisions a PostgreSQL database instance within the VPC. The security group is configured to allow access from specific sources (e.g., a bastion host or application server) and restricts access to only necessary ports (e.g., 5432 for PostgreSQL). The PostgreSQL instance is launched with an IAM role that grants it the necessary permissions to operate within the VPC.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "security_group_name" {
  description = "Name of the security group for the PostgreSQL instance"
  default     = "postgres-sg"
}

variable "allowed_ip_cidr" {
  description = "CIDR block of the source IP that can access the PostgreSQL instance"
  default     = "192.168.1.0/24"
}

variable "postgres_db_name" {
  description = "Name of the PostgreSQL database"
  default     = "mydb"
}

variable "postgres_username" {
  description = "Username for the PostgreSQL database"
  default     = "admin"
}

variable "postgres_password" {
  description = "Password for the PostgreSQL database"
  default     = "securepassword"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "postgres_sg" {
  name        = var.security_group_name
  description = "Security group for PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ip_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.security_group_name
  }
}

resource "aws_db_instance" "postgres" {
  allocated_storage    = 20
  storage_type         = "gp2"
  engine               = "postgres"
  engine_version       = "16.1"
  instance_class       = "db.t3.micro"
  db_name              = var.postgres_db_name
  username             = var.postgres_username
  password             = var.postgres_password
  vpc_security_group_ids = [aws_security_group.postgres_sg.id]
  vpc_id               = aws_vpc.main.id
