**Description of the Terraform Program:**

This Terraform configuration provisions a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS RDS, subnets, and KMS for encryption. The configuration includes:

- A custom PostgreSQL parameter group for tuning database settings.
- A security group to control access to the database instance.
- A PostgreSQL RDS instance with multi-AZ deployment for high availability.
- Encryption at rest using a KMS key.
- Storage size and engine version specified.
- The RDS instance is placed in a specified VPC and subnet group.

All resources are defined with default values where necessary, and the configuration is ready to be deployed using Terraform 1.9.8 or later with the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be overridden via variable
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs within the VPC for the RDS instance."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "kms_key_arn" {
  description = "ARN of the KMS key used for encryption at rest."
  default     = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance."
  default     = "secure-postgres-db"
}

variable "db_engine_version" {
  description = "Engine version for PostgreSQL."
  default     = "16.4"
}

variable "db_storage_size" {
  description = "Storage size in GB for the RDS instance."
  default     = 20
}

variable "db_username" {
  description = "Username for the PostgreSQL database."
  default     = "admin"
}

variable "db_password" {
  description = "Password for the PostgreSQL database."
  default     = "securepassword123"
}

variable "db_port" {
  description = "Port for the PostgreSQL database."
  default     = 5432
}

variable "db_instance_class" {
  description = "Instance class for the RDS instance."
  default     = "db.t3.medium"
}

variable "db_multi_az" {
  description = "Whether to deploy the RDS instance in a multi-AZ configuration."
  default     = true
}

variable "db_parameter_group_name" {
  description = "Name of the custom PostgreSQL parameter group."
  default     = "custom-postgres-params"
}

variable "security_group_name" {
  description = "Name of the security group for the RDS instance."
  default     = "rds-db-access"
}

resource "aws_db_parameter_group" "postgres_param_group" {
  name        = var.db_parameter_group_name
  family      = "postgres16"
  description = "Custom PostgreSQL parameter group for tuning"

  parameter {
    name     = "max_connections"
    value    = "200"
    apply_method = "pending-reboot"
  }

  parameter {
    name     = "shared_buffers"
    value    = "128MB"
    apply_method = "pending-reboot"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = var.security_group_name
  description = "Security group for PostgreSQL RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = var.db_port
    to_port     = var.db_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres_db" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = var.db_instance_class
  allocated_storage      = var.db_storage_size
  storage_type            = "gp2"
  multi_az                = var.db_multi_az
  db_name                 = "secure_db"
  username                = var.db_username
  password               = var.db_password
  port                    = var.db_port
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  db_parameter_group_name = aws_db_parameter_group.postgres_param_group.name
  skip_final_snapshot     = true
