**Description of the Terraform Program:**

This Terraform configuration provisions a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS RDS, subnets, and KMS for encryption. The configuration includes:

- A custom PostgreSQL parameter group for tuning database settings.
- A security group to control access to the database instance.
- A PostgreSQL database instance with the following specifications:
  - Instance class: `db.t3.micro`
  - Storage size: 20 GB
  - Engine version: `14.10`
  - Multi-AZ deployment: enabled
  - Backup retention period: 7 days
  - Encryption using a KMS key
- The database is placed in a private subnet of the specified VPC.
- IAM roles are created to allow the RDS instance to access KMS for encryption.

All resources are defined with default values where necessary, and the configuration is deployable with Terraform 1.9.8 and hashicorp/aws 5.75.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the private subnets."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "kms_key_arn" {
  description = "The ARN of the KMS key used for encryption."
  default     = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS database instance."
  default     = "secure-postgres-db"
}

variable "db_engine_version" {
  description = "Engine version for PostgreSQL."
  default     = "14.10"
}

variable "db_instance_class" {
  description = "Instance class for the RDS database."
  default     = "db.t3.micro"
}

variable "db_storage_size" {
  description = "Storage size in GB for the RDS database."
  default     = 20
}

variable "backup_retention_period" {
  description = "Backup retention period in days."
  default     = 7
}

variable "multi_az" {
  description = "Whether to enable Multi-AZ deployment."
  default     = true
}

variable "db_username" {
  description = "Username for the database instance."
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database instance."
  default     = "securepassword123"
}

resource "aws_db_parameter_group" "postgres_param_group" {
  name        = "postgres-param-group"
  family      = "postgres14"
  description = "Custom parameter group for PostgreSQL settings"

  parameter {
    name     = "max_connections"
    value    = "100"
    apply_method = "pending-reboot"
  }

  parameter {
    name     = "shared_buffers"
    value    = "128MB"
    apply_method = "pending-reboot"
  }
}

resource "aws_security_group" "postgres_sg" {
  name        = "postgres-sg"
  description = "Security group for PostgreSQL database"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres_db" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = var.db_instance_class
  allocated_storage      = var.db_storage_size
  backup_retention_period = var.backup_retention_period
  multi_az                = var.multi_az
  storage_encrypted       = true
  kms_key_id              = var.kms_key_arn
  db_name                 = "mydb"
  username                = var.db_username
  password               = var.db_password
  parameter_group_name    = aws_db_parameter_group.postgres_param_group.name
  vpc_security_group_ids  = [aws_security_group.postgres_sg.id]

  # Subnet group
  subnet_ids = var.subnet_ids

  # IAM role for KMS access
  iam_role = aws_iam_role.rds_kms_role.arn
}

resource "aws_iam_role" "rds_kms_role" {
  name = "rds_kms_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_kms_role_policy" {
  role       = aws_iam_role.rds_kms_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSKMSKeyUsage"
}
```

