**Description of Terraform Program:**

This Terraform configuration sets up a PostgreSQL 15 instance on AWS RDS. The instance is deployed within specified public subnets to allow for network access during Airbyte connector test cases. The configuration uses managed settings to minimize maintenance. The database is configured to skip the final snapshot upon deletion, and any changes to the instance will apply immediately. An IAM role is created to grant the RDS instance the necessary permissions to operate within the VPC and subnets.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of public subnet IDs where the RDS instance will be placed."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the RDS instance."
  default     = "sg-12345678"
}

variable "db_name" {
  description = "The name of the database to be created."
  default     = "airbyte_test_db"
}

variable "db_username" {
  description = "The username for the database."
  default     = "airbyte_user"
}

variable "db_password" {
  description = "The password for the database user."
  default     = "securepassword123"
}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance."
  default     = "airbyte-postgres-test"
}

variable "db_engine_version" {
  description = "The version of the PostgreSQL engine to use."
  default     = "15.6"
}

variable "db_instance_class" {
  description = "The instance class for the RDS instance."
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "The allocated storage in GB for the RDS instance."
  default     = 20
}

variable "skip_final_snapshot" {
  description = "Whether to skip the final snapshot when the instance is deleted."
  default     = true
}

resource "aws_db_instance" "postgres_instance" {
  allocated_storage         = var.db_allocated_storage
  engine                    = "postgres"
  engine_version            = var.db_engine_version
  instance_class            = var.db_instance_class
  db_name                   = var.db_name
  username                  = var.db_username
  password                  = var.db_password
  db_instance_identifier    = var.db_instance_identifier
  skip_final_snapshot       = var.skip_final_snapshot
  vpc_security_group_ids    = [var.security_group_id]
  storage_type              = "gp2"
  backup_retention_period    = 0
  deletion_protection        = false
  publicly_accessible        = true
  availability_zone          = ""
  db_subnet_group_name       = ""
  parameter_group_name       = ""
  storage_encrypted          = false
  copy_tags_to_snapshot      = false
  monitoring_interval        = 0
  monitoring_role_arn        = ""
  performance_insights_kms_key_id = ""
  port                        = 5432
  preferred_backup_window     = ""
  preferred_maintenance_window = ""
  tags = {
    Environment = "test"
    Purpose     = "Airbyte Connector Testing"
  }
}

resource "aws_iam_role" "rds_role" {
  name = "rds_role_for_airbyte"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "rds.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_role_policy" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
}
```

---

**Notes:**

- This configuration assumes that the VPC, subnets, and security group are already created and available.
- The `publicly_accessible` flag is set to `true` to allow access from public networks, which is necessary for Airbyte connector test cases.
- The `skip_final_snapshot` is set to `true` to avoid the final snapshot when the instance is deleted.
- The `backup_retention_period` is set to `0` to ensure that no backups are retained, which aligns with the low-maintenance requirement.
- The `deletion_protection` is set to `false` to allow the instance to be deleted without protection.
- The `aws_iam_role` and `aws_iam_role_policy_attachment` are created to grant the RDS instance the necessary permissions to operate within the VPC and subnets.

