**Description of the Terraform Program:**

This Terraform configuration sets up a complete AWS environment for a database application. It includes:

- A main VPC with a CIDR block.
- Two subnets in different Availability Zones (AZs) within the VPC.
- A security group that allows inbound access to a MySQL RDS instance (port 3306).
- A MySQL RDS instance configured to be publicly accessible, associated with the defined subnets and security group.
- Outputs the endpoint of the RDS instance for application connectivity.

The configuration uses the `hashicorp/aws` provider and is designed to be deployable with Terraform 1.9.8 or later.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_a" {
  description = "CIDR block for subnet A"
  default     = "10.0.1.0/24"
}

variable "subnet_cidr_b" {
  description = "CIDR block for subnet B"
  default     = "10.0.2.0/24"
}

variable "security_group_name" {
  description = "Name for the security group"
  default     = "rds-access-sg"
}

variable "rds_instance_name" {
  description = "Name for the RDS instance"
  default     = "mysql-db-instance"
}

variable "rds_db_username" {
  description = "Database username"
  default     = "admin"
}

variable "rds_db_password" {
  description = "Database password"
  default     = "securepassword123"
}

variable "rds_db_name" {
  description = "Database name"
  default     = "mydb"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_a
  availability_zone = "us-west-2a"
  tags = {
    Name = "subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_b
  availability_zone = "us-west-2b"
  tags = {
    Name = "subnet-b"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = var.security_group_name
  description = "Allow MySQL access"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.security_group_name
  }
}

resource "aws_db_instance" "mysql_db" {
  allocated_storage    = 20
  storage_type         = "gp2"
  engine               = "mysql"
  engine_version       = "8.0.33"
  instance_class       = "db.t3.micro"
  db_name              = var.rds_db_name
  username             = var.rds_db_username
  password             = var.rds_db_password
  port                 = 3306
  publicly_accessible  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  subnet_ids           = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
  skip_final_snapshot  = true
  tags = {
    Name = var.rds_instance_name
  }
}

output "rds_endpoint" {
  description = "The endpoint of the RDS instance"
  value       = aws_db_instance.mysql_db.endpoint
}
```

