This Terraform configuration sets up a complete AWS environment for a database application. It includes:

- A **main VPC** with a CIDR block.
- **Two subnets** in different availability zones (AZs) within the VPC.
- A **security group** that allows inbound access to a MySQL database on port 3306.
- A **MySQL RDS instance** (version 5.7) with a size of 500 GB, configured to be publicly accessible.
- The RDS instance is linked to the defined subnets and security group.
- Outputs the **database endpoint** for easy connectivity.

All resources are created in a single AWS region, and the configuration is designed to be deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_a" {
  description = "CIDR block for subnet A"
  default     = "10.0.1.0/24"
}

variable "subnet_cidr_b" {
  description = "CIDR block for subnet B"
  default     = "10.0.2.0/24"
}

variable "security_group_name" {
  description = "Name for the security group"
  default     = "mysql-db-access"
}

variable "rds_instance_name" {
  description = "Name for the RDS instance"
  default     = "mysql-db-instance"
}

variable "rds_instance_size" {
  description = "Size of the RDS instance (e.g., db.t3.medium)"
  default     = "db.t3.medium"
}

variable "rds_engine_version" {
  description = "Engine version for the RDS instance"
  default     = "5.7.mysql_aurora.2.06.2"
}

variable "rds_allocated_storage" {
  description = "Allocated storage in GB for the RDS instance"
  default     = "500"
}

variable "rds_publicly_accessible" {
  description = "Whether the RDS instance is publicly accessible"
  default     = true
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_a
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_b
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "db_security_group" {
  name        = var.security_group_name
  description = "Allow MySQL access"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

