All resources are created in the `us-east-1` region. The configuration uses default values for variables where applicable and ensures all resources are declared and referenced properly.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "database_username" {
  description = "Username for the PostgreSQL database"
  default     = "admin"
}

variable "database_password" {
  description = "Password for the PostgreSQL database"
  default     = "securepassword123"
}

variable "allowed_ip_range" {
  description = "IP range allowed to access the database"
  default     = "0.0.0.0/0"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "subnet-az1"
  }
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  tags = {
    Name = "subnet-az2"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group"
  description = "Allow PostgreSQL access"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ip_range]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-security-group"
  }
}

resource "aws_db_instance" "postgres_db" {
  allocated_storage    = 20
  storage_type         = "gp2"
  engine               = "postgres"
  engine_version       = "15.3"
  instance_class       = "db.t3.micro"
  db_name              = "mydb"
  username             = var.database_username
  password             = var.database_password
  port                 = 5432
  publicly_accessible  = true
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  subnet_ids           = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id]
  tags = {
    Name = "postgres-db"
  }
}

output "database_endpoint" {
  value = aws_db_instance.postgres_db.endpoint
}
