**Description of the Terraform Program:**

This Terraform configuration sets up a PostgreSQL database instance in AWS. It includes the following components:

- A custom VPC with a public and private subnet.
- A route table for the private subnet with a NAT gateway for outbound internet access.
- An IAM role for the RDS instance to allow necessary permissions.
- A PostgreSQL database instance with specified engine version, instance size, storage, and networking configuration.
- Security groups to control access to the database instance.
- A default variable block to provide default values for parameters like region, VPC CIDR, subnet CIDR, and instance size.

The configuration is designed to be deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "instance_type" {
  description = "Instance type for the PostgreSQL database"
  default     = "db.t3.micro"
}

variable "storage_size" {
  description = "Storage size in GB for the PostgreSQL database"
  default     = 20
}

variable "engine_version" {
  description = "Engine version for the PostgreSQL database"
  default     = "16.4"
}

variable "db_name" {
  description = "Name of the PostgreSQL database"
  default     = "mydb"
}

variable "db_username" {
  description = "Username for the PostgreSQL database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the PostgreSQL database"
  default     = "securepassword"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  map_public_ip_on_launch = false
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_nat_gateway" "nat" {
  subnet_id   = aws_subnet.public.id
  allocation_id = aws_eip.eip.id
}

resource "aws_eip" "eip" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "private_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "private_route" {
  route_table_id         = aws_route_table.private_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.nat.id
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group"
  description = "Allow access to PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_role" {
  name = "rds-db-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_role_policy" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSDBInstanceRole"
}

resource "aws_db_instance" "postgres" {
  allocated_storage    = var.storage_size
  engine               = "postgres"
  engine_version       = var.engine_version
  instance_class       = var.instance_type
  db_name              = var.db_name
  username             = var.db_username
  password             = var.db_password
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  storage_type         = "gp2"
  skip_final_snapshot  = true
  db_subnet_group_name = aws_db_subnet_group.db_subnets.name
  iam_role_arn         = aws_iam_role.rds_role.arn
}

resource "aws_db_subnet_group" "db_subnets" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.private.id]
}
```

