**Description of the Terraform Program:**

This Terraform configuration sets up a 5 GB PostgreSQL database instance in AWS, with the following specifications:

- **Database Engine:** PostgreSQL
- **Engine Version:** PostgreSQL 16 (can be adjusted)
- **Instance Size:** t3.micro (can be adjusted)
- **Storage:** 5 GB (with a max allocated storage of 50 GB)
- **Networking:** Deployed within a custom VPC and subnet
- **Maintenance Window:** 0:00 to 3:00 AM on Monday
- **IAM Roles:** Created to allow the RDS instance to interact with the VPC and subnet
- **Region:** us-east-1 (can be adjusted)
- **Provider:** hashicorp/aws ~> 5.75
- **Variables:** Used with default values for flexibility

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to deploy the RDS instance in."
  default     = "vpc-12345678"
}

variable "subnet_id" {
  description = "The ID of the subnet to deploy the RDS instance in."
  default     = "subnet-12345678"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance."
  default     = "postgres-db-instance"
}

variable "db_engine_version" {
  description = "Engine version for PostgreSQL."
  default     = "16.1"
}

variable "db_instance_size" {
  description = "Instance size for the RDS instance."
  default     = "t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the RDS instance."
  default     = 5
}

variable "db_max_allocated_storage" {
  description = "Maximum allocated storage for the RDS instance."
  default     = 50
}

variable "db_maintenance_window_start" {
  description = "Start time for the maintenance window."
  default     = "0:00"
}

variable "db_maintenance_window_end" {
  description = "End time for the maintenance window."
  default     = "3:00"
}

variable "db_maintenance_window_day" {
  description = "Day of the week for the maintenance window."
  default     = "monday"
}

resource "aws_db_instance" "postgres_db" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = var.db_instance_size
  allocated_storage      = var.db_allocated_storage
  max_allocated_storage  = var.db_max_allocated_storage
  vpc_security_group_ids = [aws_db_security_group.postgres_db_sg.id]
  subnet_id               = var.subnet_id
  vpc_id                  = var.vpc_id
  maintenance_window      = "${var.db_maintenance_window_day}:${var.db_maintenance_window_start}-${var.db_maintenance_window_day}:${var.db_maintenance_window_end}"
  skip_final_snapshot     = true
}

resource "aws_db_security_group" "postgres_db_sg" {
  name        = "postgres-db-sg"
  description = "Security group for PostgreSQL DB instance"

  vpc_id = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
