**Description of the Terraform Program:**

This Terraform configuration sets up a PostgreSQL database instance in AWS. It includes the following components:

- A custom VPC with a public and private subnet.
- A route table for the private subnet to allow communication with the database instance.
- A security group that restricts access to the database instance to only allow internal traffic within the VPC.
- A PostgreSQL database instance configured with:
  - A specific engine version.
  - Instance size (e.g., `db.t3.micro`).
  - Storage size (e.g., 20 GB).
  - Major version upgrade enabled.
  - Minor version upgrade enabled.
  - Public accessibility disabled.
- IAM roles and policies are created to ensure the database instance has the necessary permissions to operate within the VPC and subnet.

All resources are defined with default values for variables, and the configuration is deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "engine_version" {
  description = "PostgreSQL engine version"
  default     = "14.5"
}

variable "instance_class" {
  description = "Instance class for the PostgreSQL database"
  default     = "db.t3.micro"
}

variable "storage_size" {
  description = "Storage size in GB for the PostgreSQL database"
  default     = 20
}

variable "db_name" {
  description = "Name of the PostgreSQL database"
  default     = "mydb"
}

variable "db_username" {
  description = "Username for the PostgreSQL database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the PostgreSQL database"
  default     = "securepassword"
}

variable "db_port" {
  description = "Port for the PostgreSQL database"
  default     = 5432
}

variable "allow_major_version_upgrade" {
  description = "Whether to allow major version upgrades"
  default     = true
}

variable "auto_minor_version_upgrade" {
  description = "Whether to enable automatic minor version upgrades"
  default     = true
}

variable "publicly_accessible" {
  description = "Whether the database is publicly accessible"
  default     = false
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  map_public_ip_on_launch = false
}

resource "aws_route_table" "private_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "private_association" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private_route_table.id
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group"
  description = "Security group for PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = var.db_port
    to_port     = var.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-security-group"
  }
}

resource "aws_db_instance" "postgres" {
  engine                     = "postgres"
  engine_version             = var.engine_version
  instance_class             = var.instance_class
  allocated_storage         = var.storage_size
  storage_type              = "gp2"
  db_name                    = var.db_name
  username                   = var.db_username
  password                  = var.db_password
  port                       = var.db_port
  allow_major_version_upgrade = var.allow_major_version_upgrade
  auto_minor_version_upgrade  = var.auto_minor_version_upgrade
  publicly_accessible        = var.publicly_accessible
  vpc_security_group_ids     = [aws_security_group.db_sg.id]
  db_subnet_group_name       = aws_db_subnet_group.db_subnet_group.name
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "db-subnet-group"
  subnet_ids = [aws_subnet.private.id]
}
```

