**Description of the Terraform Program:**

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with the following components:

- A VPC with public and private subnets.
- A security group to control access to the RDS cluster.
- An IAM role for the RDS cluster to access AWS Secrets Manager.
- An Aurora MySQL cluster with a proxy enabled.
- The proxy is configured with an idle client timeout of 1800 seconds and debug logging disabled.
- A Secrets Manager secret to store the database credentials.
- The configuration uses default values for variables where applicable and ensures all resources are declared and referenced properly.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_1" {
  description = "CIDR block for the first public subnet"
  default     = "10.0.1.0/24"
}

variable "public_subnet_cidr_2" {
  description = "CIDR block for the second public subnet"
  default     = "10.0.2.0/24"
}

variable "private_subnet_cidr_1" {
  description = "CIDR block for the first private subnet"
  default     = "10.0.101.0/24"
}

variable "private_subnet_cidr_2" {
  description = "CIDR block for the second private subnet"
  default     = "10.0.102.0/24"
}

variable "security_group_name" {
  description = "Name of the security group for the RDS cluster"
  default     = "rds-cluster-sg"
}

variable "secret_name" {
  description = "Name of the AWS Secrets Manager secret"
  default     = "rds-credentials"
}

variable "secret_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "secret_password" {
  description = "Password for the database"
  default     = "securepassword123"
}

variable "iam_role_name" {
  description = "Name of the IAM role for the RDS cluster"
  default     = "rds-cluster-iam-role"
}

variable "iam_role_description" {
  description = "Description for the IAM role"
  default     = "Role for RDS cluster to access Secrets Manager"
}

variable "proxy_idle_timeout" {
  description = "Idle client timeout for the proxy in seconds"
  default     = 1800
}

variable "proxy_debug_logging" {
  description = "Enable debug logging for the proxy"
  default     = false
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_1
  map_public_ip_on_launch = true
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_2
  map_public_ip_on_launch = true
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_1
  map_public_ip_on_launch = false
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_2
  map_public_ip_on_launch = false
  availability_zone = "us-east-1b"
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_subnet_1_assoc" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table_association" "public_subnet_2_assoc" {
  subnet_id      = aws_subnet.public_subnet_2.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_security_group" "rds_sg" {
  name        = var.security_group_name
  description = "Security group for RDS cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_iam_role" {
  name               = var.iam_role_name
  description        = var.iam_role_description
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_secretsmanager" {
  role       = aws_iam_role.rds_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSecretsManagerReadOnlyAccess"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name = var.secret_name
}

resource "aws_secretsmanager_secret_version" "db_credentials_version" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  name      = "db_credentials"
  secret_string = jsonencode({
    username = var.secret_username
    password = var.secret_password
  })
}

resource "aws_rds_cluster" "aurora_cluster" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  engine_version          = "5.7.mysql_aurora.2.06"
  database_name           = "mydb"
  master_username         = var.secret_username
  master_password         = var.secret_password
  backup_retention_period = 7
  preferred_backup_window = "07:00-08:00"
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  iam_role_arn           = aws_iam_role.rds_iam_role.arn
  storage_type           = "gp2"
  storage_encrypted      = true
  skip_final_snapshot    = true
}

resource "aws_rds_cluster_proxy" "proxy" {
  cluster_arn = aws_rds_cluster.aurora_cluster.arn
  name        = "aurora-proxy"
  idle_client_timeout = var.proxy_idle_timeout
  debug_logging        = var.proxy_debug_logging
}
```

