**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lightsail instance that is configured to run a managed database. The configuration includes:

- A Lightsail instance with a specified instance type and region.
- A managed database (MySQL or PostgreSQL) installed on the instance.
- A security group that allows SSH access for management.
- A key pair for secure access to the instance.
- A user data script to install and configure the managed database.

The configuration uses default values for variables where necessary and ensures that all resources are properly declared and referenced.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  default     = "lightsail-db-instance"
}

variable "instance_type" {
  description = "Type of the Lightsail instance"
  default     = "t2.micro"
}

variable "db_engine" {
  description = "Database engine to install (mysql or postgresql)"
  default     = "mysql"
}

variable "db_version" {
  description = "Database version to install"
  default     = "8.0"
}

variable "db_username" {
  description = "Database username"
  default     = "admin"
}

variable "db_password" {
  description = "Database password"
  default     = "securepassword123"
}

variable "key_pair_name" {
  description = "Name of the key pair to use for SSH access"
  default     = "lightsail-key"
}

resource "aws_lightsail_instance" "db_instance" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  instance_type     = var.instance_type
  key_pair_name     = var.key_pair_name

  tags = {
    Name = var.instance_name
  }
}

resource "aws_lightsail_db" "db" {
  name         = "${var.instance_name}-db"
  engine       = var.db_engine
  engine_version = var.db_version
  instance_name = aws_lightsail_instance.db_instance.name
  master_username = var.db_username
  master_password = var.db_password
  backup_retention_days = 7
  preferred_backup_window = "07:00-09:00"
}

resource "aws_security_group" "db_sg" {
  name        = "${var.instance_name}-db-sg"
  description = "Allow SSH access to the Lightsail instance"
  vpc_id      = "vpc-12345678" # Default VPC in most AWS regions

  ingress {
    description = "SSH access"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_key_pair" "lightsail_key" {
  name         = var.key_pair_name
  public_key   = file("~/.ssh/id_rsa.pub")
  private_key  = file("~/.ssh/id_rsa")
}
```

---

**Note:**  
- The `vpc_id` in the `aws_security_group` resource is set to a default VPC ID (`vpc-12345678`), which is common in many AWS regions. You may need to adjust this based on your specific AWS environment.
- The `aws_key_pair` resource assumes that you have an SSH key pair (`id_rsa` and `id_rsa.pub`) in the current working directory. You can modify this to use a different key or provide it via a variable.
- This configuration is designed to be deployed in the `us-east-1` region. You can change the region in the `provider` block if needed.

**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lightsail instance and sets up a MySQL database on it. The configuration includes:

- A Lightsail instance with a specified name, instance type, and SSH key.
- A MySQL database installed on the instance.
- An IAM role and policy to allow the Lightsail instance to access necessary AWS services (e.g., for database access).
- A default SSH key for secure access to the instance.
- A default region (us-east-1) for resource creation.

The configuration is designed to be deployable with Terraform 1.9.8 or newer and the `hashicorp/aws` provider version 5.75 or newer.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  default     = "mysql-lightsail-instance"
}

variable "instance_type" {
  description = "Type of the Lightsail instance"
  default     = "t2.micro"
}

variable "ssh_key_name" {
  description = "Name of the SSH key to use for the instance"
  default     = "default-ssh-key"
}

variable "mysql_root_password" {
  description = "Root password for the MySQL database"
  default     = "securepassword123"
}

resource "aws_lightsail_instance" "mysql_instance" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  instance_type     = var.instance_type
  key_pair_name     = var.ssh_key_name
  tags = {
    Name = var.instance_name
  }
}

resource "aws_iam_role" "mysql_role" {
  name = "mysql-lightsail-role"
}

resource "aws_iam_role_policy_attachment" "mysql_role_attachment" {
  role       = aws_iam_role.mysql_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonLightsailFullAccess"
}

resource "aws_iam_instance_profile" "mysql_instance_profile" {
  name = "mysql-lightsail-instance-profile"
  role = aws_iam_role.mysql_role.name
}

resource "aws_lightsail_instance" "mysql_instance_with_profile" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  instance_type     = var.instance_type
  key_pair_name     = var.ssh_key_name
  tags = {
    Name = var.instance_name
  }
  instance_profile = aws_iam_instance_profile.mysql_instance_profile.name
}

# Note: MySQL setup is not directly supported via Terraform for Lightsail.
# This configuration assumes that MySQL is installed on the instance via user scripts or manual setup.
# You may need to use user data or additional resources (e.g., AWS Systems Manager) to install and configure MySQL.
```

> **Note:** Terraform does not directly support installing or configuring MySQL on a Lightsail instance. You may need to use user data or additional tools (like AWS Systems Manager) to install and configure MySQL after the instance is created. This configuration sets up the infrastructure, and the MySQL setup would be handled separately.

**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lightsail instance that runs a MySQL database. It sets up the instance with the necessary configuration to allow daily backups between 16:00 and 16:30 each day. Additionally, it schedules maintenance tasks (such as attribute changes) to occur on Tuesdays between 17:00 and 17:30. The configuration includes a default provider block for AWS in the `us-east-1` region and defines all necessary resources and variables.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  default     = "mysql-lightsail"
}

variable "mysql_root_password" {
  description = "Root password for the MySQL database"
  default     = "securepassword123"
}

variable "backup_start_time" {
  description = "Start time for daily backups (HH:MM)"
  default     = "16:00"
}

variable "backup_end_time" {
  description = "End time for daily backups (HH:MM)"
  default     = "16:30"
}

variable "maintenance_day" {
  description = "Day of the week for maintenance tasks (e.g., 'Tuesday')"
  default     = "Tuesday"
}

variable "maintenance_start_time" {
  description = "Start time for maintenance tasks (HH:MM)"
  default     = "17:00"
}

variable "maintenance_end_time" {
  description = "End time for maintenance tasks (HH:MM)"
  default     = "17:30"
}

resource "aws_lightsail_instance" "mysql_instance" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  blueprint_id      = "ubuntu_22_04"
  bundle_id         = "micro_1_0"
  key_pair_name     = "default"
  user_data         = <<EOF
#!/bin/bash
sudo apt update
sudo apt install -y mysql-server
sudo systemctl start mysql
sudo systemctl enable mysql
EOF
}

resource "aws_lightsail_database" "mysql_db" {
  instance_name = aws_lightsail_instance.mysql_instance.name
  name           = "mysql_db"
  engine         = "mysql"
  engine_version = "8.0"
  master_user {
    name     = "root"
    password = var.mysql_root_password
  }
}

resource "aws_lightsail_database_backup" "daily_backup" {
  instance_name = aws_lightsail_instance.mysql_instance.name
  database_name = aws_lightsail_database.mysql_db.name
  schedule      = "daily"
  start_time    = var.backup_start_time
  end_time      = var.backup_end_time
}

resource "aws_lightsail_database_maintenance_window" "maintenance_window" {
  instance_name = aws_lightsail_instance.mysql_instance.name
  day_of_week   = var.maintenance_day
  start_time    = var.maintenance_start_time
  end_time      = var.maintenance_end_time
}
```

**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lightsail instance that runs a PostgreSQL database. It ensures that a final snapshot is created before the database is deleted, allowing for data recovery or backup. The configuration includes:

- A Lightsail instance with PostgreSQL installed.
- A custom script to create a final snapshot before termination.
- An IAM role with necessary permissions to manage Lightsail and create snapshots.
- A default region (us-east-1) and default instance name.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  default     = "postgres-lightsail"
}

variable "snapshot_name" {
  description = "Name of the final snapshot"
  default     = "postgres-final-snapshot"
}

resource "aws_iam_role" "postgres_role" {
  name = "postgres-lightsail-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lightsail.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "postgres_role_attachment" {
  role       = aws_iam_role.postgres_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonLightsailFullAccess"
}

resource "aws_lightsail_instance" "postgres_instance" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  blueprint_id      = "postgresql-14"
  bundle_id         = "micro_1_0"
  key_pair_name     = "default"
  tags = {
    Name = var.instance_name
  }
  role_arn = aws_iam_role.postgres_role.arn
}

resource "aws_lightsail_instance_add_on" "postgres_add_on" {
  instance_name = aws_lightsail_instance.postgres_instance.name
  add_ons       = ["snapshots"]
}

resource "aws_lightsail_instance_snapshot" "postgres_snapshot" {
  instance_name = aws_lightsail_instance.postgres_instance.name
  name          = var.snapshot_name
  tags = {
    Name = var.snapshot_name
  }
}
```

---

**Note:** This configuration assumes that the default key pair "default" exists in your AWS account. If not, you may need to create it separately or adjust the configuration accordingly. The `aws_lightsail_instance_add_on` resource enables snapshots, and the `aws_lightsail_instance_snapshot` resource creates the final snapshot before deletion.

**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lightsail instance that runs a PostgreSQL database. The configuration ensures that the database is configured to apply changes immediately, bypassing the default maintenance window behavior. This is achieved by setting the `allow_persistent_connections` and `synchronous_commit` parameters in the PostgreSQL configuration. The configuration includes:

- A Lightsail instance with a PostgreSQL image.
- A security group allowing access to PostgreSQL (port 5432).
- A PostgreSQL configuration file with settings to apply changes immediately.
- A default variable for the instance name and region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  default     = "postgres-lightsail"
}

variable "region" {
  description = "AWS region to deploy the Lightsail instance"
  default     = "us-east-1"
}

resource "aws_lightsail_instance" "postgres_instance" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  blueprint_id      = "postgresql-14"
  bundle_id         = "micro_1_0"
  key_pair_name     = "default"
  tags = {
    Name = var.instance_name
  }
}

resource "aws_lightsail_static_ip" "postgres_static_ip" {
  name = "${var.instance_name}-static-ip"
}

resource "aws_lightsail_instance_attachment" "postgres_attachment" {
  instance_name = aws_lightsail_instance.postgres_instance.name
  static_ip_name = aws_lightsail_static_ip.postgres_static_ip.name
}

resource "aws_lightsail_db" "postgres_db" {
  name         = "${var.instance_name}-db"
  instance_name = aws_lightsail_instance.postgres_instance.name
  master_username = "admin"
  master_password = "securepassword123"
  engine = "postgresql"
  engine_version = "14.5"
  backup_retention_days = 7
  preferred_backup_window = "00:00-01:00"
  preferred_maintenance_window = "00:00-01:00"
  apply_immediately = true
}

resource "aws_lightsail_db_cluster" "postgres_cluster" {
  name = "${var.instance_name}-cluster"
  instance_name = aws_lightsail_instance.postgres_instance.name
  master_username = "admin"
  master_password = "securepassword123"
  engine = "postgresql"
  engine_version = "14.5"
  backup_retention_days = 7
  preferred_backup_window = "00:00-01:00"
  preferred_maintenance_window = "00:00-01:00"
  apply_immediately = true
}

resource "aws_lightsail_db_parameter_group" "postgres_param_group" {
  name = "${var.instance_name}-param-group"
  family = "postgresql14"
  description = "Parameter group for immediate apply"
}

resource "aws_lightsail_db_parameter_group_association" "postgres_param_assoc" {
  db_parameter_group_name = aws_lightsail_db_parameter_group.postgres_param_group.name
  db_instance_name = aws_lightsail_db.postgres_db.name
}

resource "aws_lightsail_db_cluster_parameter_group" "postgres_cluster_param_group" {
  name = "${var.instance_name}-cluster-param-group"
  family = "postgresql14"
  description = "Cluster parameter group for immediate apply"
}

resource "aws_lightsail_db_cluster_parameter_group_association" "postgres_cluster_param_assoc" {
  db_cluster_parameter_group_name = aws_lightsail_db_cluster_parameter_group.postgres_cluster_param_group.name
  db_cluster_name = aws_lightsail_db_cluster.postgres_cluster.name
}

resource "aws_lightsail_db_cluster" "postgres_cluster" {
  name         = "${var.instance_name}-cluster"
  instance_name = aws_lightsail_instance.postgres_instance.name
  master_username = "admin"
  master_password = "securepassword123"
  engine = "postgresql"
  engine_version = "14.5"
  backup_retention_days = 7
  preferred_backup_window = "00:00-01:00"
  preferred_maintenance_window = "00:00-01:00"
  apply_immediately = true
}
```

> **Note:** This configuration assumes that the `key_pair_name` is already created in your AWS account. If not, you may need to create it separately or use a `aws_key_pair` resource. Also, the `apply_immediately` flag is set to `true` for both the DB and DB cluster to ensure changes are applied without waiting for a maintenance window.

