**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lightsail instance with multiple attached disks. The configuration includes:

- A Lightsail instance with a specified name, instance type, and region.
- Multiple Lightsail disks (e.g., 20GB and 50GB) created and attached to the instance.
- The disks are configured with a name, size, and type.
- The configuration uses default values for variables where applicable, ensuring the configuration is deployable without additional input.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  default     = "my-lightsail-instance"
}

variable "disk_names" {
  description = "List of names for the disks to be created"
  default     = ["data-disk-1", "data-disk-2"]
}

variable "disk_sizes" {
  description = "List of sizes for the disks in GB"
  default     = [20, 50]
}

variable "disk_types" {
  description = "List of disk types (e.g., 'standard', 'gp2')"
  default     = ["standard", "gp2"]
}

resource "aws_lightsail_instance" "example" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  blueprint_id      = "ubuntu_22_04"
  bundle_id         = "micro_1_0"
  key_pair_name     = "my-key-pair" # Ensure this key pair exists in your AWS account
}

resource "aws_lightsail_disk" "data_disks" {
  count             = length(var.disk_names)
  name              = var.disk_names[count.index]
  size_in_gb        = var.disk_sizes[count.index]
  type              = var.disk_types[count.index]
  availability_zone = "us-east-1a"
}

resource "aws_lightsail_disk_attachment" "disk_attachments" {
  count             = length(var.disk_names)
  instance_name     = var.instance_name
  disk_name         = var.disk_names[count.index]
  is_primary        = false
}
```

