**Description:**

This Terraform configuration creates an AWS Lightsail instance and grants it access to an S3 bucket. It includes:

- A Lightsail instance with a specified name and region.
- An S3 bucket with a unique name.
- An IAM role for the Lightsail instance to assume.
- A policy that allows the Lightsail instance to access the S3 bucket.
- A resource policy that grants the Lightsail instance access to the bucket.

All resources are defined with default values for variables, and the configuration is deployable with Terraform 1.9.8 and hashicorp/aws 5.75.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "lightsail_instance_name" {
  description = "Name of the Lightsail instance"
  default     = "lightsail-instance"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket"
  default     = "lightsail-bucket-${random.uuid.bucket_id_suffix}-"
}

variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

resource "aws_s3_bucket" "bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  tags = {
    Name = "lightsail-bucket"
  }
}

resource "aws_iam_role" "lightsail_role" {
  name = "lightsail-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "lightsail.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "lightsail_policy" {
  name = "lightsail-iam-policy"
  role = aws_iam_role.lightsail_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:ListBucket"
      ]
      Resource = [
        "${aws_s3_bucket.bucket.arn}",
        "${aws_s3_bucket.bucket.arn}/*"
      ]
    }]
  })
}

resource "aws_s3_bucket_policy" "bucket_policy" {
  bucket = aws_s3_bucket.bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${aws_iam_role.lightsail_role.name}"
      }
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:ListBucket"
      ]
      Resource = [
        "${aws_s3_bucket.bucket.arn}",
        "${aws_s3_bucket.bucket.arn}/*"
      ]
    }]
  })
}

data "aws_caller_identity" "current" {}
```

