- A default AWS provider configured in the `us-east-1` region.
- An S3 bucket to serve as the origin for the distribution.
- An IAM role and policy to allow the Lightsail Distribution to access the S3 bucket.
- A Lightsail Distribution resource that is configured to use the S3 bucket as its origin.
- All necessary variables are defined with default values for easy deployment.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to use as the origin."
  default     = "my-lightsail-origin-bucket"
}

variable "distribution_name" {
  description = "The name of the Lightsail Distribution."
  default     = "my-lightsail-distribution"
}

resource "aws_s3_bucket" "origin_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  lifecycle_rule {
    id      = "EnableVersioning"
    enabled = true
  }

  versioning {
    enabled = true
  }
}

resource "aws_iam_role" "s3_access_role" {
  name = "s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lightsail.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "s3_access_policy" {
  name = "s3-access-policy"
  role = aws_iam_role.s3_access_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:ListBucket",
        "s3:PutObject",
      ]
      Resource = [
        "${aws_s3_bucket.origin_bucket.arn}",
        "${aws_s3_bucket.origin_bucket.arn}/*",
      ]
    }]
  })
}

resource "aws_lightsail_distribution" "distribution" {
  name              = var.distribution_name
  origin            = "s3://${var.bucket_name}"
  enable_http2     = true
  enable_compression = true
  http_port         = 80
  https_port        = 443
  protocol = "https"
  protocol_version = "http2"
  tags = {
    Terraform = "true"
  }
}
```

