**Description of the Terraform Program:**

This Terraform configuration creates an AWS Lightsail Distribution with a Lightsail instance as the origin. The configuration includes:

- A Lightsail instance running a web server (e.g., Nginx).
- A Lightsail Distribution that uses the instance as the origin.
- A domain name (optional) associated with the distribution.
- A valid AWS provider configuration in the `us-east-1` region.
- IAM roles and policies as needed for Lightsail access.

Variables are defined with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_name" {
  description = "Name of the Lightsail instance"
  default     = "my-lightsail-instance"
}

variable "distribution_name" {
  description = "Name of the Lightsail distribution"
  default     = "my-lightsail-distribution"
}

variable "domain_name" {
  description = "Domain name to associate with the distribution (optional)"
  default     = ""
}

variable "instance_username" {
  description = "Username for SSH access to the instance"
  default     = "ubuntu"
}

variable "instance_ssh_key_name" {
  description = "SSH key name for the instance"
  default     = "my-ssh-key"
}

variable "instance_image_name" {
  description = "Lightsail image name for the instance"
  default     = "ubuntu-22-04"
}

variable "instance_plan" {
  description = "Lightsail instance plan (e.g., micro, small, etc.)"
  default     = "micro"
}

variable "distribution_origin" {
  description = "Origin for the distribution (must be a Lightsail instance)"
  default     = "lightsail-1234567890abcdef0"
}

variable "distribution_region" {
  description = "Region for the distribution"
  default     = "us-east-1"
}

resource "aws_lightsail_instance" "example" {
  name              = var.instance_name
  availability_zone = "us-east-1a"
  blueprint_id      = "ubuntu_22_04"
  bundle_id         = var.instance_plan
  key_pair_name     = var.instance_ssh_key_name
  user_data         = "sudo apt update && sudo apt install -y nginx"
}

resource "aws_lightsail_distribution" "example" {
  name             = var.distribution_name
  origin            = var.distribution_origin
  origin_region     = var.distribution_region
  enable_http2      = true
  enable_compression = true
  tags = {
    Name = "lightsail-distribution"
  }
}

resource "aws_route53_record" "example" {
  if var.domain_name != "" {
    name    = var.domain_name
    type    = "A"
    zone_id = aws_route53_zone.example.zone_id
    records = [aws_lightsail_distribution.example.domain_name]
  }
}

resource "aws_route53_zone" "example" {
  name = "example.com"
}
```

**Note:** This configuration assumes you have an existing SSH key pair named `my-ssh-key` in your AWS account. If you need to create the key pair, you can use the `aws_key_pair` resource. Also, the `distribution_origin` should be the ARN of a valid Lightsail instance. You can retrieve the ARN using the AWS CLI or the AWS Console.

