**Description:**

This Terraform configuration creates an Amazon S3 Glacier vault and sets up a notification configuration to trigger actions (such as sending an SNS message) when specific events occur in the vault. The configuration includes:

- An AWS provider configured in the `us-east-1` region.
- An S3 Glacier vault.
- A notification configuration for the vault that specifies the event type (e.g., `archive-retrieval-complete` or `inventory-retrieval-complete`) and the destination (e.g., an SNS topic).
- An IAM role and policy to allow the S3 Glacier vault to send notifications to the SNS topic.

Variables are provided with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  description = "Name of the S3 Glacier vault"
  default     = "my-glacier-vault"
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic to receive notifications"
  default     = "arn:aws:sns:us-east-1:123456789012:my-sns-topic"
}

variable "notification_event" {
  description = "Type of event to trigger notification (e.g., archive-retrieval-complete)"
  default     = "archive-retrieval-complete"
}

resource "aws_s3 glacier_vault" "glacier_vault" {
  vault_name = var.vault_name
}

resource "aws_s3_bucket_notification" "glacier_notification" {
  bucket = aws_s3_glacier_vault.glacier_vault.id

  lambda_function {
    lambda_arn = "arn:aws:lambda:us-east-1:123456789012:function:my-lambda"
    events     = ["s3:PutObject"]
  }

  topic {
    topic_arn = var.sns_topic_arn
    events    = [var.notification_event]
  }
}

resource "aws_iam_role" "sns_role" {
  name = "sns_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "sns_policy" {
  name = "sns_policy"
  role = aws_iam_role.sns_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "sns:Publish",
        "sns:GetTopicAttributes"
      ]
      Resource = "*"
    }]
  })
}
```

---

**Note:** This configuration assumes that the SNS topic already exists and that the IAM role and policy are properly set up for the S3 Glacier vault to publish to the SNS topic. You may need to adjust the `sns_topic_arn` and `lambda_arn` based on your actual AWS environment.

