**Description:**

This Terraform configuration creates an AWS S3 Glacier Vault and integrates it with an AWS S3 Event Notification that triggers an AWS SNS topic. The SNS topic is set up to allow notifications to be sent to an email address. The configuration includes:

- An AWS S3 Glacier Vault
- An AWS SNS Topic
- An IAM Role for the SNS Topic to allow email delivery
- An S3 Event Notification that triggers the SNS Topic when objects are archived in the Glacier Vault

All resources are created in the `us-east-1` region. Default values are provided for variables such as the SNS topic name, email address, and Glacier vault name.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "glacier_vault_name" {
  description = "Name of the S3 Glacier Vault"
  default     = "my-glacier-vault"
}

variable "sns_topic_name" {
  description = "Name of the SNS Topic"
  default     = "glacier-archival-notification"
}

variable "sns_email_address" {
  description = "Email address to receive notifications"
  default     = "notifications@example.com"
}

resource "aws_s3_bucket" "glacier_vault" {
  bucket = var.glacier_vault_name
  force_destroy = true
}

resource "aws_s3_bucket_notification" "glacier_notification" {
  bucket = aws_s3_bucket.glacier_vault.id

  topic {
    topic_arn = aws_sns_topic.glacier_sns.arn
    events    = ["s3:ArchiveRetrieval", "s3:ArchiveRetrievalCompleted"]
  }
}

resource "aws_sns_topic" "glacier_sns" {
  name = var.sns_topic_name
}

resource "aws_iam_role" "sns_email_role" {
  name = "sns-email-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "sns.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "sns_email_policy" {
  name = "sns-email-policy"
  role = aws_iam_role.sns_email_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "sns:Publish",
        "sns:SetSubscriptionAttributes"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_sns_topic_subscription" "sns_email_subscription" {
  topic_arn         = aws_sns_topic.glacier_sns.arn
  protocol          = "email"
  endpoint          = var.sns_email_address
  raw_message_delivery = false
  region            = "us-east-1"
}
```

