This Terraform configuration creates an Amazon S3 Glacier vault and applies a basic access policy to it. The policy allows full access to the vault for the AWS account owner. The configuration uses the `aws_glacier_vault` resource and the `aws_iam_policy` and `aws_iam_policy_attachment` resources to define and attach the access policy. The AWS provider is configured with a default region (us-east-1), and all necessary resources are declared explicitly.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  description = "Name of the S3 Glacier vault"
  default     = "my-glacier-vault"
}

variable "policy_name" {
  description = "Name of the IAM policy"
  default     = "GlacierVaultAccessPolicy"
}

resource "aws_glacier_vault" "glacier_vault" {
  vault_name = var.vault_name
}

resource "aws_iam_policy" "glacier_policy" {
  name        = var.policy_name
  description = "Allows full access to the Glacier vault"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = { AWS = "arn:aws:iam::${aws_caller_identity.current.account_id}:root" }
        Action   = [
          "glacier:DescribeVault",
          "glacier:ListVaults",
          "glacier:UploadArchive",
          "glacier:InitiateJob",
          "glacier:DescribeJob",
          "glacier:ListJobs",
          "glacier:GetJobOutput",
          "glacier:AbortJob"
        ]
        Resource = "arn:aws:glacier:${aws_region.current.name}:${aws_caller_identity.current.account_id}:vault/${var.vault_name}"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "glacier_policy_attachment" {
  name       = "${var.policy_name}-attachment"
  principals {
    type        = "AWS"
    identifiers = ["arn:aws:iam::${aws_caller_identity.current.account_id}:root"]
  }
  policies   = [aws_iam_policy.glacier_policy.name]
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}
```

---

**Note:** This configuration assumes that the AWS provider is properly authenticated via environment variables or shared credentials. You may need to configure AWS credentials separately depending on your deployment environment.

