**Description:**

This Terraform configuration creates an S3 Glacier vault and applies an IAM policy to it using the `aws_iam_policy_document` data resource. The policy is then used to lock the vault using the `aws_glacier_vault_lock` resource. The policy is configured to allow full access to the vault for a specific IAM role, ensuring that the vault is locked and cannot be modified once the lock is applied.

The configuration includes:
- A provider block for AWS in the `us-east-1` region.
- A data resource to define the IAM policy document.
- A resource to create the S3 Glacier vault.
- A resource to lock the vault using the defined policy.
- Default values for variables to ensure the configuration is self-contained and deployable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  description = "Name of the S3 Glacier vault"
  default     = "example-glacier-vault"
}

variable "iam_role_arn" {
  description = "ARN of the IAM role that will have access to the vault"
  default     = "arn:aws:iam::123456789012:role/example-role"
}

data "aws_iam_policy_document" "vault_access" {
  statement {
    actions = [
      "glacier:DescribeVault",
      "glacier:GetVaultLock",
      "glacier:InitiateVaultLock",
      "glacier:ListMultipartUploads",
      "glacier:ListParts",
      "glacier:PutVaultLock",
      "glacier:AbortMultipartUpload",
      "glacier:CompleteMultipartUpload",
      "glacier:UploadPart",
      "glacier:UploadPartCopy",
      "glacier:GetJobOutput",
      "glacier:DescribeJob",
      "glacier:InitiateJob",
      "glacier:ListJobs",
    ]

    resources = ["arn:aws:glacier:us-east-1:123456789012:vaults/${var.vault_name}"]

    principals {
      type        = "AWS"
      identifiers = [var.iam_role_arn]
    }
  }
}

resource "aws_glacier_vault" "vault" {
  vault_name = var.vault_name
}

resource "aws_glacier_vault_lock" "lock" {
  vault_name = aws_glacier_vault.vault.vault_name
  policy    = data.aws_iam_policy_document.vault_access.json
}
```

