**Description of the Terraform Program:**

This Terraform script provisions a Network Load Balancer (NLB) in AWS and attaches it to an EC2 instance running an `t2.micro` instance type. The NLB will listen on port 80 and forward traffic to the EC2 instance. The EC2 instance is configured with a public IP address and a security group that allows HTTP traffic. An IAM role is created to grant the EC2 instance the necessary permissions to launch and operate in the AWS environment.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_type" {
  description = "The type of EC2 instance to launch"
  default     = "t2.micro"
}

variable "security_group_name" {
  description = "Name of the security group to associate with the EC2 instance"
  default     = "allow-http"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the resources"
  default     = "vpc-0123456789abcdef0"
}

variable "subnet_id" {
  description = "The ID of the subnet to use for the EC2 instance"
  default     = "subnet-0123456789abcdef0"
}

variable "key_name" {
  description = "The name of the EC2 key pair to use"
  default     = "my-key-pair"
}

variable "iam_role_name" {
  description = "Name of the IAM role to assign to the EC2 instance"
  default     = "ec2-nlb-role"
}

resource "aws_security_group" "http_sg" {
  name        = var.security_group_name
  description = "Allow HTTP traffic"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "ec2_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = var.instance_type
  subnet_id     = var.subnet_id
  key_name      = var.key_name
  security_groups = [aws_security_group.http_sg.name]

  iam_instance_profile = aws_iam_role.ec2_role.name

  tags = {
    Name = "web-server"
  }
}

resource "aws_network_load_balancer" "nlb" {
  name               = "my-nlb"
  subnet_ids         = [var.subnet_id]
  idle_timeout       = 30
  access_logs {
    bucket = "my-nlb-logs"
    prefix = "logs"
  }
}

resource "aws_network_load_balancer_target" "nlb_target" {
  load_balancer_arn = aws_network_load_balancer.nlb.arn
  port              = 80
  instance_id       = aws_instance.web_server.id
}
```

---

**Note:**  
- Replace the default values for `vpc_id`, `subnet_id`, and `bucket` with your actual AWS resources.
- Ensure that the S3 bucket `my-nlb-logs` exists in the same region as your resources.
- The `ami` value is for Amazon Linux 2 in `us-east-1`. Adjust it based on your region and OS preference.

