**Description of the Terraform Program:**

This Terraform configuration creates an Application Load Balancer (ALB) in AWS. The ALB will be set up in a specified region, and it will be associated with a security group that allows HTTP and HTTPS traffic. The ALB will be configured with a default listener that forwards traffic to a target group. The target group will be created as a placeholder for future targets (e.g., EC2 instances or Lambda functions). The configuration includes necessary IAM roles and security groups to ensure the ALB can operate securely and communicate with the target group.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the ALB will be created."
  default     = "vpc-12345678"
}

variable "subnets" {
  description = "A list of subnet IDs where the ALB will be deployed."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the ALB."
  default     = "sg-12345678"
}

variable "alb_name" {
  description = "The name of the Application Load Balancer."
  default     = "my-alb"
}

resource "aws_lb" "alb" {
  name               = var.alb_name
  subnets           = var.subnets
  security_groups    = [var.security_group_id]
  idle_timeout       = 30
  enable_deletion_protection = false
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.default_target_group.arn
  }
}

resource "aws_lb_target_group" "default_target_group" {
  name        = "${var.alb_name}-target-group"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = "80"
