**Description:**

This Terraform script provisions a Network Load Balancer (NLB) in AWS. The NLB will be configured in a specified region and will have a single target group associated with it. The script includes a default region, a default VPC ID, and a default subnet ID. The NLB will be created with a single listener (TCP on port 80) and will be associated with a target group that listens on port 80. The script is designed to be deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC to associate the Network Load Balancer with."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the Network Load Balancer."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "lb_name" {
  description = "The name of the Network Load Balancer."
  default     = "my-nlb"
}

variable "target_group_name" {
  description = "The name of the target group associated with the Network Load Balancer."
  default     = "my-nlb-target-group"
}

resource "aws_network_load_balancer" "nlb" {
  name               = var.lb_name
  subnet_ids         = var.subnet_ids
  vpc_id             = var.vpc_id
  idle_timeout       = 30
  access_logs {
    enabled = false
  }
}

resource "aws_network_load_balancer_listener" "listener" {
  load_balancer_arn = aws_network_load_balancer.nlb.arn
  port              = 80
  protocol          = "tcp"

  default_action {
    type = "forward"

    forward {
      target_group_arn = aws_network_target_group.target_group.arn
    }
  }
}

resource "aws_network_target_group" "target_group" {
  name        = var.target_group_name
  port        = 80
  protocol    = "tcp"
  vpc_id      = var.vpc_id
  target_type = "instance"
}
