LLM Output #0:
**Description:**

This Terraform configuration creates an AWS Elastic Load Balancer (ELB) with an associated Elastic IP (EIP). The Load Balancer is configured as a Classic Load Balancer (CLB), which is suitable for applications that require basic load balancing capabilities. The Elastic IP is allocated and associated with the Load Balancer to provide a static public IP address.

The configuration includes:
- A VPC (Virtual Private Cloud) to host the Load Balancer.
- A subnet within the VPC to place the Load Balancer.
- An Elastic IP (EIP) allocated and associated with the Load Balancer.
- A Classic Load Balancer (CLB) with a listener and health check configuration.

Variables are provided with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "load_balancer_name" {
  description = "Name of the Load Balancer"
  default     = "my-load-balancer"
}

variable "instance_port" {
  description = "Port on the instances to listen on"
  default     = 80
}

variable "load_balancer_port" {
  description = "Port on the Load Balancer to listen on"
  default     = 80
}

variable "health_check_path" {
  description = "Path for health check"
  default     = "/health"
}

variable "health_check_interval" {
  description = "Interval (seconds) for health checks"
  default     = 30
}

variable "health_check_timeout" {
  description = "Timeout (seconds) for health checks"
  default     = 5
}

variable "health_check_unhealthy_threshold" {
  description = "Unhealthy threshold for health checks"
  default     = 3
}

variable "health_check_protocol" {
  description = "Protocol for health checks"
  default     = "HTTP"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr
  availability_zone = "us-west-2a"
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_elb" "lb" {
  name = var.load_balancer_name

  subnets = [aws_subnet.main.id]

  listener {
    instance_port     = var.instance_port
    instance_protocol = "http"
    lb_port           = var.load_balancer_port
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = var.health_check_unhealthy_threshold
    unhealthy_threshold = var.health_check_unhealthy_threshold
    interval            = var.health_check_interval
    timeout             = var.health_check_timeout
    path                = var.health_check_path
    protocol            = var.health_check_protocol
  }

  tags = {
    Name = var.load_balancer_name
  }
}

resource "aws_eip" "lb_eip" {
  vpc = true
  instance = aws_elb.lb.id
}
```

---

**Note:** This configuration uses the Classic Load Balancer (CLB), which is deprecated in favor of the Application Load Balancer (ALB) and Network Load Balancer (NLB). If you need a modern load balancer, let me know and I can provide an ALB configuration instead.

