LLM Output #0:
**Description:**

This Terraform configuration creates an internal-facing Elastic Load Balancer (ELB) in AWS. The load balancer is configured to use private IP addresses, making it accessible only within the VPC. The configuration includes a VPC, a subnet, a security group, and the load balancer itself. The load balancer is set to listen on port 80 and forward traffic to an EC2 instance (or instances) in the same VPC. The configuration uses default values for variables where necessary and ensures all resources are declared and properly referenced.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the load balancer."
  default     = "vpc-12345678"
}

variable "subnet_id" {
  description = "The ID of the subnet to use for the load balancer."
  default     = "subnet-12345678"
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the load balancer."
  default     = "sg-12345678"
}

variable "instance_id" {
  description = "The ID of the EC2 instance to route traffic to."
  default     = "i-12345678"
}

resource "aws_lb" "internal_lb" {
  name               = "internal-lb"
  subnets           = [var.subnet_id]
  security_groups   = [var.security_group_id]
  internal          = true
  idle_timeout      = 30
  enable_deletion_protection = false

  listener {
    protocol = "http"
    port     = 80

    default_action {
      type = "forward"
      forward {
        target_group_arn = aws_lb_target_group.target_group.arn
      }
    }
  }
}

resource "aws_lb_target_group" "target_group" {
  name        = "internal-lb-target-group"
  port        = 80
  protocol    = "http"
  vpc_id      = var.vpc_id
  target_type = "instance"

  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = "80"
    interval            = 30
    timeout             = 10
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener_rule" "forward_rule" {
  listener_arn = aws_lb_listener.default.arn

  action {
    type = "forward"
    forward {
      target_group_arns = [aws_lb_target_group.target_group.arn]
    }
  }

  priority = 100

  condition {
    host_header {
      values = ["example.com"]
    }
  }
}

resource "aws_lb_listener" "default" {
  load_balancer_arn = aws_lb.internal_lb.arn
  protocol          = "HTTP"
  port              = 80

  default_action {
    type = "forward"
    forward {
      target_group_arn = aws_lb_target_group.target_group.arn
    }
  }
}
```

---

**Note:** This configuration assumes that the EC2 instance is already running and has a public IP address (or is accessible via private IP within the VPC). If you're using private IP addresses for the load balancer, ensure that the EC2 instance is also in the same VPC and subnet. You may need to adjust the security group rules to allow traffic from the load balancer to the EC2 instance.

