LLM Output #0:
**Description of the Terraform Program:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances grouped in a target group. The configuration includes:

- A VPC with a public subnet.
- A security group allowing HTTP traffic.
- A target group for EC2 instances.
- An Application Load Balancer (ALB) with a listener that forwards traffic to the target group.
- An EC2 instance (or multiple instances) that are registered with the target group.
- IAM roles and policies for the EC2 instances to allow them to communicate with the ALB and other services.

The configuration uses default values for variables where necessary and is deployable in AWS using Terraform 1.9.8 or later.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "instance_type" {
  description = "Type of EC2 instance to launch"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instance"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (us-west-2)
}

variable "security_group_name" {
  description = "Name of the security group for the ALB"
  default     = "alb-allow-http"
}

variable "target_group_name" {
  description = "Name of the target group"
  default     = "http-target-group"
}

variable "load_balancer_name" {
  description = "Name of the load balancer"
  default     = "my-alb"
}

variable "instance_count" {
  description = "Number of EC2 instances to launch"
  default     = 2
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "alb_sg" {
  name        = var.security_group_name
  description = "Allow HTTP traffic to ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_target_group" "http_target" {
  name        = var.target_group_name
  port        = 80
  protocol    = "http"
  vpc_id      = aws_vpc.main.id
  health_check {
    path                = "/health"
    protocol            = "HTTP"
    port                = "80"
    interval_seconds    = 30
    timeout_seconds     = 10
    healthy_threshold   = 3
    unhealthy_threshold = 5
  }
}

resource "aws_lb" "alb" {
  name               = var.load_balancer_name
  subnets           = [aws_subnet.public.id]
  security_groups    = [aws_security_group.alb_sg.id]
  idle_timeout       = 30
  enable_deletion_protection = false
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.http_target.arn
  }
}

resource "aws_instance" "web_server" {
  count             = var.instance_count
  ami              = var.ami_id
  instance_type    = var.instance_type
  subnet_id        = aws_subnet.public.id
  vpc_id           = aws_vpc.main.id
  security_groups  = [aws_security_group.alb_sg.id]

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y httpd
    sudo systemctl start httpd
    sudo systemctl enable httpd
    echo "Hello from instance ${count.index + 1}" > /var/www/html/index.html
  EOF

  tags = {
    Name = "web-server-${count.index + 1}"
  }
}

resource "aws_lb_target_group_attachment" "target_attachment" {
  count             = var.instance_count
  target_group_arn = aws_lb_target_group.http_target.arn
  target_id         = aws_instance.web_server[count.index].id
  port              = 80
}
```

