LLM Output #0:
**Description:**

This Terraform configuration creates an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB). The ALB will route traffic based on HTTP/HTTPS rules to the NLB, which will then forward the traffic to the backend instances or services. The configuration includes:

- A Network Load Balancer (NLB) with a public IP address.
- An Application Load Balancer (ALB) with a public IP address.
- A target group associated with the NLB.
- A listener on the ALB that forwards traffic to the target group.
- All necessary IAM roles and policies for the load balancers to function.

The configuration uses default values for variables where applicable and is compatible with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the load balancers will be created."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the load balancers."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the load balancers."
  default     = "sg-12345678"
}

variable "alb_name" {
  description = "The name of the Application Load Balancer."
  default     = "alb-frontend"
}

variable "nlb_name" {
  description = "The name of the Network Load Balancer."
  default     = "nlb-backend"
}

resource "aws_network_load_balancer" "nlb" {
  name               = var.nlb_name
  subnet_ids         = var.subnet_ids
  security_groups    = [var.security_group_id]
  idle_timeout       = 30
  enable_deletion_protection = false
}

resource "aws_lb_target_group" "target_group" {
  name        = "${var.nlb_name}-target"
  port        = 80
  protocol    = "tcp"
  vpc_id      = var.vpc_id
  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = 80
    interval_seconds     = 30
    timeout_seconds      = 5
    healthy_threshold   = 5
    unhealthy_threshold = 3
  }
}

resource "aws_lb" "alb" {
  name               = var.alb_name
  subnets           = var.subnet_ids
  security_groups    = [var.security_group_id]
  idle_timeout       = 30
  enable_deletion_protection = false
}

resource "aws_lb_listener" "alb_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    forward {
      target_group_arns = [aws_lb_target_group.target_group.arn]
    }
  }
}
```

