**Description:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with a redirect action. The load balancer will listen on HTTP port 80 and redirect all traffic to HTTPS on port 443. The configuration includes a default listener rule that performs the redirect. The load balancer is deployed in the `us-east-1` region, and the necessary IAM roles and resources are defined to ensure the load balancer can be created and managed.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC where the load balancer will be created."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the load balancer."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the load balancer."
  default     = "sg-12345678"
}

resource "aws_lb" "redirect_alb" {
  name               = "redirect-alb"
  subnets           = var.subnet_ids
  security_groups    = [var.security_group_id]
  idle_timeout       = 60
  enable_deletion_protection = false
}

resource "aws_lb_listener" "http_redirect" {
  load_balancer_arn = aws_lb.redirect_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      redirect_type = "permanent"
      port          = "443"
      protocol      = "HTTPS"
      replace_uri   = false
    }
  }
}
```

---

**Note:**  
- This configuration assumes that the VPC, subnets, and security group already exist.  
- The `aws_lb` resource creates the load balancer, and the `aws_lb_listener` resource defines the redirect action.  
- You can customize the `vpc_id`, `subnet_ids`, and `security_group_id` using the provided variables.

