LLM Output #0:
**Description:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with a fixed-response action. The load balancer will listen on HTTP port 80 and respond with a fixed HTTP response (e.g., "Hello from Terraform") when it receives traffic. The configuration includes a default security group, a target group, and the necessary IAM roles and policies for the load balancer to function.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "load_balancer_name" {
  description = "Name of the Application Load Balancer"
  default     = "tf-alb-fixed-response"
}

variable "vpc_id" {
  description = "ID of the VPC where the load balancer will be created"
  default     = "vpc-12345678"
}

variable "security_group_id" {
  description = "ID of the security group to associate with the load balancer"
  default     = "sg-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the load balancer"
  default     = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_lb" "fixed_response_alb" {
  name               = var.load_balancer_name
  subnets           = var.subnet_ids
  security_groups    = [var.security_group_id]
  idle_timeout       = 30
  enable_deletion_protection = false
}

resource "aws_lb_listener" "fixed_response_listener" {
  load_balancer_arn = aws_lb.fixed_response_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Hello from Terraform"
      status_code  = "200"
    }
  }
}

resource "aws_lb_target_group" "fixed_response_target_group" {
  name        = "${var.load_balancer_name}-target-group"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = "80"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 3
  }
}

resource "aws_iam_role" "alb_role" {
  name = "alb_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticloadbalancing.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "alb_role_policy" {
  role       = aws_iam_role.alb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonELBFullAccess"
}
```

---

**Notes:**

- This configuration assumes you have a VPC and subnets already created.
- The `security_group_id` is set to a default value, which you should replace with an actual security group ID in your environment.
- The `aws_iam_role` and `aws_iam_role_policy_attachment` ensure the load balancer has the necessary permissions to operate.
- The `aws_lb_target_group` is created but not associated with any targets. You can add targets later if needed.

