**Description:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with an action to authenticate users using AWS Cognito. The configuration includes:

- A VPC with a public subnet.
- A security group allowing HTTP traffic.
- A target group for the ALB.
- An ALB with a listener that uses the "authenticate-cognito" action.
- An IAM role for the ALB to allow it to authenticate users via Cognito.
- Default variables for region, VPC CIDR, and Cognito user pool details.

The configuration is designed to be deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "cognito_user_pool_id" {
  description = "AWS Cognito User Pool ID"
  default     = "us-east-1_123456789"
}

variable "cognito_client_id" {
  description = "AWS Cognito Client ID"
  default     = "abcdef1234567890"
}

variable "cognito_domain" {
  description = "Cognito domain for authentication"
  default     = "my-cognito-domain.auth.us-east-1.amazoncognito.com"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Allow HTTP traffic for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "alb_auth_role" {
  name = "alb-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "elasticloadbalancing.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "alb_auth_policy" {
  role       = aws_iam_role.alb_auth_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonCognitoPowerUser"
}

resource "aws_lb" "alb" {
  name               = "my-alb"
  subnets           = [aws_subnet.public.id]
  security_groups   = [aws_security_group.alb.id]
  idle_timeout      = 60
  enable_deletion_protection = false
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "http"

  default_action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn = "arn:aws:cognito-idp:${var.region}:123456789012:userpool/${var.cognito_user_pool_id}"
      user_pool_client_id = var.cognito_client_id
      user_pool_domain = var.cognito_domain
    }
  }
}
```

