**Description:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with an OIDC authentication action. The ALB will be associated with a target group that points to an EC2 instance. The OIDC authentication action will be configured to authenticate incoming requests using an OpenID Connect (OIDC) provider. The configuration includes:

- An AWS provider configured in the `us-east-1` region.
- A VPC and subnet for the ALB.
- A security group to allow traffic to the ALB.
- An EC2 instance as a target for the ALB.
- A target group for the ALB.
- An Application Load Balancer (ALB) with an OIDC authentication action.
- An IAM OIDC provider and role for authentication.

Variables are provided with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the ALB."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the ALB."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to use for the ALB."
  default     = "sg-12345678"
}

variable "instance_id" {
  description = "The ID of the EC2 instance to use as a target."
  default     = "i-12345678"
}

variable "oidc_provider_arn" {
  description = "The ARN of the OIDC provider to use for authentication."
  default     = "arn:aws:iam::123456789012:oidc-provider/example.com"
}

variable "oidc_role_arn" {
  description = "The ARN of the IAM role to use for authentication."
  default     = "arn:aws:iam::123456789012:role/oidc-role"
}

resource "aws_vpc" "example" {
  id           = var.vpc_id
  cidr_block   = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "example" {
  count        = length(var.subnet_ids) > 0 ? length(var.subnet_ids) : 0
  id           = var.subnet_ids[count.index]
  vpc_id       = aws_vpc.example.id
  cidr_block   = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "alb_sg" {
  id          = var.security_group_id
  vpc_id      = aws_vpc.example.id
  description = "Security group for ALB"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "target" {
  id          = var.instance_id
  instance_type = "t2.micro"
  ami         = "ami-0c55b159cbfafe1f0"
  vpc_security_group_ids = [aws_security_group.alb_sg.id]
  subnet_id   = aws_subnet.example[0].id
  key_name    = "my-key-pair"
  tags = {
    Name = "alb-target"
  }
}

resource "aws_lb_target_group" "example" {
  name        = "alb-target-group"
  port        = 80
  protocol    = "http"
  vpc_id      = aws_vpc.example.id
  health_check {
    path          = "/health"
    protocol      = "HTTP"
    port          = "80"
    interval      = 30
    timeout       = 10
    healthy_threshold = 5
    unhealthy_threshold = 3
  }
}

resource "aws_lb" "example" {
  name               = "alb-example"
  subnets           = aws_subnet.example[*].id
  security_groups   = [aws_security_group.alb_sg.id]
  idle_timeout      = 60
  enable_deletion_protection = false
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.example.arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type = "authenticate-oidc"
    authenticate_oidc {
      issuer    = "https://example.com"
      audience  = "example-app"
      authorization_endpoint = "https://example.com/authorize"
      token_endpoint         = "https://example.com/token"
      jwks_uri               = "https://example.com/jwks"
      client_id              = "example-client-id"
      client_secret          = "example-client-secret"
      session_timeout        = 300
      authenticate_view {
        path = "/auth"
      }
    }
  }
}

resource "aws_iam_oidc_provider" "oidc_provider" {
  url = "https://example.com"
  client_id_list = ["example-client-id"]
  client_id_list = ["example-client-id"]
  thumbprint_list = ["example-thumbprint"]
}

resource "aws_iam_role" "oidc_role" {
  name = "oidc-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = "arn:aws:iam::123456789012:oidc-provider/example.com"
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringLike = {
          "example.com:sub" = "example-sub"
        }
      }
    }]
  })
}
