LLM Output #0:
**Description:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) along with a target group. The load balancer will forward traffic to a target group, which can be associated with EC2 instances or other services. The configuration includes a default target group, a load balancer, and necessary security groups. The load balancer is created in the `us-east-1` region, and the target group is set up with a default health check configuration.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "load_balancer_name" {
  description = "Name of the Application Load Balancer"
  default     = "my-alb"
}

variable "target_group_name" {
  description = "Name of the target group"
  default     = "my-target-group"
}

variable "vpc_id" {
  description = "ID of the VPC to deploy the load balancer in"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the load balancer"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "health_check_path" {
  description = "Path for health check"
  default     = "/health"
}

variable "health_check_port" {
  description = "Port for health check"
  default     = "80"
}

variable "health_check_protocol" {
  description = "Protocol for health check"
  default     = "HTTP"
}

variable "health_check_interval" {
  description = "Interval for health check in seconds"
  default     = "30"
}

variable "health_check_timeout" {
  description = "Timeout for health check in seconds"
  default     = "5"
}

variable "health_check_unhealthy_threshold" {
  description = "Unhealthy threshold for health check"
  default     = "3"
}

resource "aws_lb" "alb" {
  name               = var.load_balancer_name
  subnets           = var.subnet_ids
  security_groups    = ["sg-12345678"] # Replace with your security group ID
  idle_timeout       = 60
  enable_deletion_protection = false
}

resource "aws_lb_target_group" "tg" {
  name                = var.target_group_name
  port                = 80
  protocol            = "HTTP"
  vpc_id              = var.vpc_id
  health_check_path   = var.health_check_path
  health_check_port   = var.health_check_port
  health_check_protocol = var.health_check_protocol
  health_check_interval = var.health_check_interval
  health_check_timeout = var.health_check_timeout
  health_check_unhealthy_threshold = var.health_check_unhealthy_threshold
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.tg.arn
  }
}
```

