LLM Output #0:
**Description:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with an associated Target Group that uses IP-based targets. The Load Balancer is configured to listen on HTTP (port 80) and forward traffic to a target group that accepts IP addresses as targets. The configuration includes a default VPC, a security group, and the necessary IAM roles for the Load Balancer to function properly. The Load Balancer is deployed in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the Load Balancer."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the Load Balancer."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the Load Balancer."
  default     = "sg-12345678"
}

variable "target_group_name" {
  description = "The name of the target group."
  default     = "ip-target-group"
}

variable "load_balancer_name" {
  description = "The name of the Load Balancer."
  default     = "ip-load-balancer"
}

resource "aws_lb" "ip_load_balancer" {
  name               = var.load_balancer_name
  subnets           = var.subnet_ids
  security_groups    = [var.security_group_id]
  idle_timeout       = 30
  enable_deletion_protection = false
}

resource "aws_lb_target_group" "ip_target_group" {
  name        = var.target_group_name
  port        = 80
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  target_type = "ip"

  health_check {
    path                = "/"
    protocol            = "HTTP"
    port                = 80
    interval_seconds    = 30
    timeout_seconds     = 5
    healthy_threshold   = 5
    unhealthy_threshold = 3
  }
}

resource "aws_lb_listener" "ip_listener" {
  load_balancer_arn = aws_lb.ip_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.ip_target_group.arn
  }
}
```

