LLM Output #0:
**Description:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) with a Lambda target group. The ALB will route traffic to a Lambda function via the target group. The configuration includes:

- A VPC with a public subnet.
- A security group allowing HTTP traffic.
- A Lambda function (as a placeholder, not deployed).
- A target group for Lambda.
- An Application Load Balancer with a listener that routes traffic to the Lambda target group.
- IAM roles and policies for the Lambda function and ALB.

Variables are provided with default values for flexibility.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  default     = "lambda-target"
}

variable "lambda_arn" {
  description = "ARN of the Lambda function"
  default     = "arn:aws:lambda:us-east-1:123456789012:function:lambda-target"
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "alb-security-group"
}

variable "alb_name" {
  description = "Name of the Application Load Balancer"
  default     = "lambda-alb"
}

variable "target_group_name" {
  description = "Name of the target group"
  default     = "lambda-target-group"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_security_group" "alb_sg" {
  name        = var.security_group_name
  description = "Allow HTTP traffic to ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "alb" {
  name               = var.alb_name
  subnets           = [aws_subnet.public.id]
  security_groups   = [aws_security_group.alb_sg.id]
  idle_timeout      = 30
  enable_deletion_protection = false
}

resource "aws_lb_target_group" "lambda_target" {
  name        = var.target_group_name
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "lambda"

  tags = {
    Name = var.target_group_name
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda_target.arn
  }
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_policies" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}
```

---

**Note:** This configuration assumes the Lambda function is already created and has the correct ARN. You can replace the `lambda_arn` variable with the actual ARN of your Lambda function.

