**Description:**

This Terraform configuration creates an Application Load Balancer (ALB) and an associated Target Group. The Load Balancer is configured to listen on HTTP port 80, and the Target Group is set up to route traffic to an EC2 instance (or instances) in a specified subnet. The configuration includes a default VPC, subnet, security group, and IAM role for the EC2 instance. The ALB is deployed in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "instance_type" {
  description = "Type of EC2 instance to use as a target"
  default     = "t2.micro"
}

variable "security_group_name" {
  description = "Name of the security group for the EC2 instance"
  default     = "alb-target-sg"
}

variable "alb_name" {
  description = "Name of the Application Load Balancer"
  default     = "alb-target-group-demo"
}

variable "target_group_name" {
  description = "Name of the target group"
  default     = "alb-target-group-demo"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "alb_sg" {
  name        = var.security_group_name
  description = "Allow HTTP traffic to ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "alb-target-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_role_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
}

resource "aws_instance" "target" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI
  instance_type = var.instance_type
  subnet_id     = aws_subnet.main.id
  vpc_security_group_ids = [aws_security_group.alb_sg.id]
  iam_instance_profile = aws_iam_role.ec2_role.name

  tags = {
    Name = "alb-target-instance"
  }
}

resource "aws_lb" "alb" {
  name               = var.alb_name
  subnets           = [aws_subnet.main.id]
  security_groups   = [aws_security_group.alb_sg.id]
  idle_timeout      = 30
  enable_deletion_protection = false
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    forward {
      target_group_arns = [aws_lb_target_group.target.arn]
    }
  }
}

resource "aws_lb_target_group" "target" {
  name        = var.target_group_name
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    path                = "/health"
    protocol            = "HTTP"
    port                = "80"
    interval_seconds    = 30
    timeout_seconds     = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }
}
