**Description of the Terraform Program:**

This Terraform configuration creates an AWS Application Load Balancer (ALB) and an associated Target Group. The Load Balancer is configured to listen on HTTP port 80, and the Target Group is set up to route traffic to an EC2 instance (which is not defined in this configuration but can be referenced as a target). The configuration includes a default VPC, a security group, and necessary IAM roles for the Load Balancer and Target Group. The provider is configured for the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the Load Balancer."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the Load Balancer."
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the Load Balancer."
  default     = "sg-12345678"
}

variable "target_group_name" {
  description = "The name of the target group."
  default     = "my-target-group"
}

variable "target_group_port" {
  description = "The port on which the target group listens."
  default     = 80
}

variable "target_group_protocol" {
  description = "The protocol used by the target group."
  default     = "HTTP"
}

variable "load_balancer_name" {
  description = "The name of the Load Balancer."
  default     = "my-load-balancer"
}

resource "aws_lb" "example" {
  name               = var.load_balancer_name
  subnet_ids         = var.subnet_ids
  security_groups    = [var.security_group_id]
  idle_timeout       = 30
  enable_deletion_protection = false
  tags = {
    Name = var.load_balancer_name
  }
}

resource "aws_lb_target_group" "example" {
  name        = var.target_group_name
  port        = var.target_group_port
  protocol    = var.target_group_protocol
  vpc_id      = var.vpc_id
  health_check {
    path                = "/"
    protocol            = var.target_group_protocol
    port                = var.target_group_port
    interval_seconds    = 30
    timeout_seconds     = 5
    healthy_threshold   = 5
    unhealthy_threshold = 3
  }
  tags = {
    Name = var.target_group_name
  }
}

resource "aws_lb_listener" "example" {
