  subnet_ids = var.rds_db_subnet_ids
  tags = {
    Name = "db-subnet-group"
  }
}

resource "aws_security_group" "db_security_group" {
  name        = var.rds_db_security_group_name
  description = "Allow access to RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = var.rds_db_port
    to_port     = var.rds_db_port
    protocol    = "tcp"
    cidr_blocks = [var.rds_db_allow_ip_range]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-security-group"
  }
}

resource "aws_rds_instance" "main" {
  identifier              = var.rds_instance_name
  engine                  = var.rds_db_engine
  instance_class          = var.rds_db_instance_class
  allocated_storage      = var.rds_db_allocated_storage
  storage_type            = "gp2"
  db_name                 = "mydb"
  username                = var.rds_db_username
  password               = var.rds_db_password
  port                    = var.rds_db_port
  db_subnet_group_name    = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.db_security_group.id]
  publicly_accessible     = true
  tags = {
    Name = "my-rds-instance"
  }
}
