**Description of the Terraform Program:**

This Terraform configuration creates a basic AWS SQL database using Amazon RDS. It sets up a single Aurora MySQL database instance in a specified AWS region. The configuration includes:

- A VPC with a public subnet.
- A security group allowing access to the database from a specific IP range.
- An IAM role for the RDS instance to manage database access.
- A database instance with a specified username, password, and database name.
- A default subnet ID and security group ID for simplicity.

The configuration is designed to be deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "security_group_ip_range" {
  description = "IP range allowed to access the database"
  default     = "0.0.0.0/0"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance"
  default     = "my-aurora-db"
}

variable "db_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  default     = "securepassword123"
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydb"
}

variable "db_engine" {
  description = "Database engine (e.g., aurora-mysql)"
  default     = "aurora-mysql"
}

variable "db_engine_version" {
  description = "Database engine version"
  default     = "5.7.mysql_aurora.2.06.1"
}

variable "db_instance_class" {
  description = "Instance class for the RDS instance"
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage in GB"
  default     = "20"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group"
  description = "Allow access to the database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
