**Description of the Terraform Program:**

This Terraform configuration creates a memory-optimized PostgreSQL instance on AWS. It provisions an EC2 instance with an IAM role that allows it to access AWS services, installs PostgreSQL, and configures it for memory-optimized performance. The instance is launched in a specified AWS region, and all necessary resources are defined within the configuration to ensure it is deployable without external dependencies.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_type" {
  description = "The EC2 instance type for the PostgreSQL server."
  default     = "r5.large"
}

variable "ami_id" {
  description = "The AMI ID to use for the EC2 instance."
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (2023.09)
}

variable "key_name" {
  description = "The name of the EC2 key pair to use."
  default     = "my-key-pair"
}

variable "security_group_name" {
  description = "The name of the security group to associate with the instance."
  default     = "postgres-sg"
}

variable "postgres_version" {
  description = "The version of PostgreSQL to install."
  default     = "15"
}

resource "aws_security_group" "postgres_sg" {
  name        = var.security_group_name
  description = "Allow PostgreSQL access"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.security_group_name
  }
}

resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "postgres-vpc"
  }
}

resource "aws_subnet" "default" {
  vpc_id            = aws_vpc.default.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "postgres-subnet"
  }
}

resource "aws_internet_gateway" "default" {
  vpc_id = aws_vpc.default.id
  tags = {
    Name = "postgres-igw"
  }
}

resource "aws_route_table" "default" {
  vpc_id = aws_vpc.default.id
  tags = {
    Name = "postgres-rt"
  }

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.default.id
  }
}

resource "aws_route_table_association" "default" {
  subnet_id      = aws_subnet.default.id
  route_table_id = aws_route_table.default.id
}

resource "aws_iam_role" "postgres_role" {
  name = "postgres_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "postgres_policy" {
  role       = aws_iam_role.postgres_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ReadOnlyAccess"
}

resource "aws_instance" "postgres_instance" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = aws_subnet.default.id
  security_groups = [aws_security_group.postgres_sg.name]
  iam_instance_profile = aws_iam_instance_profile.postgres_profile.name
  tags = {
    Name = "postgres-instance"
  }

  user_data = <<-EOF
    #!/bin/bash
    sudo yum update -y
    sudo yum install -y https://download.postgresql.org/pub/repos/yum/reporpms/EL-8-x86_64/pgdg-redhat-repo-15-2.noarch.rpm
    sudo yum install -y postgresql-server postgresql-contrib
    sudo /usr/pgsql-15/bin/postgresql-15-setup initdb
    sudo systemctl enable postgresql-15
    sudo systemctl start postgresql-15
    sudo sed -i "s/#shared_buffers = 128MB/shared_buffers = 2GB/" /var/lib/pgsql/15/data/postgresql.conf
    sudo sed -i "s/#effective_cache_size = 1GB/effective_cache_size = 4GB/" /var/lib/pgsql/15/data/postgresql.conf
    sudo sed -i "s/#work_mem = '1MB'/work_mem = '4MB'/" /var/lib/pgsql/15/data/postgresql.conf
    sudo sed -i "s/#maintenance_work_mem = '16MB'/maintenance_work_mem = '256MB'/" /var/lib/pgsql/15/data/postgresql.conf
    sudo systemctl restart postgresql-15
  EOF
}

resource "aws_iam_instance_profile" "postgres_profile" {
  name = "postgres_instance_profile"
  role = aws_iam_role.postgres_role.name
}
