This Terraform configuration creates an AWS RDS MySQL instance. The instance is configured with a specified instance class, storage, and security group. The configuration ensures that any changes made to the instance (such as scaling or modifying parameters) are applied immediately. The instance is set up with a default password and a publicly accessible endpoint for easy access. An IAM role is created to allow the RDS instance to access necessary AWS services, and the configuration includes default values for all variables to ensure it is deployable out of the box.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "instance_class" {
  description = "The instance class for the RDS MySQL instance."
  default     = "db.t3.micro"
}

variable "storage_size" {
  description = "The storage size in GB for the RDS MySQL instance."
  default     = 20
}

variable "db_name" {
  description = "The name of the database to create."
  default     = "mydb"
}

variable "db_username" {
  description = "The username for the database."
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database."
  default     = "securepassword123"
}

variable "vpc_id" {
  description = "The ID of the VPC to deploy the RDS instance into."
  default     = "vpc-12345678"
}

variable "security_group_id" {
  description = "The ID of the security group to associate with the RDS instance."
  default     = "sg-12345678"
}

variable "allow_public_access" {
  description = "Whether to allow public access to the RDS instance."
  default     = true
}

resource "aws_rds_instance" "mysql_instance" {
  identifier           = "mydb-instance"
  instance_class       = var.instance_class
  allocated_storage   = var.storage_size
  engine               = "mysql"
  engine_version       = "8.0.33"
  db_name              = var.db_name
  username             = var.db_username
  password             = var.db_password
  vpc_security_group_ids = [var.security_group_id]
  publicly_accessible  = var.allow_public_access
  skip_final_snapshot  = true
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds_iam_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
