**Description of the Terraform Program:**

This Terraform configuration creates an AWS RDS SQL database instance and a read replica of it. The configuration includes:

- A VPC with a public subnet and route table.
- A security group allowing access to the database from specific IP ranges.
- An RDS SQL database instance in the primary region.
- A read replica of the database in a different region (cross-region replication).
- IAM roles and policies for the RDS instances to ensure proper access and permissions.
- Default variables for region, database name, username, password, and replica region.

The configuration is designed to be deployable with Terraform 1.9.8 and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region where the primary database will be created."
  default     = "us-east-1"
}

variable "replica_region" {
  description = "The AWS region where the read replica will be created."
  default     = "us-west-2"
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "database_name" {
  description = "The name of the database."
  default     = "mydb"
}

variable "db_username" {
  description = "The username for the database."
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database."
  default     = "securepassword123"
}

variable "db_instance_class" {
  description = "The instance class for the database."
  default     = "db.t3.micro"
}

variable "db_engine" {
  description = "The database engine (e.g., mysql5.7, postgresql14)."
  default     = "mysql5.7"
}

variable "db_port" {
  description = "The port for the database."
  default     = 3306
}

variable "allowed_ip_ranges" {
  description = "List of IP ranges allowed to connect to the database."
  default     = ["0.0.0.0/0"]
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main_vpc.id
}

resource "aws_route_table_association" "public_route_table_association" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_security_group" "db_security_group" {
  name        = "db-security-group"
  description = "Allow access to the database"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = var.db_port
    to_port     = var.db_port
    protocol    = "tcp"
    cidr_blocks = var.allowed_ip_ranges
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "primary_db" {
  allocated_storage    = 20
  storage_type         = "gp2"
  engine               = var.db_engine
  instance_class       = var.db_instance_class
  name                 = var.database_name
  username             = var.db_username
  password             = var.db_password
  port                 = var.db_port
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  skip_final_snapshot  = true
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "db-subnet-group"
  subnet_ids = [aws_subnet.public_subnet.id]
}

resource "aws_db_instance" "replica_db" {
  allocated_storage    = 20
  storage_type         = "gp2"
  engine               = var.db_engine
  instance_class       = var.db_instance_class
  name                 = var.database_name
  username             = var.db_username
  password             = var.db_password
  port                 = var.db_port
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  skip_final_snapshot  = true
  replication_source_identifier = aws_db_instance.primary_db.id
  region                = var.replica_region
}

resource "aws_iam_role" "rds_role" {
  name = "rds_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_role_policy" {
  role       = aws_iam_role.rds_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
}
```

---

**Note:** This configuration assumes that the replica region is different from the primary region. You may need to adjust the `replica_region` variable based on your AWS account's region availability. Also, ensure that the IAM role and policies are correctly set up for cross-region replication.

