**Description of the Terraform Program:**

This Terraform configuration creates an AWS RDS database instance that is restored from a backup stored in Amazon S3. The configuration includes:

- A VPC with a public subnet.
- A security group allowing access to the RDS instance.
- An IAM role and policy to grant the RDS instance permission to access the S3 bucket.
- An S3 bucket to store the database backup.
- An RDS instance configured to restore from the S3 backup.

The configuration uses default values for variables where necessary and ensures all resources are declared and properly referenced.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket containing the database backup"
  default     = "db-backup-bucket"
}

variable "rds_instance_name" {
  description = "Name of the RDS instance"
  default     = "db-restore-instance"
}

variable "rds_instance_class" {
  description = "Instance class for the RDS instance"
  default     = "db.t3.micro"
}

variable "rds_engine" {
  description = "Database engine (e.g., mysql, postgres)"
  default     = "mysql"
}

variable "rds_engine_version" {
  description = "Database engine version"
  default     = "8.0.33"
}

variable "rds_master_username" {
  description = "Master username for the RDS instance"
  default     = "admin"
}

variable "rds_master_password" {
  description = "Master password for the RDS instance"
  default     = "securepassword123"
}

variable "rds_backup_s3_bucket_arn" {
  description = "ARN of the S3 bucket containing the backup"
  default     = "arn:aws:s3:::db-backup-bucket"
}

variable "rds_backup_s3_key" {
  description = "S3 key path to the backup file"
  default     = "backups/db-restore.sql"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr
  map_public_ip_on_launch = true
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  description = "Allow access to RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_role" {
  name = "rds-restore-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "rds_s3_access" {
  name = "rds-s3-access-policy"
  role = aws_iam_role.rds_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        "${var.rds_backup_s3_bucket_arn}/*",
        "${var.rds_backup_s3_bucket_arn}"
      ]
    }]
  })
}

resource "aws_iam_instance_profile" "rds_instance_profile" {
  name = "rds-restore-instance-profile"
  role = aws_iam_role.rds_role.id
}

resource "aws_s3_bucket" "backup_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
}

resource "aws_rds_cluster" "restore_cluster" {
  cluster_identifier = var.rds_instance_name
  engine              = var.rds_engine
  engine_version      = var.rds_engine_version
  master_username     = var.rds_master_username
  master_password     = var.rds_master_password
  backup_retention_period = 7
  preferred_backup_window = "07:00-08:00"
  storage_type        = "gp2"
  instance_class      = var.rds_instance_class
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  iam_role_arn        = aws_iam_role.rds_role.arn
  restore_from = {
    s3 = {
      bucket = var.rds_backup_s3_bucket_arn
      key    = var.rds_backup_s3_key
    }
  }
}
```

