**Description of the Terraform Program:**

This Terraform configuration creates an AWS Aurora MySQL DB cluster that supports storage autoscaling. The configuration includes:

- A VPC with a public subnet.
- A security group allowing access to the DB cluster.
- An Aurora MySQL DB cluster with storage autoscaling enabled.
- An IAM role for the DB cluster to allow storage autoscaling.
- A default subnet ID and security group ID for simplicity.

The configuration is designed to be deployable in AWS using Terraform version 1.9.8 or higher and the `hashicorp/aws` provider version 5.75 or higher.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the DB cluster."
  default     = "vpc-0123456789abcdef0"
}

variable "subnet_id" {
  description = "The ID of the subnet to use for the DB cluster."
  default     = "subnet-0123456789abcdef0"
}

variable "security_group_id" {
  description = "The ID of the security group to use for the DB cluster."
  default     = "sg-0123456789abcdef0"
}

variable "db_cluster_identifier" {
  description = "The identifier for the DB cluster."
  default     = "autoscaling-db-cluster"
}

variable "db_instance_identifier" {
  description = "The identifier for the DB instance."
  default     = "autoscaling-db-instance"
}

variable "db_engine_version" {
  description = "The version of the database engine to use."
  default     = "mysql8.0"
}

variable "db_master_username" {
  description = "The master username for the database."
  default     = "admin"
}

variable "db_master_password" {
  description = "The master password for the database."
  default     = "SecureP@ssw0rd!"
}

variable "db_instance_class" {
  description = "The instance class for the DB instance."
  default     = "db.r5.large"
}

variable "db_allocated_storage" {
  description = "The initial allocated storage in GB."
  default     = "20"
}

variable "db_max_allocated_storage" {
  description = "The maximum allocated storage in GB."
  default     = "100"
}

resource "aws_db_cluster" "example" {
  identifier          = var.db_cluster_identifier
  engine              = "aurora-mysql"
  engine_version      = var.db_engine_version
  master_username     = var.db_master_username
  master_password     = var.db_master_password
  db_subnet_group_name = "default"
  vpc_security_group_ids = [var.security_group_id]
  storage_type        = "gp2"
  storage_encrypted   = true
  port                = 3306
  backup_retention_period = 7
  preferred_backup_window = "07:00-08:00"
  skip_final_snapshot = true
  storage_autoscaling {
    enabled = true
    max_allocated_storage = var.db_max_allocated_storage
  }
}

resource "aws_db_instance" "example" {
  identifier          = var.db_instance_identifier
  db_cluster_identifier = aws_db_cluster.example.id
  instance_class      = var.db_instance_class
  allocated_storage   = var.db_allocated_storage
