  vpc_security_group_ids = [var.security_group_id]
  db_subnet_group_name = "default"
  storage_type        = "gp2"
  storage_encrypted   = true
  port                = 3306
  backup_retention_period = 7
  preferred_backup_window = "07:00-08:00"
  skip_final_snapshot = true
  storage_autoscaling {
    enabled = true
    max_allocated_storage = var.db_max_allocated_storage
  }
}

resource "aws_iam_role" "db_cluster_role" {
  name = "db_cluster_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "db_cluster_role_attachment" {
  role       = aws_iam_role.db_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSClusterRole"
}
```

---

**Note:** This configuration assumes that the default VPC and subnet are available in the specified region. In production, you should replace the default values with actual VPC and subnet IDs. Additionally, the IAM role is attached to allow the DB cluster to manage storage autoscaling.

