**Description of the Terraform Program:**

This Terraform configuration creates an AWS RDS database instance that uses AWS Secrets Manager to manage the master password. The master password is stored in a Secrets Manager secret, and the RDS instance is configured to use that secret. A default AWS KMS key is used to encrypt the secret. The configuration includes:

- An AWS Secrets Manager secret for the master password.
- An AWS KMS key (default) for encrypting the secret.
- An AWS RDS database instance that references the secret for its master password.
- All necessary IAM roles and policies to allow RDS to access the secret and KMS key.

The configuration is set up in the `us-east-1` region and uses default values where applicable.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "secret_name" {
  description = "Name of the AWS Secrets Manager secret to store the master password."
  default     = "rds-master-password"
}

variable "kms_key_arn" {
  description = "ARN of the KMS key to use for encrypting the secret."
  default     = "arn:aws:kms:us-east-1:123456789012:key/abcd1234-a123-4567-8abc-def123456789"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS database instance."
  default     = "my-rds-instance"
}

variable "db_engine" {
  description = "Database engine to use (e.g., mysql, postgres)."
  default     = "mysql"
}

variable "db_version" {
  description = "Database engine version."
  default     = "8.0"
}

variable "db_username" {
  description = "Database username."
  default     = "admin"
}

variable "db_password" {
  description = "Database password (used to create the secret)."
  default     = "securepassword123"
}

variable "db_instance_class" {
  description = "Database instance class."
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage in GB."
  default     = 20
}

resource "aws_secretsmanager_secret" "rds_master_password" {
  name = var.secret_name
}

resource "aws_secretsmanager_secret_version" "rds_master_password_version" {
  secret_id = aws_secretsmanager_secret.rds_master_password.id
  plaintext = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}

resource "aws_kms_key" "default_kms_key" {
  description = "Default KMS key for encrypting secrets"
}

resource "aws_rds_cluster" "example" {
  cluster_identifier = var.db_instance_identifier
  engine             = var.db_engine
  engine_version     = var.db_version
  master_username    = var.db_username
  master_password    = var.db_password
  db_instance_class  = var.db_instance_class
  allocated_storage  = var.db_allocated_storage
  storage_type       = "gp2"
  backup_retention_days = 7
  skip_final_snapshot = true

  # IAM role for RDS to access Secrets Manager
  iam_role_arn = aws_iam_role.rds_secret_access_role.arn

  # Enable encryption with KMS key
  storage_encrypted = true
  kms_key_id        = aws_kms_key.default_kms_key.arn
}

resource "aws_iam_role" "rds_secret_access_role" {
  name = "rds-secret-access-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "rds.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_secret_access_policy" {
  role       = aws_iam_role.rds_secret_access_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
}

resource "aws_iam_role_policy" "rds_secret_access_policy" {
  name = "rds-secret-access-policy"
  role = aws_iam_role.rds_secret_access_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "secretsmanager:GetSecretValue",
        "secretsmanager:DescribeSecret"
      ]
      Resource = "*"
    }]
  })
}
