}

resource "aws_iam_role" "rds_db_instance_role" {
  name = "rds-db-instance-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "rds.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_db_instance_role_policy" {
  role       = aws_iam_role.rds_db_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSDBInstanceRole"
}

resource "aws_rds_cluster" "rds_cluster" {
  cluster_identifier = var.rds_db_instance_identifier
  engine             = var.rds_db_engine
  engine_version     = var.rds_db_version
  instance_class     = var.rds_db_instance_class
  master_username    = var.rds_db_master_username
  master_password    = var.rds_db_master_password
  allocated_storage  = var.rds_db_allocated_storage
  vpc_security_group_ids = var.rds_db_vpc_security_group_ids
  storage_encrypted  = true
  kms_key_id         = aws_kms_key.secret_kms_key.arn
  secret_arn         = aws_secretsmanager_secret.rds_secret.arn
}

data "aws_caller_identity" "current" {}
```

---

**Note:** This configuration assumes that the necessary VPC and subnet group already exist. If not, you would need to create them separately. The RDS instance is configured to use the secret from Secrets Manager and the KMS key for encryption. The IAM role allows the RDS instance to access the secret.

