variable "snapshot_identifier" {
  description = "The identifier for the RDS snapshot."
  default     = "my-db-snapshot"
}

variable "db_engine_version" {
  description = "The version of the MySQL engine to use."
  default     = "mysql-8.0"
}

variable "db_instance_class" {
  description = "The compute and memory capacity of the DB instance."
  default     = "db.t3.micro"
}

variable "db_username" {
  description = "The master username for the DB instance."
  default     = "admin"
}

variable "db_password" {
  description = "The master password for the DB instance."
  default     = "SecureP@ssw0rd!"
}

variable "db_subnet_group_name" {
  description = "The name of the DB subnet group."
  default     = "my-db-subnet-group"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the DB subnet group."
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs to use for the DB subnet group."
  default     = ["subnet-12345678", "subnet-87654321"]
}

