**Description:**

This Terraform configuration creates an AWS Elastic File System (EFS) with a specified lifecycle policy. The lifecycle policy defines how long files should be retained before being deleted. The configuration includes:

- A VPC and subnet to host the EFS.
- A security group to allow access to the EFS.
- An EFS file system with a lifecycle policy configured.
- An IAM role and policy to allow EC2 instances to access the EFS.
- Default values for variables to ensure the configuration is deployable without additional input.

The EFS is created in the `us-east-1` region, and the lifecycle policy is set to delete files after 30 days by default.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC to use for the EFS."
  default     = "vpc-12345678"
}

variable "subnet_id" {
  description = "The ID of the subnet to use for the EFS."
  default     = "subnet-12345678"
}

variable "lifecycle_policy_days" {
  description = "The number of days to retain files before deletion."
  default     = 30
}

variable "iam_role_name" {
  description = "The name of the IAM role for EFS access."
  default     = "EFSAccessRole"
}

resource "aws_vpc" "efs_vpc" {
  id           = var.vpc_id
  cidr_block   = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "efs_subnet" {
  id            = var.subnet_id
  cidr_block    = "10.0.1.0/24"
  vpc_id        = aws_vpc.efs_vpc.id
  map_public_ip_on_launch = false
}

resource "aws_security_group" "efs_sg" {
  name        = "efs-sg"
  description = "Allow access to EFS"
  vpc_id      = aws_vpc.efs_vpc.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "efs_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "efs_policy" {
  name = "${var.iam_role_name}-policy"
  role = aws_iam_role.efs_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "elasticfilesystem:DescribeFileSystems",
        "elasticfilesystem:CreateMountTarget",
        "elasticfilesystem:DeleteMountTarget",
        "elasticfilesystem:DescribeMountTargets",
        "elasticfilesystem:MountTargetState",
        "elasticfilesystem:CreateFileSystem",
        "elasticfilesystem:DeleteFileSystem",
        "elasticfilesystem:DescribeLifecyclePolicies",
        "elasticfilesystem:PutLifecyclePolicy",
      ]
      Resource = "*"
    }]
  })
}

resource "aws_efs_file_system" "efs" {
  lifecycle_policy {
    transition_to_ia_days = 0
    transition_to_archive_days = 0
    delete_days = var.lifecycle_policy_days
  }

  tags = {
    Name = "EFS-Lifecycle-Example"
  }
}

resource "aws_efs_mount_target" "efs_mount" {
  file_system_id = aws_efs_file_system.efs.id
  subnet_id      = aws_subnet.efs_subnet.id
  security_group_id = aws_security_group.efs_sg.id
}
```

---

**Note:** This configuration assumes that the VPC and subnet already exist. If you want to create them dynamically, you can replace the `vpc_id` and `subnet_id` variables with `aws_vpc` and `aws_subnet` resources.

