**Description of the Terraform Program:**

This Terraform configuration creates a VPC in AWS with multiple public subnets. Each subnet is associated with a route table that is configured for internet access via an Internet Gateway. The configuration includes:

- A VPC with a specified CIDR block.
- Multiple public subnets in different Availability Zones.
- An Internet Gateway attached to the VPC.
- A route table with a default route (`0.0.0.0/0`) pointing to the Internet Gateway.
- Each public subnet is associated with the route table to enable internet access.

The configuration uses default values for variables where necessary and includes a valid AWS provider configuration in the `us-east-1` region.

---

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_count" {
  description = "The number of public subnets to create."
  default     = 3
}

variable "availability_zones" {
  description = "List of availability zones to use for subnets."
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block       = "0.0.0.0/0"
    gateway_id       = aws_internet_gateway.main.id
    propagate_table  = true
  }
}

resource "aws_subnet" "public" {
  count             = var.public_subnet_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  map_public_ip_on_launch = true
  availability_zone = var.availability_zones[count.index]

  route_table_id = aws_route_table.public.id
}
```

