This Terraform configuration sets up a dedicated-tenancy AWS VPC with DNS support and hostnames enabled. It includes an Internet Gateway for internet access and a Route Table that allows outbound internet traffic. All resources are tagged with a variable name, which can be customized as needed. The configuration uses the AWS provider and ensures all resources are properly defined and tagged.

---

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name for the VPC"
  default     = "dedicated-tenancy-vpc"
}

variable "tag_name" {
  description = "Tag name to apply to all resources"
  default     = "Production"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = var.vpc_name
    TagName     = var.tag_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name        = "${var.vpc_name}-igw"
    TagName     = var.tag_name
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name        = "${var.vpc_name}-rtb"
    TagName     = var.tag_name
  }

  route {
    cidr_block         = "0.0.0.0/0"
    gateway_id         = aws_internet_gateway.main.id
    route_table_id     = aws_route_table.main.id
  }
}

resource "aws_route_table_association" "main" {
  route_table_id = aws_route_table.main.id
  subnet_id      = aws_subnet.main.id
}
