**Description of the Terraform Program:**

This Terraform configuration sets up a VPC in a specified AWS region with the following components:

- A VPC with a CIDR block.
- Two subnets in different availability zones (AZs) within the VPC.
- An Internet Gateway attached to the VPC.
- A Route Table with a route to the Internet Gateway for internet access.
- A Security Group that allows inbound traffic on the default ports for MySQL (3306) and PostgreSQL (5432) from any IP address.
- A Database Subnet Group that includes both subnets for use with AWS RDS or similar services.

The configuration uses default values for variables where necessary and includes a valid AWS provider configuration in a specified region.

---

```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be overridden with a variable
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "List of availability zones for subnets"
  default     = ["us-west-2a", "us-west-2b"]
}

variable "database_subnet_group_name" {
  description = "Name for the database subnet group"
  default     = "my-db-subnet-group"
}

variable "security_group_name" {
  description = "Name for the security group"
  default     = "db-access-sg"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = var.availability_zones[0]
  map_public_ip_on_launch = true
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = var.availability_zones[1]
  map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block           = "0.0.0.0/0"
    gateway_id           = aws_internet_gateway.igw.id
    egress_only_gateway_id = ""
  }
}

resource "aws_route_table_association" "public_route_table_assoc_1" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table_association" "public_route_table_assoc_2" {
  subnet_id      = aws_subnet.public_subnet_2.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_security_group" "db_access_sg" {
  name        = var.security_group_name
  description = "Allow access to MySQL and PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = var.database_subnet_group_name
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
}
