**Description of the Terraform Program:**

This Terraform configuration creates an **Egress-Only Internet Gateway (EIGW)** associated with a specified **VPC**, enabling IPv6-enabled instances within that VPC to access the internet. The EIGW allows outbound internet traffic but **does not allow inbound traffic**, ensuring that the VPC remains secure from external access. The configuration includes:

- A **VPC** with IPv6 CIDR block.
- An **Egress-Only Internet Gateway** attached to the VPC.
- A **main route table** with a route to the EIGW for IPv6 traffic.
- Default values for variables to ensure deployability without manual input.

---

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name of the VPC"
  default     = "my-vpc"
}

variable "vpc_cidr_ipv4" {
  description = "IPv4 CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "vpc_cidr_ipv6" {
  description = "IPv6 CIDR block for the VPC"
  default     = "2001:db8::/32"
}

variable "availability_zone" {
  description = "Availability zone for the VPC"
  default     = "us-west-2a"
}

resource "aws_vpc" "main" {
  count             = 1
  cidr_block        = var.vpc_cidr_ipv4
  ipv6_cidr_block   = var.vpc_cidr_ipv6
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  count             = 1
  vpc_id            = aws_vpc.main.id
  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_egress_only_internet_gateway" "main" {
  count             = 1
  vpc_id            = aws_vpc.main.id
  tags = {
    Name = "${var.vpc_name}-eigw"
  }
}

resource "aws_route_table" "main" {
  count             = 1
  vpc_id            = aws_vpc.main.id
  route {
    ipv6_destination_cidr_block = "::/0"
    egress_only_internet_gateway_id = aws_egress_only_internet_gateway.main.id
  }
  tags = {
    Name = "${var.vpc_name}-rtb"
  }
}

resource "aws_route_table_association" "main" {
  count             = 1
  route_table_id    = aws_route_table.main.id
  subnet_id         = aws_subnet.main.id
}
```

